window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["med:med-cirurgia-med-cir-02"]={"block":"med:med-cirurgia-med-cir-02","label":"MED · MED CIR 02","count":426,"questions":[{"id":"med-cirurgia-med-cir-02-345508","number":"345508","sourceNumber":"345508","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Masculino, 20 anos, apresenta quadro de dor abdominal em andar superior e diarréia\nde aspecto secretório. Endoscopia digestiva\nalta mostra extensa lesão ulcerada duodenal com teste\nurease negativo. Ultrassom abdominal e hemograma normais. Gastrinemia sérica de 500 pg/mL\n(VR: até 100 pg/mL). Assinale a alternativa que mostre o local mais provável de origem desta\ndoença:","options":{"A":"Pâncreas.","B":"Duodeno.","C":"Apêndice cecal.","D":"Corpo gástrico."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-251873","number":"251873","sourceNumber":"251873","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A principal causa de hemorragia digestiva alta não varicosa é:","options":{"A":"Úlcera péptica.","B":"Gastrite atrófica.","C":"Linfoma tipo MALT.","D":"Gastroparesia."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-251947","number":"251947","sourceNumber":"251947","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente ?, 33 anos, com queixas de pirose e regurgitamento pós-prandial de evolução\ncrônica. Há 3 anos foi diagnosticado pela endoscopia digestiva alta: esofagite grau A de Los\nAngeles, hiato esofagiano alargado e transição esôfago gástrica 3 cm acima do pinçamento\ndiafragmático. Melhora com uso de inibidores de bomba de prótons, medidas posturais e dietéticas,\nmas ao término dos tratamentos apresenta recidiva precoce dos sintomas. Qual sua conduta?","options":{"A":"Solicitar Manometria Esofágica e caso normal indicar tratamento cirúrgico.","B":"Solicitar Phmetria Esofágica e caso anormal indicar tratamento cirúrgico.","C":"Solicitar esofagografia e caso confirme o diagnóstico indicar tratamento cirúrgico.","D":"Indicar tratamento cirúrgico."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-217665","number":"217665","sourceNumber":"217665","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente, sexo masculino, 35 anos, com dor epigástrica súbita de forte intensidade, que\nse irradiou inicialmente para hipogástrio e\nem seguida para todo abdome, evolução de 2 horas.\n\nVinha fazendo uso de AINH há 3 dias por apresentar dor lombar. Ao exame físico encontramos o\n\"abdome em tábua\". O exame mais apropriado para esclarecimento diagnóstico é:","options":{"A":"Ultrassonografia de abdome.","B":"Rotina radiológica para abdome agudo.","C":"Ressonância magnética de abdome superior.","D":"Tomografia computadorizada de abdome."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-182622","number":"182622","sourceNumber":"182622","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente masculino, 52 anos com queixas de disfagia com evolução de 8 anos. Foi\nrealizado endoscopia digestiva alta que\nevidenciou dilatação esofágica e diagnóstico de acalasia. O\nesofagograma revelou megaesôfago grau II. Qual exame deverá ser realizado para a escolha da\ntécnica operatória apropriada?","options":{"A":"Endoscopia com magnificação e corante vermelho Congo.","B":"Manometria esofágica.","C":"PHmetria esofágica.","D":"Ecoendoscopia."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-159113","number":"159113","sourceNumber":"159113","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente do sexo masculino, 58 anos, iniciou quadro de dor em andar superior do\nabdome intensa, há 2 horas. Nega quadro\nsemelhante anterior ou cirurgias prévias. Ao exame\nfísico: abdome plano, em tábua. Considerando a hipótese de perfuração de úlcera péptica, quais as\nprincipais etiologias?","options":{"A":"H. pylori e Anti-Inflamatório Não Hormonal (AINH).","B":"Câncer gástrico e doença de Dieulafoy.","C":"Gastrite erosiva aguda e síndrome de Ménétrier.","D":"Gastrinoma e tumor estromal."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-135927","number":"135927","sourceNumber":"135927","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Um lactante com 1 mês e 20 dias de vida é atendido na Unidade de Pronto\nAtendimento de seu bairro com história de\nvômitos alimentares em jato após as mamadas.\nEncontra-se abaixo do peso esperado para idade e desidratado. Após investigação, a ecografia\nabdominal firmou o diagnóstico de estenose hipertrófica de piloro. Quais os distúrbios acidobásicos\nque se espera encontrar?","options":{"A":"Alcalose respiratória;","B":"Alcalose metabólica;","C":"Acidose respiratória;","D":"Acidose metabólica."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-108688","number":"108688","sourceNumber":"108688","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente feminina, 60 anos, submetida à Gastrectomia a Bll e \"Y\" de Roux para\ntratamento de um adenocarcinoma gástrico. Qual a importância do \"Y\" de Roux nesse\nprocedimento?","options":{"A":"Profilaxia da deficiência de Vit. B12;","B":"Profilaxia da S. de Dumping;","C":"Profilaxia da gastrite alcalina;","D":"Profilaxia da perda de peso pôs-gastrectomia."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-84539","number":"84539","sourceNumber":"84539","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"São indicações clássicas de tratamento cirúrgico para úlcera péptica, exceto:","options":{"A":"úlcera penetrada para pâncreas.","B":"perfuração.","C":"obstrução pilórica.","D":"hemorragia sem controle com tratamento endoscópico/ radiológico.","E":"presença de pneumoperitoneo."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-29363","number":"29363","sourceNumber":"29363","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente H.pylori positivo. Qual situação está indicada fortemente erradicação do\nmicrorganismo?","options":{"A":"Úlcera duodenal","B":"Dispepsia funcional","C":"Doença do refluxo gastro-esofágico","D":"Desejo do paciente após esclarecimentos","E":"Uso crônico de AINES"},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-343187","number":"343187","sourceNumber":"343187","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"O divertículo faringoesofágico é o divertículo esofágico mais comum. Situa-se\nherniando em uma região denominada trígono de\nKillian. A complicação mais mórbida do não\ntratamento desta doença em pacientes idosos é:","options":{"A":"Carcinoma escamoso.","B":"Esôfago de Barret.","C":"Pneumonias por aspiração.","D":"Perda ponderal."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-343191","number":"343191","sourceNumber":"343191","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Assinale a alternativa que se associa a condições de aumento da secreção péptica\ngástrica como na síndrome de Zollinger-Ellison.","options":{"A":"Carcinoma epidermoide de estômago","B":"Gastrinoma","C":"GIST duodenal","D":"Insulinoma"},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-315164","number":"315164","sourceNumber":"315164","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A alteração fisiológica causada pela vagotomia troncular é a seguinte:","options":{"A":"Diminuição do volume da vesícula biliar","B":"Aumento da sensibilidade à histamina","C":"Aumento da secreção exócrina do pâncreas","D":"Diminuição do fluxo biliar pós-prandial","E":"Hipoplasia das células secretoras de gastrina"},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-315165","number":"315165","sourceNumber":"315165","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Durante uma gastrectomia parcial (antrectomia), que estrutura serve de referência para\ndelimitar o antrogástrico?","options":{"A":"Artéria gástrica esquerda.","B":"Ramo de Latarjet do nervo vago.","C":"Borda superior do pâncreas.","D":"Ligamento Redondo.","E":"Artéria gastro-omental direita."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-275978","number":"275978","sourceNumber":"275978","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Na doença do refluxo gastroesofágico, qual o exame complementar considerado como\npadrão ouro?","options":{"A":"Manometria.","B":"Endoscopia.","C":"Rx contrastado do esôfago.","D":"Phmetria.","E":"Impedanciometria."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-279056","number":"279056","sourceNumber":"279056","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"É o divertículo faringoesofágico mais comum encontrado hoje em dia. Apresenta-se,\ngeralmente, em pacientes idosos na sétima\ndécada de vida e tem sido postulado como resultado de\nperda da elasticidade tecidual e tônus muscular com a idade. É encontrado especificamente\nherniando no triângulo de Killian, entre as fibras oblíquas do músculo tireofaríngeo e as fibras\nhorizontais do músculo cricofaríngeo. Trata-se do:","options":{"A":"Divertículo de Meckel.","B":"Divertículo de Zenker.","C":"Divertículo de Hinchey.","D":"Divertículo de Hutch."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-278638","number":"278638","sourceNumber":"278638","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A seriografia contrastada a seguir de esôfago, estômago e duodeno tem maiores\nchances de serem encontradas em pacientes com o diagnóstico de:","options":{"A":"Acalásia.","B":"Carcinoma espinocelular.","C":"Adenocarcinoma.","D":"Espasmo esofágico difuso."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-278643","number":"278643","sourceNumber":"278643","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"As úlceras gástricas podem ocorrer em qualquer local no estômago, apesar de\ngeralmente estarem presentes na curvatura menor, perto da incisura angularis. Sobre a\nclassificação de Johnson, assinale a correta.","options":{"A":"Úlcera tipo I: sempre estão associadas à secreção excessiva de ácidos.","B":"Úlcera tipo II: geralmente estão associadas a uma elevada secreção de ácido, em combinação\ncom uma úlcera duodenal.","C":"Úlcera tipo III: são úlceras em corpo gástrico e responsáveis por cerca de 90% das lesões.","D":"As úlceras gástricas do tipo IV ocorrem em uma parte distal do corpo gástrico, próximo ao\npiloro."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-279064","number":"279064","sourceNumber":"279064","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"É a falha de relaxamento da musculatura esofágica. Essa doença é a mais bem\ncompreendida de todos os distúrbios da motilidade esofágica. A tríade clássica de sintomas\nconsiste em disfagia, regurgitação e perda de peso. Pode ser diagnosticada pelo esofagograma\nabaixo. Trata-se do(a):","options":{"A":"Esôfago em quebra-nozes.","B":"Adenocarcinoma de esôfago.","C":"Doença do refluxo gastroesofágico.","D":"Acalásia."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-231355","number":"231355","sourceNumber":"231355","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Assinale qual o esquema terapêutico considerado como primeira opção para o\ntratamento do H. Pylori de acordo com o IV Consenso Brasileiro do H. Pylori:","options":{"A":"IBP (dose plena) + amoxicilina 1G + Claritromicina 500 MG 2 vezes ao dia ? durante 14 dias.","B":"IBP (dose plena + amoxicilina 1G + Claritromicina 500 MG 2 vezes ao dia, durante 07 dias.","C":"A alternativa (A) e (E), durante 10 dias.","D":"IBP (dose plena) + amoxicilina 1G + Metronidazol 400 MG duas vezes ao dia 14 dias","E":"IBP (dose plena 1 x dia) + tetraciclina 500 MG (6 em 6 horas) + Claritromicina 500 MG (2 x dia),\ndurante 14 dias."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-249304","number":"249304","sourceNumber":"249304","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"O tronco celíaco é uma importante fonte de irrigação de vísceras abdominais. Emite 3\nramos arteriais principais:","options":{"A":"mesentérica superior, hepática comum e frênica inferior.","B":"mesentérica superior, hepática própria e esplênica.","C":"hepática comum, gástrica esquerda e esplênica.","D":"mesentérica inferior, gástrica esquerda e esplênica acessória."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-249306","number":"249306","sourceNumber":"249306","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A fundoplicatura de Nissen é um procedimento cirúrgico utilizado para tratamento de:","options":{"A":"dolicomegaesôfago.","B":"atresia duodenal.","C":"gastrite alcalina.","D":"doença do refluxo gastroesofágico."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-249412","number":"249412","sourceNumber":"249412","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"São fatores estimulantes da secreção ácida gástrica:","options":{"A":"Gastrina, histamina e acetilcolina.","B":"Gastrina, bradicinina e acetilcolina.","C":"Somatostatina, histamina e acetilcolina.","D":"Somatostatina, bradicinina e adrenalina."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-249422","number":"249422","sourceNumber":"249422","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Originalmente descrito por Zenker e Von Ziemssen, o divertículo faringo-esofágico é o\ndivertículo esofágico mais comum. Encontra-se herniando em uma região denominada trígono de\nKillian. A complicação mais mórbida do não tratamento desta doença em pacientes idosos é:","options":{"A":"Abscesso pulmonar e/ou pneumonias por aspiração.","B":"Perfuração esofágica.","C":"Esôfago de Barret.","D":"Caquexia."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-249225","number":"249225","sourceNumber":"249225","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A técnica cirúrgica para correção de doença do refluxo gastroesofágico que\noriginalmente há abordagem intra-torácica e abdominal é:","options":{"A":"Nissen","B":"Lindi","C":"Toupet","D":"Belsey-Mark IV"},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-249229","number":"249229","sourceNumber":"249229","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"São estimulantes da secreção de ácido clorídrico pelas células parietais no estômago:","options":{"A":"histamina, acetilcolina e gastrina.","B":"histamina, acetilcolina e prostaglandina.","C":"tiamina, acetilcolina e bicarbonato.","D":"gastrina, acetilcolina e óxido pentanitroso."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-212155","number":"212155","sourceNumber":"212155","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente de 60 anos, sexo feminino, relata que há 6 meses iniciou um quadro de dor\nem região epigástrica de moderada\nintensidade, sem irradiação e 2 vezes por semana. Há 3 meses\nevoluiu com piora da intensidade e da frequência do sintoma. Refere dor epigástrica diária,\nprincipalmente após a alimentação. Foi à consulta com o gastroenterologista, que solicitou uma\nendoscopia digestiva alta. O exame histológico evidenciou gastrite crônica com presença de H.\npylori. De acordo com o IV Consenso Brasileiro sobre a infecção por Helicobacter pylori, assinale a\nalternativa CORRETA.","options":{"A":"A fase adulta é considerada o período de maior risco para aquisição de H. pylori.","B":"Os seres humanos são o único reservatório e principal fonte de transmissão de H. pylori.","C":"A pesquisa de H. pylori após a terapia de erradicação deverá ser realizada pelo menos 12\nsemanas após o término do tratamento.","D":"O teste do antígeno fecal usando anticorpos monoclonais é o exame padrão ouro para o\ndiagnóstico não invasivo de infecção por H. pylori.","E":"O teste rápido da urease é o exame recomendado para controle da erradicação de H. pylori\napós o tratamento, sem a necessidade de exame adicional."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-201751","number":"201751","sourceNumber":"201751","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Quais destas operações são realizadas no tratamento do megaesôfago chagásico em\ngraus iniciais?","options":{"A":"Esofagocoloplastia.","B":"Esofagogastroplastia.","C":"Esofagectomia total.","D":"Todas as anteriores.","E":"Nenhuma das anteriores."},"answer":"E","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-215497","number":"215497","sourceNumber":"215497","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Assinale a alternativa INCORRETA com relação à duplicação esofágica.","options":{"A":"O diagnóstico é realizado por radiografia contrastada de esôfago que revela compressão\nextrínseca, geralmente no terço médio, e pode ser\nconfirmado por tomografia de tórax.","B":"O diagnóstico diferencial inclui outras formas de compressão esofagiana como adenomegalias e\nanomalias vasculares.","C":"O diagnóstico de duplicação de esôfago é, geralmente, realizado no período pré-natal e seu\nquadro clínico caracteriza-se, basicamente,\npor disfagia ou, eventualmente, sintomas respiratórios.","D":"O tratamento cirúrgico é realizado inicialmente por videotoracoscopia e consiste na exérese\ncompleta da duplicação da parede esofagiana."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-180138","number":"180138","sourceNumber":"180138","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"O triângulo de Killian tem relação etiopatogênica com:","options":{"A":"Hernia lombar superior","B":"Hernia inguinal","C":"Divertículo de Zenker","D":"Divertículo de Meckel","E":"Anel de Schatzki"},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-180145","number":"180145","sourceNumber":"180145","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Sobre suturas gastrointestinais é incorreto afirmar:","options":{"A":"O plano total tem por objetivo a hemostasia e a continência.","B":"A sutura contínua ancorada permite melhor controle hemostático.","C":"A gastroenteroanastomose geralmente é realizada na face posterior do estômago, por causa do\nmelhor suprimento arterial.","D":"A sutura seromuscular é a que permanence e a que mantém a justaposição correta das\nestruturas\n\nanatômicas anastomosadas.","E":"A anastomose é dita isoperistáltica quando o sentido do trânsito é o mesmo em cada uma das\nvísceras anastomosadas."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-181312","number":"181312","sourceNumber":"181312","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Em relação à doença de Chagas e à acalásia da cárdia, é correto afirmar:","options":{"A":"o tratamento curativo da acalásia é cirúrgico, sendo as cirurgias de Heller e Thal-Hatafuku as\nmais realizadas em todo o mundo.","B":"apesar de doenças diferentes, a esofagopatia chagásica e a acalásia idiopática têm\nfisiopatologia, manifestações clínicas e tratamento iguais.","C":"o tratamento não cirúrgico mais eficaz para acalásia é a dilatação pneumática da transição\nesôfago-gástrica levando a alívio duradouro da disfagia.","D":"os pacientes com doença de Chagas apresentam sintomas brandos e inespecíficos na fase\naguda e, após 2 a 4 meses, mais da metade dos pacientes evoluem para fase crônica.","E":"as características radiológicas do megaesôfago do grupo II, segundo a classificação de\nRezende, são pequeno a moderado aumento de\ndiâmetro e retenção de contraste e hipotonia do\nesôfago inferior."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-181403","number":"181403","sourceNumber":"181403","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Dadas as afirmativas, quanto à doença do refluxo gastroesofágico (DRGE), I. Tosse\ncrônica, pigarro e desgaste no esmalte dentário são considerados manifestações atípicas da\nDRGE.; II. A obesidade é um fator de risco na DRGE.; III. A DRGE pode ser classificada em duas\nformas de apresentação, sendo a erosiva a forma mais frequente de apresentação.; IV. Os\ninibidores da bomba de prótons (IBP) são considerados medicamentos de escolha no tratamento\nda DRGE. Pacientes com manifestações atípicas têm indicação de iniciar tratamento com dose\nplena de IBP por um período prolongado. verifica-se que estão corretas","options":{"A":"I e II, apenas.","B":"I e III, apenas.","C":"II e IV, apenas.","D":"III e IV, apenas.","E":"I, II, III e IV."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-182824","number":"182824","sourceNumber":"182824","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Sobre os divertículos de Zenker, marque a afirmativa INCORRETA.","options":{"A":"É encontrado no triângulo de Killian, entre as fibras oblíquas do músculo tireofaríngeo e as\nfibras\nhorizontais do músculo cricofaríngeo.","B":"Os procedimentos endoscópicos para tratamento dos divertículos de Zenker são sujeitos a\ncomplicações, destacando-se hemorragia e perfurações, que podem cursar com grave mediastinite.","C":"O diagnóstico é feito por seriografia contrastada faringoesofágica.","D":"A vantagem da diverticulopexia sobre a diverticulectomia é a ausência do risco de fístula."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-183622","number":"183622","sourceNumber":"183622","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"O papel do tratamento cirúrgico para o refluxo gastroesofágico e hérnias de hiato\nmudou drasticamente durante a década de 1990. A\npopularização da intervenção cirúrgica\nminimante invasiva foi a força motriz responsável pelo aumento das indicações para o tratamento\ncirúrgico destas doenças. É INCORRETO afirmar sobre as complicações relacionadas aos\nprocedimentos antirrefluxo laparoscópicos:","options":{"A":"Pneumotórax é uma das complicações intraoperatórias mais comuns, que se resolvem na maior\nparte das vezes com drenagem pleural fechada.","B":"Plenitude pode ocorrer em até 30% dos pacientes, no entanto a maioria tem melhora dos\nsintomas após 2 meses.","C":"Insucesso cirúrgico se refere a pacientes com sintomas persistentes e evidência de exposição\nao ácido, a incidência é de cerca de 5 a 10%.","D":"A taxa de mortalidade é muito baixa. Sendo maior em paciente com mais de 60 anos."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-161306","number":"161306","sourceNumber":"161306","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Aponte a alternativa INCORRETA com relação às síndromes pós-gastrectomia.","options":{"A":"A síndrome de Dumping pode ser precoce (20-30 minutos após a ingestão) ou tardia (duas ou\ntrês horas após uma refeição) e é mais comum após gastrectomia parcial com reconstrução à\nBillroth II.","B":"A síndrome da alça aferente ocorre como resultado de uma obstrução parcial da alça aferente,\nque é incapaz de esvaziar os seus conteúdos.","C":"A obstrução da alça eferente geralmente é rara e pode ocorrer a qualquer momento após a\noperação; no entanto, mais de 50% dos pacientes ficam obstruídos no primeiro mês de\n\npós-operatório.","D":"A maior parte dos pacientes que sofrem de gastrite por refluxo alcalino foi submetida à\nressecção gástrica com anastomose à Billroth I."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-161310","number":"161310","sourceNumber":"161310","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Associe os Hormônios Gastrointestinais a seus respectivos Efeitos Primários e, em\nseguida, marque a opção contendo a sequência CORRETA. (Conforme imagem do caderno de\nquestões).","options":{"A":"1-b / 2-d / 3-c / 4-a","B":"1-b / 2-c / 3-a / 4-d","C":"1-b / 2-c / 3-d / 4-a","D":"1-d / 2-a / 3-b / 4-c"},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-161262","number":"161262","sourceNumber":"161262","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Assinale a alternativa INCORRETA em relação à anatomia gástrica macroscópica.","options":{"A":"O plexo celíaco é a principal fonte do suprimento sanguíneo para o estômago. Existem quatro\nartérias principais ? as artérias gástricas\nesquerda e direita e a artéria gastroepiplóica direita e\nesquerda. Uma quantidade substancial de sangue pod ser suprida pelas artérias frênicas inferiores\ne pelas artérias gástricas curtas.","B":"A mais volumosa artéria para o estômago é a artéria gástrica direita, e não é incomum (15-20%)\nque uma artéria hepática esquerda aberrante\nse origine dela.","C":"A inervação extrínseca do estômago é parassimpática (via vago) e simpática (pelo plexo\ncelíaco). Na junção gastroesofágica, o vago esquerdo é anterior e o vago direito é posterior.","D":"As veias gástricas esquerda e direita geralmente drenam para dentro da veia porta. A veia\ngastroepiploica direita drena para a veia mesentérica superior, e a veia gastroepiplóica esquerda\ndrena para veia esplênica."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-152663","number":"152663","sourceNumber":"152663","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Na doença do refluxo gastroesofágico, qual o exame complementar considerado como\npadrão-ouro?","options":{"A":"Manometria.","B":"Endoscopia.","C":"Rx contrastado do esôfago.","D":"pHmetria.","E":"Cintilografia."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-134854","number":"134854","sourceNumber":"134854","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Divertículos são formações saculares em fundo cego que podem estar localizados em\nvárias partes do corpo humano. Os divertículos de Zenker localizam-se no:","options":{"A":"Esôfago superior.","B":"Intestino grosso.","C":"Intestino delgado.","D":"Esôfago inferior."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-134823","number":"134823","sourceNumber":"134823","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"No paciente com doença do refluxo gastroesofágico, cuja manometria revela uma\natividade peristáltica de 45% e amplitude da onda\nperistáltica distal de 21 mmHg, deve-se optar por:","options":{"A":"fundoplicatura total.","B":"esofagogastrectomia.","C":"fundoplicatura parcial.","D":"gastrectomia parcial a BII."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-134056","number":"134056","sourceNumber":"134056","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A síndrome da alça aferente é em consequência","options":{"A":"da obstrução da anastomose Billroth I.","B":"da obstrução da anastomose Billroth II.","C":"do rápido esvaziamento gástrico da anastomose Billroth I.","D":"do rápido esvaziamento gástrico da anastomose Billroth II."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-131347","number":"131347","sourceNumber":"131347","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A cirurgia mais eficaz para correção de refluxo gastroesofágico:","options":{"A":"Cirurgia de Lind.","B":"Cirurgia de Nissen.","C":"Cirurgia de Lotart-Jacob.","D":"Cirurgia de Merendino.","E":"Gastrectomia proximal."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-131387","number":"131387","sourceNumber":"131387","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Na doença do refluxo gastroesofágico, qual o exame complementar considerado como\npadrão-ouro?","options":{"A":"Manometria.","B":"Endoscopia.","C":"RX contrastado do esôfago.","D":"pHmetria.","E":"Cintilografia."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-110054","number":"110054","sourceNumber":"110054","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente do sexo masculino, 50 anos, com quadro de dor em região epigástrica há dois\ndias, é admitido no pronto-socorro com piora da dor. Tem antecedente de hipertensão arterial\nsistêmica e obesidade. Ao exame clínico, apresenta palpação dolorosa em região epigástrica e\nflancos. Raios X abdominal em posição ortostática revelam presença de ar em região\nsubdiafragmática bilateral. Hemograma com leucocitose e dosagem de amilase com valor duas\nvezes superior ao limite da normalidade. Assinale abaixo o diagnóstico MAIS provável:","options":{"A":"Pancreatite aguda.","B":"Úlcera duodenal perfurada.","C":"Colelitíase.","D":"Nefrolitíase."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-109974","number":"109974","sourceNumber":"109974","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"São pacientes que necessitam profilaxia para Úlcera Péptica ao utilizar\nAnti-Inflamatórios Não Esteroidais (AINE?s), EXCETO:","options":{"A":"Com antecedente de Úlcera Péptica.","B":"Em uso concomitante de Varfarina.","C":"Em uso concomitante de Corticosteroides em dose alta.","D":"Quando o tratamento com AINE?s for superior a dois dias."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-109755","number":"109755","sourceNumber":"109755","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"O sinal de presença de pneumoperitônio ocorre perfuração de víscera:","options":{"A":"maciça.","B":"oca com porção retroperitonial.","C":"oca com porção intraperitonial.","D":"oca intramediastinal."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-110546","number":"110546","sourceNumber":"110546","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"De acordo com o consenso Roma III, o tempo necessário de sintomas para que se faça\no diagnóstico de Dispepsia Funcional é:","options":{"A":"sintomas tenham iniciado a 12 meses e ativos nos últimos 3 meses.","B":"6 meses com sintomas presentes e ativos nos últimos 2 meses.","C":"sintomas tenham iniciado há pelo menos 6 meses e ativos nos últimos 3 meses.","D":"12 meses com sintomas presentes e 3 meses não necessariamente consecutivos.","E":"nenhuma das alternativas acima."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-110557","number":"110557","sourceNumber":"110557","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Dentre as alternativas abaixo, assinale a mais CORRETA em relação ao H. pylori:","options":{"A":"O H. pylori é uma bacilo espiralado Gram-positivo.","B":"Produz a enzima \"urease\" que facilita a sua colonização e multiplicação no epitélio\ngastrointestinal.","C":"Foi descoberta por Warren e Marshall em um final de semana prolongado no ano de 1993.","D":"Está presente em cerca de setenta por\ncento (70%) dos caso de úlcera duodenal.","E":"As alternativas \"A e B\" estão corretas."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-109780","number":"109780","sourceNumber":"109780","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Divertículo de Zenker está localizado no:","options":{"A":"íleo terminal.","B":"esôfago inferior.","C":"próximo apêndice vermiforme.","D":"esôfago proximal."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-110030","number":"110030","sourceNumber":"110030","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Qual é a posição MAIS adequada de Raios-X simples de abdome que deve ser\nrealizada frente à suspeita de abdome agudo perfurativo?","options":{"A":"Em decúbito ventral.","B":"Em decúbito lateral esquerdo com raios horizontais.","C":"Em decúbito dorsal.","D":"Em Trendelemburg."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-86622","number":"86622","sourceNumber":"86622","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Em relação ao nervo vago, marque a alternativa INCORRETA:","options":{"A":"É o 10º par craniano.","B":"Possui fibras eferentes viscerais parassimpáticas.","C":"Acima do diafragma o nervo emite seus ramos principais.","D":"O tronco anterior recebe fibras predominantes do nervo vago direito.","E":"O nervo principal anterior (nervo de Latarjet anterior) tem origem no tronco anterior."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-86631","number":"86631","sourceNumber":"86631","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Assinale a alternativa correta no tratamento da úlcera péptica complicada:","options":{"A":"O tratamento cirúrgico se impõe ao tratamento clínico.","B":"Na úlcera perfurada o tratamento cirúrgico é considerado como de exceção.","C":"Na hemorragia por úlcera, a endoscopia digestiva terapêutica só deve ser utilizada quando o\npaciente não tem condição cirúrgica.","D":"Cerca de 10% das obstruções do segmento gastroduodenal são atribuídos à causa péptica.","E":"Nos casos de estenose pilórica severa péptica, a cirurgia deve ser realizada imediatamente."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-158436","number":"158436","sourceNumber":"158436","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Com relação às úlceras gástricas e, mais especificamente, às fases de Sakita, assinale\na alternativa CORRETA:","options":{"A":"Cicatriz (A1 e A2).","B":"Ativa (A1 e A2).","C":"Cicatrização (A1 e A2).","D":"Cicatriz (H1 e H2).","E":"Cicatrização (S1 e S2)."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-108579","number":"108579","sourceNumber":"108579","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"É um medicamento utilizado para tratar refluxo gastroesofágico por reduzir a secreção\nde ácido clorídrico:","options":{"A":"Domperidona.","B":"Omeprazol.","C":"Metoclopramida.","D":"Betanecol.","E":"Albendazol."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-362513","number":"362513","sourceNumber":"362513","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente do sexo feminino, 45 anos, obesa, vem ao consultório queixando história de\npirose crônica que tratava no domicílio com chás caseiros. Evolui há cerca de 2 meses com\naumento da frequência da pirose, associada a dor retroesternal, regurgitação e perda de peso. Traz\nconsigo endoscopia digestiva que fez por conta própria, que evidenciou duas erosões de 75mm em\nesôfago distal, não coalescentes. Sobre o caso, assinale a alternativa CORRETA:","options":{"A":"Os sintomas típicos descritos pela paciente, associados aos seus achados endoscópicos,\nexcluem a necessidade de realização de Phmetria\nesofagiana para confirmação diagnóstica do\ncaso.","B":"Já que os sintomas apresentados não são típicos e os achados endoscópicos são inespecíficos,\no próximo passo para diagnóstico é o início de\nterapia com bloqueadores de bomba de prótons e\nrealização de Phmetria sem fio por 96 horas.","C":"A ausência de hérnia hiatal na endoscopia digestiva exclui diagnóstico de doença do refluxo\ngastroesofágico.","D":"O diagnóstico de acalasia será confirmado caso a Phmetria sem fio observe tempo de exposição\nda mucosa esofágica ao ácido gástrico menor que\n4% em todos os dias do exame."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-327257","number":"327257","sourceNumber":"327257","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente do sexo feminino, 43 anos, refere que, há 1 ano e meio, iniciou quadro de\ndisfagia inicialmente para sólidos que evoluiu progressivamente para disfagia para alimentos\npastosos, associada a regurgitação de alimentos não digeridos e tosse seca. Refere piora da\nregurgitação e tosse durante o decúbito, além de perda de 10kg no período. Seu exame físico\ncervical, torácico e abdominal não tem alterações relevantes. Solicitada endoscopia digestiva alta,\nesta evidenciou esofagite leve, discreta dilatação esofagiana, ausência de hérnia hiatal e discreta\nresistência do esfíncter esofagiano inferior (EEI) à insuflação com ar. Sobre o caso acima, assinale\na alternativa INCORRETA:","options":{"A":"O esofagograma baritado deve ser útil na avaliação do grau da doença e no seu direcionamento\nterapêutico.","B":"Uma adequada opção terapêutica para esta paciente é a Cirurgia de Heller associada a\nconfecção de válvula antirrefluxo à Lind.","C":"O exame padrão ouro para o diagnóstico do quadro acima é a Phmetria esofagiana que\nobservaria hipotonia da parede do esôfago e hipertonia do EEI.","D":"Tratamentos endoscópicos como a injeção de toxina botulínica ou dilatação pneumática do EEI\nsão opções terapêuticas à abordagem cirúrgica."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-298219","number":"298219","sourceNumber":"298219","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Os casos clínicos abaixo são sugestivos de Doença de Refluxo Gastroesifágico\n(DRGE), EXCETO:","options":{"A":"Paciente do sexo masculino, obeso, com história de episódio de pirose ocasional associada a\nalimentação copiosa rica em gordura e consumo de álcool, com endoscopia normal.","B":"Grávida de 32 semanas, queixando mais de 4 episódios de pirose após refeições por semana.","C":"Paciente do sexo masculino, 38 anos, com rouquidão crônica de difícil tratamento e volumosa\nhérnia de hiato à endoscopia.","D":"Neuropata, 2 anos de idade, com história de episódios frequentes de regurgitação de leite e\ninternações por pneumonia."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-286710","number":"286710","sourceNumber":"286710","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"O tratamento da DRGE (Doença do Refluxo Gastroesofágico) objetiva controlar os\nsintomas, cicatrizar as lesões e prevenir as complicações. Fazem parte do tratamento da DRGE,\nEXCETO:","options":{"A":"Elevação da cabeceira da cama (15 cm).","B":"Moderação na ingestão dos seguintes alimentos, com observação à correlação com os\nsintomas: alimentos gordurosos, cítricos, café, chocolate, bebidas alcoólicas, hortelã e tomate.","C":"Inibidores da bomba de prótons em ciclo de 4 a 8 semanas de tratamento.","D":"Anticolinérgicos e antidepressivos tricíclicos."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-286731","number":"286731","sourceNumber":"286731","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente do sexo feminino, 32 anos, refere história de laringite crônica refratária a\ntratamentos convencionais, sendo diagnosticada com doença do refluxo gastroesofágico há cerca\nde 5 anos. Refere ter realizado endoscopia, Phmetria e esofagomanometria à época. A paciente\nentão iniciou tratamento com 40mg diários de Omeprazol com melhora da pirose e do quadro de\nlaringite, porém apresentava recorrências frequentes devido a uso irregular da medicação e não se\nadaptar adequadamente à dieta. Você é o quarto médico que esta paciente procura porque os\nmédicos anteriores ?não resolveram o problema?. O quadro vem piorando no último ano com\naumento da intensidade e frequência da pirose e aparecimento de tosse crônica. Realizou\nrecentemente e por conta própria uma endoscopia digestiva alta que revelou transição\nesofagogástrica 3cm acima da prega diafragmática, além de esofagite em terços médio e distal do\nesôfago, sem sinais macroscópicos de áreas sugestivas de metaplasia. Sobre o caso acima,\nassinale a alternativa CORRETA:","options":{"A":"Os dados fornecidos acima sugerem que a hiatoplastia com fundoplicatura laparoscópica parece\nser opção terapêutica adequada para esta\npaciente.","B":"Os dados fornecidos acima nos permitem afirmar que a conduta adequada só pode ser definida\napós realização de nova Phmetria e esofagomanometria.","C":"Já que o diagnóstico de hérnia hiatal não foi adequadamente fechado, o próximo passo na\ninvestigação desta paciente é o esofagograma baritado.","D":"A esofagite grave presente à endoscopia desta paciente nos leva a cogitar a indicação de\nesofagectomia devido ao iminente risco de malignização."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-252238","number":"252238","sourceNumber":"252238","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente com epigastralgia refratária, realizou endoscopia com identificação de várias\nlesões ulceradas em estômago e dosagem de gastrina elevada. Que síndrome pode estar\nrelacionada?","options":{"A":"Paterson Kelly.","B":"Zolinger Ellison.","C":"Mallory Weiss.","D":"Prune Belly."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-208437","number":"208437","sourceNumber":"208437","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Uma paciente do sexo feminino, 55 anos, entra no seu consultório com queixa\ndispéptica crônica. Por ser procedente de\nmunicípio do Interior do Estado, o único exame que pôde\nser realizado na sua cidade foi radiografia contrastada de esôfago, estômago e duodeno. O exame\nevidencia imagem que sugere lesão ulcerada em região antral, com dificuldade de passagem de\ncontraste para o duodeno. Assinale a alternativa CORRETA:","options":{"A":"Há indicação precisa de endoscopia digestiva alta com biópsia para definição do caráter\n(benigno ou maligno) da lesão.","B":"Os dados acima são suficientes para afirmar a necessidade de gastrectomia total para esta\npaciente.","C":"Vômitos contendo alimentos não digeridos, melena e perda de peso são elementos que\nprovavelmente estarão presentes na história detalhada desta paciente.","D":"A observação de ascite, prateleira de Blumer e esplenomegalia ao exame físico indicam\nprognóstico ruim para esta paciente."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-208432","number":"208432","sourceNumber":"208432","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente do sexo feminino, 46 anos, vem à avaliação médica com história de pirose há\nmuitos anos, frequentemente associada a alimentação copiosa rica em gordura, refrigerantes e\ncafé. Controla a sintomatologia com chás caseiros, hidróxido de alumínio e antiácidos\nefervescentes. Foi submetida a endoscopia digestiva alta que evidenciou áreas de epitélio\navermelhado em esôfago distal, medindo 5 cm acima da linha Z. A biópsia revelou tratar-se de\nmetaplasia colunar e áreas de displasia de alto grau. Qual das seguintes orientações a esta\npaciente é inadequada?","options":{"A":"A senhora apresenta um quadro de doença do refluxo gastroesofágico bastante complicada que\nse não for tratado adequadamente pode\nevoluir para um câncer.","B":"As chances dessa metaplasia no esôfago que apareceu na sua endoscopia melhorar apenas\ncom remédios é muito baixa.","C":"Seu exame demonstra que a cirurgia de fundoplicatura evitará que a sua lesão do esôfago se\ntransforme em câncer.","D":"A senhora tem indicação de tratamento cirúrgico, mas antes deveremos iniciar tratamento com\nmedicações em dose máxima por 3 meses e repetir a endoscopia para ver se a displasia melhorou."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-176030","number":"176030","sourceNumber":"176030","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Em relação aos divertículos de esôfago, assinale a alternativa INCORRETA:","options":{"A":"O divertículo esofágico mais comum é o divertículo de Zenker, que ocorre na junção da\nfaringe ao esôfago.","B":"Os divertículos epifrênicos, assim como os parabronquiais, são divertículos verdadeiros.","C":"Divertículos de pulsão são divertículos falsos, decorrentes de altas pressões intraluminares.","D":"Divertículos parabronquiais resultam de reações inflamatórias externas nos linfonodos\nadjacentes."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-176038","number":"176038","sourceNumber":"176038","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Sobre acalasia, é INCORRETO afirmar:","options":{"A":"É considerada uma lesão pré-maligna, pois pode levar, após anos de evolução, ao\ndesenvolvimento de carcinoma de esôfago, sendo o tipo histológico mais comum o\nadenocarcinoma.","B":"A tríade clássica dos sintomas inclui disfagia, regurgitação e perda de peso.","C":"Ao exame de manometria, ocorre falha de relaxamento do esfíncter esofágico inferior em\nresposta à deglutição.","D":"Estágios mais avançados levam à dilatação maciça e tortuosidade do órgão, o chamado\nmegaesôfago."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-176043","number":"176043","sourceNumber":"176043","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"No tratamento cirúrgico da doença do refluxo gastroesofágico, a fundoplicatura à\nNissen corresponde à confecção de uma válvula de:","options":{"A":"360º.","B":"270º.","C":"180º anterior.","D":"180º posterior."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-176051","number":"176051","sourceNumber":"176051","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Os tipos de úlcera péptica que estão relacionados à hipercloridria são:","options":{"A":"I e II.","B":"I e IV.","C":"II e III.","D":"II e IV."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-151871","number":"151871","sourceNumber":"151871","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Caracteriza histologicamente o esôfago de Barrett a presença de:","options":{"A":"Epitélio colunar.","B":"Epitélio cilíndrico.","C":"Células caliciformes.","D":"Células eosinofílicas."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-151921","number":"151921","sourceNumber":"151921","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A cirurgia de Heller é indicada para portadores de:","options":{"A":"Acalásia.","B":"Úlcera péptica.","C":"Divertículo de Zenker.","D":"Síndrome de Plummer-Vinson."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-151932","number":"151932","sourceNumber":"151932","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"O teste respiratório da ureia marcada com carbono 13 é usado no controle da\nerradicação de:","options":{"A":"Helicobacter pylori.","B":"Clamidia tracomatis.","C":"Papilomavírus humano.","D":"BAAR (Bacilo Álcool Ácido Resistente)."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-151997","number":"151997","sourceNumber":"151997","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Sobre a úlcera péptica perfurada todas a alternativas estão corretas, EXCETO:","options":{"A":"O exame físico abdominal mostra sinal de irritação peritoneal.","B":"A radiografia de tórax em ortostase mostra pneumotórax livre.","C":"Quase sempre o paciente pode dar a hora exata do início da dor lancinante.","D":"O tratamento clínico é indicado apenas quando há evidências de que a ferida tenha se fechado\ne na ausência de peritonite química."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-151966","number":"151966","sourceNumber":"151966","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"São indicações cirúrgica de úlcera péptica hemorrágica, EXCETO:","options":{"A":"Quando a úlcera está associada ao Helicobacter pylori.","B":"Ausência de disponibilidade de sangue para transfusão.","C":"Hemorragia maciça não responsiva a tratamento endoscópico.","D":"Necessidade de transfusão de mais de 4 a 6 unidades de concentrado de hemácias, apesar das\ntentativas de controle endoscópico."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-151901","number":"151901","sourceNumber":"151901","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente do sexo feminino, 45 anos, sobrepeso, vem ao consultório de cirurgia,\nencaminhada do otorrinolaringologista,\nqueixando pirose e regurgitação ácida após alimentação\nrica em gordura e ácidos. Tais sintomas ocorrem quase que diariamente há cerca de 2 anos e\npioraram após gravidez e ganho de peso. Refere ainda dor torácica esporádica, retroesternal em\nqueimação, não relacionada a exercícios físicos, episódios ocasionais de disfonia e sensação de\nglobo faríngeo. Nega disfasia e hematêmese. Seu exame físico não tem alterações. Traz consigo\numa endoscopia digestiva alta que evidencia hérnia hiatal de 2 cm e ausência de lesões\nesofagianas, tais como ulcerações ou esofagite. Assinale a alternativa INCORRETA:","options":{"A":"A ausência de lesões esofagianas à endoscopia não exclui a hipótese de Doença do Refluxo\nGastroesofágico (DRGE), havendo necessidade de prosseguir com a investigação diagnóstica.","B":"A esofagomanometria não fecha diagnóstico de DRGE, porém pode evidenciar situações, tais\ncomo a hipotonia do esfíncter esofagiano inferior, que são sugestivas deste diagnóstico.","C":"A demonstração de refluxo gastroesofágico através do exame contrastado do esôfago tem maior\nsensibilidade e especificidade no diagnóstico de DRGE que a pHmetria esofagiana.","D":"Caso esta paciente não se adapte ao tratamento clínico com uso crônico de inibidores da bomba\nde prótons, a indicação de fundoplicatura\ngástrica com hiatoplastia via laparoscópica deve ser\nconsiderada."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-151905","number":"151905","sourceNumber":"151905","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Considerando o linfoma MALT de baixo grau, qual o tratamento de escolha como\nprimeira linha?","options":{"A":"Radioterapia.","B":"Quimioterapia.","C":"Quimioradioterapia.","D":"Erradicação do Helicobacter pylori."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-139139","number":"139139","sourceNumber":"139139","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"O esôfago de Barret caracteriza-se:","options":{"A":"Seu epitélio faz semelhança com as células cilíndricas.","B":"Por apresentar células caliciformes de permeio a células cilíndricas.","C":"Originar a síndrome de Plummer Vinson.","D":"Pela linhagem glandular no epitálio escamoso."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-103806","number":"103806","sourceNumber":"103806","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"O divertículo faringoesofagico de Zenker:","options":{"A":"É classificados como divertículo de tração.","B":"Em geral aparece na segunda década da vida.","C":"É formado com camada de mucosa e submucosa.","D":"Ocorre entre as fibras do músculo platisma e cricofaríngeo."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-103857","number":"103857","sourceNumber":"103857","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Esôfago com peristalse hipertensa ou contrações de alta amplitude. Sem predileção por\nfaixa etária ou sexo e é o distúrbio de hipermotilidade esofágica mais comum e o mais doloroso,\ncaracteriza:","options":{"A":"Acalásia.","B":"Espasmo esofágico difuso.","C":"Esôfago quebra-nozes.","D":"Esfíncter Esofagiano Inferior (EEI) hipertenso."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-107885","number":"107885","sourceNumber":"107885","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Com o advento das drogas inibidoras da bomba de prótons e o melhor entendimento da\ngênese da úlcera péptica e sua associação\ncom antiinflamatórios não hormonais e o Helicobater\npylori, seu tratamento cirúrgico entrou em declínio nas últimas décadas. Contudo, ainda há\nsituações onde a cirurgia deve ser aplicada. As alternativas abaixo configuram indicações para o\ntratamento cirúrgico da úlcera péptica, EXCETO:","options":{"A":"Sangramento ativo da úlcera com falha do tratamento endoscópico.","B":"Úlcera tipo III de Johnson com obstrução crônica.","C":"Paciente portador de úlcera gástrica que evolui com dor epigástrica intensa, abdome em tábua e\npneumoperitôneo.","D":"Úlcera tipo I de Johnson, com histopatológico evidenciando gastrite crônica associada ao\nHelicobacter pylori."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-107706","number":"107706","sourceNumber":"107706","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente do sexo feminino, 28 anos, obesa, vem ao ambulatório com queixa de pirose\ncrônica, principalmente após alimentação copiosa, rica em gordura e condimentados. Ela traz\nconsigo endoscopia digestiva alta que evidencia esôfago de elasticidade preservada, com transição\nesôfago-gástrica a nível do pinçamento diafragmático, apresentando lesões avermelhadas\nsemelhantes à mucosa gástrica em seu terço distal, cuja biópsia evidenciou tratar-se de metaplasia\ncolunar. O estômago encontrava-se hiperemiado (gastrite enantematosa), sem outras lesões.\n\nAnalise as assertivas abaixo e assinale a alternativa INCORRETA: I. A esofagomanometria é o\nexame de maior sensibilidade para\ndiagnosticar a patologia de base do paciente acima; II. Já que\nnão há hérnia hiatal, não há indicação de tratamento cirúrgico; III. O esofagograma contrastado e a\nPhmetria esofagiana são exames dispensáveis na avaliação do caso acima; IV. Caso o tratamento\nnão seja adequado, há possibilidade de evolução do caso para carcinoma escamocelular de\nesôfago; V. A ranitidina é medicação obrigatória no tratamento deste paciente.","options":{"A":"As assertivas III e IV são incorretas.","B":"Todas são falsas.","C":"As assertivas II e V são incorretas.","D":"A assertiva IV não é correta já que a neoplasia de evolução provável no caso é o linfoma\nesofagiano."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-87456","number":"87456","sourceNumber":"87456","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Todos os eventos abaixo podem ocorrer na acalásia, EXCETO:","options":{"A":"Espasmo patológico do esfíncter esofagiano inferior.","B":"Úlcera esofagiana por refluxo gastroesofágico.","C":"Retenção alimentar e vômitos de alimentos não digeridos.","D":"Megaesôfago.","E":"Imagem de \"bico de pássaro\" à radiografia contrastada de esôfago."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-81983","number":"81983","sourceNumber":"81983","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Principal causa de perfuração do esôfago:","options":{"A":"Ingesta de corpo estranho.","B":"Trauma por arma branca.","C":"Instrumentação endoscópica.","D":"Trauma por projetil de arma de fogo.","E":"Lesão inadvertida durante procedimento na traqueia."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-61575","number":"61575","sourceNumber":"61575","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Desde que foi isolado e identificado em 1983, por Marshall e seu então residente\nWarren, o Helicobacter pylori tem sido\nassociado a várias doenças gastrointestinais. Tal descoberta\nfoi de tamanha importância que mereceu o prêmio Nobel de Medicina de 2005. Até o momento, faz\nparte do consenso brasileiro a pesquisa e erradicação do H. Pylori nas seguintes situações:","options":{"A":"Úlcera gastroduodenal, Linfoma MALT de baixo grau, pós-ressecção de câncer gástrico precoce,\nfamiliar de 1º grau com câncer gástrico.","B":"Úlcera gastroduodenal, Linfoma MALT de baixo grau, pós-ressecção de câncer gástrico precoce,\nfamiliar de 1º grau com câncer gástrico. Doença do refluxo gastroesofágico.","C":"Pacientes de risco para úlcera ou complicações que deverão usar cronicamente AAS em doses\nbaixas. Doença do refluxo gastroesofágico, úlcera gastroduodenal, Linfoma MALT de baixo grau.","D":"Úlcera gastroduodenal, Linfoma MALT de baixo grau, pós-ressecção de câncer gástrico precoce,\ndispepsia funcional, pacientes de risco para úlcera ou complicações que deverão usar\ncronicamente AAS em doses baixas.","E":"Pacientes de risco para úlcera ou complicações que deverão usar cronicamente AAS em doses\nbaixas, uso crônico de anticoagulantes como o marevan, úlcera gastroduodenal, Linfoma MALT de\nbaixo grau, pós-ressecção de câncer gástrico precoce."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-46638","number":"46638","sourceNumber":"46638","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Disfagia com perda da peristalse esofagiana, ocasionado por perda ou diminuição de\ncélulas ganglionares no plexo mioentérico, o que ocasiona relaxamento ineficaz do esfíncter\nesofagiano inferior:","options":{"A":"Megaesôfago Chagásico","B":"Esôfago em Quebra Nozes","C":"Divertículo de Zenker","D":"Acalasia","E":"Esôfago de Barret"},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-34103","number":"34103","sourceNumber":"34103","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"O distúrbio metabólico mais comum após gastrectomia é:","options":{"A":"Anemia megaloblástica.","B":"Hipoglicemia.","C":"Absorção prejudicada de gordura.","D":"Deficiência de cálcio.","E":"Anemia ferropriva."},"answer":"E","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-34133","number":"34133","sourceNumber":"34133","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"O gastrinoma é o tumor endócrino pancreático mais sintomático. Que outros tumores\npodem, também, processar a progastrina até\ngastrina, produzindo a Síndrome de Zollinger-Ellison?","options":{"A":"Tumor de Ovário.","B":"Tumor de Pulmão.","C":"Neuroma Acústico.","D":"Tumor de Cólon.","E":"Tumor de Hipófise."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-26460","number":"26460","sourceNumber":"26460","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A dor epigástrica em queimação noturna está mais relacionada a:","options":{"A":"Úlcera gástrica","B":"Úlcera duodenal","C":"Úlcera de estresse","D":"Esofagite","E":"Gastrinoma"},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-26679","number":"26679","sourceNumber":"26679","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"O divertículo epifrênico é uma afecção rara que compromete o :","options":{"A":"Esôfago","B":"Cólon direito","C":"Cólon esquerdo","D":"Ílio terminal","E":"Jejuno"},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-10024","number":"10024","sourceNumber":"10024","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente procura o ambulatório de clínica médica com resultado de endoscopia com\ngastrite enantemática leve e Helicobacter pylori positivo. Qual é afirmação correta:","options":{"A":"Todo paciente deve ser tratado para o Helicobacter pylori, independente da lesão encontrada na\nendoscopia.","B":"Paciente com gastrite enantemática não deve ser tratado, mesmo que este solicite o tratamento\nao médico.","C":"O controle do tratamento (nova pesquisa do H. pylori) deve ser verificado em pacientes com\núlcera péptica e no linfoma MALT de baixo grau.","D":"Após o tratamento do H.pylori deve solicitar endoscopia anual para investigação de neoplasia\ngástrica.","E":"O melhor esquema para o tratamento é claritromicina, amoxicilina e ranitidina ou cimetidina por\n14 dias."},"answer":"E","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-10025","number":"10025","sourceNumber":"10025","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente de 30 anos relata pirose, duas vezes por semana, há dois meses e que piora\ncom alimentos gordurosos e cafeinados. Correlacione à afirmação correta.","options":{"A":"O diagnóstico da patologia acima deve ser firmado com endoscopia digestiva.","B":"A Phmetria é o melhor exame para este paciente.","C":"Iniciar o tratamento clínico com inibidor de bomba de prótons por quatro semanas.","D":"Deve avaliar o tratamento cirúrgico com fundoplicatura para diminuir as chances de\ncomplicações.","E":"Solicitar a Endoscopia para avaliar a presença de hérnia de hiato que é principal causa da\ndoença do refluxo gastro-esofágica."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-49436","number":"49436","sourceNumber":"49436","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente, 36 anos de idade, sexo masculino, sem comorbidades maiores, nega etilismo\ne tabagismo, refere tosse noturna, rouquidão e\nepisódios de dor torácica tipo queimor retroesternal,\nprincipalmente após deitar-se. Tem histórico prévio de internação hospitalar recente por\npneumonia. Endoscopia digestiva alta e ecocardiograma normais. O exame padrão-ouro para\ndiagnóstico da afecção em questão é:","options":{"A":"tomografia axial computadorizada de tórax.","B":"pHmetria esofágica.","C":"manometria esofágica.","D":"faringoscopia direta.","E":"angiorressonância do tórax e da região cervical."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-11135","number":"11135","sourceNumber":"11135","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Mulher, 25 anos de idade, residente em zona urbana, vem se queixando de dor\nepigástrica e pirose, que ocorreram em dois\nepisódios de moderada intensidade, durando 1 hora e\nmeia, nos últimos quinze dias. Nega episódios similares antes, bem como vômitos, febre, perda\nponderal ou alteração do ritmo intestinal. Menstruações regulares. Ao exame físico, apresenta bom\nestado geral, IMC igual a 23, mucosas coradas e anictéricas. Sem achado cardiorrespiratório.\n\nAbdome com fígado palpável sob RCD e a 4 cm do Ax, hepatimetria de 12 cm. Baço impalpável. A\nmelhor abordagem nesse caso é:","options":{"A":"realizar ultrassonografia de abdome superior.","B":"fazer teste terapêutico com inibidor de bomba de próton.","C":"medicar com sintomáticos e observar, marcar retorno com 15 dias.","D":"realizar endoscopia digestiva alta.","E":"dosar enzimas hepáticas canaliculares e aminotransferases."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-332615","number":"332615","sourceNumber":"332615","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Isabela, 29 anos, e Carlos, 32 anos, vêm a consulta de puericultura com sua filha\nAmanda, de 2 meses e 15 dias. É sua\nprimeira filha e a gestação foi planejada. Gravidez e parto\nocorreram sem intercorrências. Amanda está em amamentação exclusiva. Entretanto, na última\nconsulta há duas semanas, estava com ganho de peso insuficiente, regurgitação e vômitos. Os pais\nforam tranquilizados quanto a evolução e caráter autolimitado na maioria das crianças e orientados\na diminuir o tempo de oferta, mas aumentar a frequência da amamentação, evitar a manipulação\nexcessiva da filha e ambientes agitados durante e após a alimentação e deixá-la em pé para arrotar\ndepois de comer. Os pais relataram que estavam seguindo as orientações, mas Amanda persistia\ncom vômitos e passou a ficar mais irritada e chorosa. A avaliação da pega e sucção estava\nadequada. O ganho de peso continuou insuficiente e o restante do exame físico estava normal,\nsem febre. Assinale a alternativa que apresenta a conduta para esse caso:","options":{"A":"Deve-se iniciar tratamento empírico com ranitidina ou omeprazol e agendar retorno em 15 dias\npara reavaliação.","B":"Pode-se encaminhar para especialista para descartar doença do refluxo gastroesofágico por\nmeio de exame de pHmetria e/ou endoscopia digestiva alta.","C":"Entre possíveis exames complementares, pode-se solicitar radiografia de esôfago, estômago e\nduodeno com bário para diagnóstico de doença\ndo refluxo gastroesofágico.","D":"Realizar tratamento empírico para infecção urinária, já que é a causa infecciosa mais comum","E":"Solicitar internamento imediato da menor pelo alto risco de desnutrição."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-281873","number":"281873","sourceNumber":"281873","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Pela classificação de Forrest, um paciente com hemorragia digestiva, que apresente um\ncoágulo recente, sem sangramento ativo, sem visualização do coto vascular é classificado em:","options":{"A":"Forrest IB","B":"Forrest IIA","C":"Forrest IIB","D":"Forrest III"},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-249723","number":"249723","sourceNumber":"249723","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Mulher, 58 anos, oriunda de zona rural do estado da Bahia, apresenta disfagia há 15\nanos, que teve início com alimentos\nlíquidos, evoluindo há um ano para sólidos, associada à perda\nde 8kg, além de regurgitação de alimento para cavidade oral após alimentação. Considerando esse\ncaso clínico, a principal suspeita diagnóstica é , e os exames mais adequados\npara investigação são . A alternativa que preenche, correta e\nsequencialmente, as lacunas do trecho acima é","options":{"A":"Esofagite de refluxo / endoscopia digestiva alta, pHmetria e manometria esofágica","B":"Doença do refluxo gastroesofágico / endoscopia digestiva alta e manometria esofágica","C":"Neoplasia de esófago / endoscopia digestiva alta com biopsia e tomografia computadorizada","D":"Megaesôfago Chagásico / endoscopia digestiva alta, esofagograma e manometria esofágica","E":"Megaesôfago Chagásico / tomografia computadorizada, esofagograma e endoscopia digestiva\nalta"},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-181188","number":"181188","sourceNumber":"181188","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"São alterações manométricas encontradas na Acalasia, EXCETO:","options":{"A":"Pressão do Esfíncter esofágico inferior > 26 mmHg.","B":"Relaxamento do Esfíncter esofágico inferior incompleto.","C":"Amplitude pressórica diminuída.","D":"Peristalse Hipertensa."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-157718","number":"157718","sourceNumber":"157718","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Sobre os divertículos gastrointestinais, marque a alternativa CORRETA.","options":{"A":"O melhor exame para a confirmação diagnóstica do divertículo de Zenker é a Endoscopia\nDigestiva alta.","B":"O duodeno é o segundo sítio mais comum de divertículos no aparelho digestivo, perdendo\napenas para o esôfago.","C":"O divertículo de Meckel é um divertículo verdadeiro, e está localizado na maioria dos casos no\njejuno.","D":"Mucosa ectópica pode ser encontrada em até 60% dos casos de divertículo de Meckel, e o\ntecido ectópico mais comum é o gástrico."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-139746","number":"139746","sourceNumber":"139746","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"O principal sintoma relacionado à Doença do Refluxo Gastroesofágico é a pirose ou\nqueimação retroesternal. O segundo sintoma mais prevalente é:","options":{"A":"Tosse.","B":"Disfonia.","C":"Vômitos.","D":"Regurgitação."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-139749","number":"139749","sourceNumber":"139749","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A acalasia é um distúrbio da motilidade primária do esôfago que se caracteriza por falha\nno relaxamentodo esfíncter:","options":{"A":"superior do esôfago nas deglutições e ausência de peristalse no corpo esofágico.","B":"inferior do esôfago nas deglutições e presença de peristalse no corpo esofágico.","C":"inferior do esôfago nas deglutições e ausência de peristalse no corpo esofágico.","D":"superior do esôfago nas deglutições e presença de peristalse no corpo esofágico."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-134679","number":"134679","sourceNumber":"134679","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A acalasia é um distúrbio da motilidade primária do esôfago, que se caracteriza por\nfalha no relaxamento do esfíncter:","options":{"A":"superior do esôfago nas deglutições e ausência de peristalse no corpo esofágico.","B":"inferior do esôfago nas deglutições e presença de peristalse no corpo esofágico.","C":"inferior do esôfago nas deglutições e ausência de peristalse no corpo esofágico.","D":"superior do esôfago nas deglutições e presença de peristalse no corpo esofágico."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-111839","number":"111839","sourceNumber":"111839","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Divertículos são formações saculares em fundo cego que podem estar localizados em\nvárias partes do corpo humano. Os divertículos de Zenker localizam-se no:","options":{"A":"esôfago superior.","B":"intestino grosso.","C":"intestino delgado.","D":"esôfago inferior."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-111913","number":"111913","sourceNumber":"111913","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Homem de 48 anos com dor epigástrica e subesternal em queimação crônica (há 4\nmeses). Relata que os sintomas pioram ao\ndeitar-se e após refeições. Nega dificuldade para engolir\nou perda de peso. Usou inibidor da bomba de prótons regularmente nas últimas 6 semanas com\nmelhora parcial dos sintomas. Relata ainda sibilância e rouquidão pela manhã. O resto da história e\nexame clínico é normal. Em se tratando de refluxo gastroesofágico dos mecanismos a seguir,\nsempre contribuem para esse processo patológico, EXCETO:","options":{"A":"anormalidades do esfíncter esofágico inferior.","B":"esvaziamento prejudicado do esôfago.","C":"barreiras esofágicas anormais à exposição ao ácido.","D":"hérnia hiatal."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-111828","number":"111828","sourceNumber":"111828","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A Acalasia é um distúrbio da motilidade primária do esôfago que se caracteriza por\nfalha no relaxamento do esfíncter:","options":{"A":"superior do esôfago nas deglutições e ausência de peristalse no corpo esofágico.","B":"inferior do esôfago nas deglutições e presença de peristalse no corpo esofágico.","C":"inferior do esôfago nas deglutições e ausência de peristalse no corpo esofágico.","D":"superior do esôfago nas deglutições e presença de peristalse no corpo esofágico."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-350870","number":"350870","sourceNumber":"350870","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Mulher de 27 anos comparece ao consultório do cirurgião com queixa de dificuldade de\ndeglutição intensa. Refere não conseguir ingerir sólidos há cerca de 1 semana. Desde então, vinha\nem dieta pastosa, porém refere ainda sensação de entalo e dor retroesternal. Paciente refere\nardência retroesternal desde a adolescência que piorava após tomar refrigerantes e comidas\ncondimentadas. A paciente realizou endoscopia com biopsia que foi compatível com estenose\npéptica esofágica. Qual deve ser a conduta para essa paciente, nesse momento?","options":{"A":"Cirurgia de Nissen antirrefluxo videolaparoscópica.","B":"Inibidores de bomba de prótons e sonda nasoenteral.","C":"Dilatação endoscópica e inibidores de bomba de prótons.","D":"Passagem de \"stent\" endoscópico e investigação com tomografia."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-321281","number":"321281","sourceNumber":"321281","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Mulher de 55 anos, IMC 27, é submetida a cirurgia para correção de hérnia hiatal\nassociada a doença antirrefluxo. A indicação\nda cirurgia foi sintomas recorrentes após suspensão\nda terapia clínica por diversas tentativas ao longo de 4 anos. Os exames pré-operatórios\ndemonstravam: endoscopia com esofagite grau B de Los Angeles, pHmetria refluxo ácido anormal\ncom indice DeMeester elevado e manometria com esficter esofageano com baixa pressão, sem\nalterações de motilidade do corpo esofágico. A cirurgia realizada há 10 dias foi uma válvula\nantirreflexo do tipo Nissen, por videolaparoscopia. Atualmente, a paciente queixa-se de dificuldade\npara deglutir dieta espessa e sólidos. Tolera dieta líquida e semipastosa. A paciente está bastante\nangustiada pois não consegue progredir a dieta devido a disfagia e sensação de \"bolus\"\nretroesternal durante essas refeições. Qual deve ser a conduta para essa paciente nesse\nmomento?","options":{"A":"Regredir à dieta para líquida, aguardar nova tentativa de evolução da dieta, após alguns dias.","B":"Realizar uma revisão cirúrgica por videolaparoscopia e retirar pontos do fechamento dos pilares.","C":"Indicar dilatação pneumática endoscópica para alívio da tonicidade do esfíncter esofágico\ninferior.","D":"Solicitar um manometria para estudo da causa da disfagia, motilidade esofágica e competência\nvalvar."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-292807","number":"292807","sourceNumber":"292807","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Na investigação de um paciente com queixa de disfagia, qual exame serve para\norientar condutas clínicas e cirúrgicas, demonstrando pontos de estenose, estase, aspecto da\nmucosa e coleta de fragmentos? Qual dos exames atende a essa necessidade?","options":{"A":"Manometria de alta resolução.","B":"Endoscopia digestiva alta.","C":"Cintilografia esofágica.","D":"Esofagograma digital."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-234014","number":"234014","sourceNumber":"234014","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Um paciente de 38 anos medindo 1,70m e pesando 72 kg, estava em\nacompanhamento cli?nico em unidade ba?sica de\nsau?de e foi referido a um servic?o de cirurgia. O\npaciente relatou que ha? dois anos tem quadro de pirose retroesternal, mesmo em ortostase, com\npiora apo?s as refeic?o?es, associado a? disfonia intermitente, tosse seca e pigarro dia?rio. Ao\nexame fi?sico, apresentava somente leve desconforto a? palpac?a?o profunda no epigastro.\n\nRelatava etilismo social e negava tabagismo. Ao longo desse peri?odo, fez uso de pantoprazol 40\nmg e a endoscopia digestiva alta\ncompati?vel com esofagite grau III de Savary-Miller. Foi solicitada,\nna atenc?a?o especializada, manometria esofa?gica que evidenciou hipotonia acentuada do\nesfi?ncter esofageano inferior e dismotilidade moderada do corpo esofa?gico. A pHmetria\nesofa?gica evidenciou registro na sonda proximal de 10 episo?dios de pH inferior a 4. Qual a\nconduta a ser proposta ao paciente?","options":{"A":"Sugerir a indicac?a?o de tratamento ciru?rgico por meio de fundoplicatura\nvi?deo-laparosco?pica.","B":"Dobrar a dose do pantoprazol, associar medicac?a?o pro?-cine?tica em dose plena e reforc?ar\norientac?o?es diete?ticas-comportamentais.","C":"Manter o tratamento cli?nico, associar medicac?a?o pro?-cine?tica em dose plena e reforc?ar\norientac?o?es diete?ticas-comportamentais.","D":"Manter o tratamento cli?nico, reforc?ar orientac?o?es diete?ticas-comportamentais e associar\ntratamento endosco?pico da dismotilidade."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-173009","number":"173009","sourceNumber":"173009","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Um paciente de 41 anos tem queixas de rouquidão crônica e queimação retroesternal\nhá 8 anos. Faz uso de bloqueador de bombas de\nprótons há pelo menos 4 anos, continuamente.\nHábitos tabagistas desde 20 anos, meio maço de cigarro nos finais de semana. Apresenta IMC de\n\n26. Refere vida agitada sem horários organizados ou refeições equilibradas. A última endoscopia\ndemonstra esofagite grau A de Los Angeles com área sugestiva de Barret curto. Qual dos\ntratamentos propostos apresenta maior chance de controlar a doença do refluxo desse paciente e\nsuas consequentes complicações?","options":{"A":"Cirurgia antirrefluxo pela técnica de Nissen.","B":"Organização do estilo de vida e mudanças de hábitos alimentares.","C":"Suspensão do uso do cigarro e acompanhamento para perda de peso.","D":"Uso de dose dobrada do bloqueador de bomba de próton e associação de procinéticos."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-172980","number":"172980","sourceNumber":"172980","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente de 18 anos, feminina, é atendida no ambulatório por queixa de epigastralgia.\nRefere que a dor é \"em ardência\", em\nepigástrio, sem irradiações, sem piora com movimentação,\nporém, melhora com ingesta alimentar (aumento de peso de 3kg no período dos sintomas). Relata\nque o quadro se iniciou há 3 meses, sendo observado com frequência diária. Nega sangramentos\nou melena. Exame físico normal. Não há histórico familiar patológico relevante e a paciente era\npreviamente saudável. Não havia histórico de uso de medicações. Exames laboratoriais\n(hemograma, proteína C reativa, creatinina e tireotropina) estavam normais. Qual a conduta mais\napropriada nesse momento?","options":{"A":"Indicar realização de endoscopia digestiva alta.","B":"Pesquisar antígeno fecal para Helicobacter pylori.","C":"Realizar tratamento para Helicobacter pylori.","D":"Prescrever bloqueador de bomba de prótons."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-150840","number":"150840","sourceNumber":"150840","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Homem de 24 anos procurou atendimento médico com queixa de há 01 ano ter iniciado\nquadro de pirose retroesternal, associado à regurgitação de alimentos digeridos. Recentemente,\napresenta certa disfagia a alimentos sólidos. Faz uso de inibidores de bomba de prótons, os quais\nmelhoram a pirose, mas após a interrupção dos mesmos há recorrência dos sintomas em poucos\ndias. Exames: endoscopia digestiva alta ? esofagite de refluxo com ulcerações convergentes (grau\n3 de Savary-Miller), gastrite enantematosa leve e uma hérnia de hiato por deslizamento de 3 cm;\nmanometria esofágica ? hipocontratilidade do esfíncter esofagiano inferior e aumento da duração\ndas ondas em esôfago distal; pHmetria esofágica ? refluxo gastroesofágico patológico em decúbito\ndorsal e em ortostase. Hábitos: tabagista há 6 anos, de 1 maço de cigarros/dia. IMC: 28 kg/m². Para\no tratamento das queixas atuais desse paciente, qual a melhor conduta?","options":{"A":"Indicar cirurgia com realização de válvula antirrefluxo de 360 graus.","B":"Substituir por bloqueadores H2, dose alta, e promover a perda de peso.","C":"Dobrar a dose do inibidor de bomba de prótons e associar agentes procinéticos.","D":"Promover modificações dietéticas e nos hábitos de vida (cessar o tabagismo, fracionar dieta\netc.)."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-126964","number":"126964","sourceNumber":"126964","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Homem, de 42 anos, entrou no consultório com queixa de disfagia, que se iniciou há 1\nano. Evoluiu com piora passando a comer vagarosamente e ingerindo grandes volumes de água.\nRelata uma sensação de obstrução ao nível do xifoide, após a ingesta de líquidos, especialmente\nos gelados. Há 3 meses, vem apresentando piora dos sintomas passando a melhorar somente\nquando apresenta algum grau de regurgitação. Perdeu neste último período 10 Kg, dos 80 Kg\nhabituais. Ao exame físico, encontra-se pouco distrófico, levemente hipocorado, com ausculta\npulmonar sem ruídos adventícios e abdome discretamente escavado, indolor, sem massas ou\nvisceromegalias palpáveis. Qual exame esclareceria melhor a natureza dessa obstrução?","options":{"A":"Esofagograma.","B":"Manometria esofágica.","C":"Endoscopia digestiva alta.","D":"Tomografia com contraste."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-126992","number":"126992","sourceNumber":"126992","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente de 40 anos, sexo masculino, é avaliado em consultório por queixa de pirose\nretroesternal principalmente após refeições, piorando com ingesta de alguns alimentos\ncondimentados. Refere que o quadro iniciou-se há cerca de 5 anos e coincidiu com ganho de peso\napós abandonar atividades esportivas. Não fuma e, raramente ingere bebidas alcoólicas. Nega\npatologias associadas. Exame físico evidencia somente sobrepeso. Já traz endoscopia digestiva\nalta com esofagite leve, sem outras alterações. Relata ter feito as modificações de estilo de vida\ncabíveis (corrigindo refeições e hábitos) conforme orientações médicas prévias. Está, ainda, em\nuso diário de pantoprazol 40 mg antes do café da manhã há 4 semanas, mas nega melhora do\nquadro clínico apesar de tudo. Qual conduta deve ser tomada da condução desse caso, no\nmomento?","options":{"A":"Associar antagonista do receptor H2.","B":"Mudar prescrição para 40 mg 2x/dia.","C":"Aumentar dose para 80 mg pela manhã.","D":"Trocar por outro bloqueador de bomba."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-102133","number":"102133","sourceNumber":"102133","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Sr. João, 65 anos, é diagnosticado com carcinoma epidermoide de esôfago médio,\natingindo a submucosa e, por essa razão, é indicada para esofagectomia. Na avaliação\n\npré-operatória, é submetido a um cateterismo coronariano que demonstra obstrução de 50% de\nartéria descendente anterior. Outros exames pré-operatórios normais. Nega outras comorbidades,\npaciente é ex- tabagista, não apresenta sintomas cardiovasculares, faz caminhada acelerada de 4\nkm cinco vezes por semana. Diante do quadro, qual deve ser a conduta em relação a esse\npaciente?","options":{"A":"Encaminhar para realização da esofagectomia.","B":"Realizar angioplastia de coronária, antes da esofagectomia.","C":"Realizar revascularização do miocárdio, antes da esofagectomia.","D":"Contraindicar esofagectomia, devido ao alto risco cardiovascular."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-102121","number":"102121","sourceNumber":"102121","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente de 38 anos, sexo masculino, é encaminhado ao ambulatório de cirurgia para\ninvestigação de disfagia há mais de dois anos. A endoscopia digestiva alta mostra esôfago dilatado,\no esofagograma mostra esôfago com 11 cm de diâmetro de aspecto sinuoso e a manometria\nesofágica apresenta esfíncter esofagiano inferior com pressão de 45 mmHg, falha no relaxamento\ndeste e ondas esofágicas de baixa amplitude. Qual a melhor conduta para esse caso?","options":{"A":"Dilatação pneumática do EEI.","B":"Esofagectomia laparoscópica.","C":"Esofagocardiomiotomia à Heller por vídeo.","D":"Injeções de toxina botulínica diretamente no EEI."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-102155","number":"102155","sourceNumber":"102155","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente masculino, 58 anos, apresentando dor em hipocôndrio direito, sensação de\nqueimação epigástrica e retroesternal e regurgitação recorrentes, há 60 dias. Apresenta também\ndiarreia aquosa, sem muco ou pus, intermitente, há 90 dias. Nega tabagismo e etilismo. Refere\nperda de 5 kg no período. Endoscopia digestiva evidenciou três úlceras duodenais, tratadas com\nomeprazol, com persistência dos sintomas. Com base nos achados clínicos e considerando a\nprincipal hipótese diagnóstica, qual dosagem laboratorial deve ser solicitada na investigação\ndiagnóstica?","options":{"A":"Gastrina.","B":"Calcitonina.","C":"Somatostatina.","D":"Peptídeo intestinal vasoativo."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-102171","number":"102171","sourceNumber":"102171","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Ao atender uma criança de três dias de vida, com conjuntivite por provável Clamídia, o\nmédico prescreve eritromicina oral. Após duas semanas, a criança necessita fazer uma cirurgia por\num possível efeito adverso desse antibiótico nessa faixa de idade. Assinale a alternativa que\ncontém a condição sugerida nesse caso?","options":{"A":"Estenose hipertrófica do piloro.","B":"Intussuscepção intestinal.","C":"Divertículo de Meckel.","D":"Má rotação intestinal."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-65759","number":"65759","sourceNumber":"65759","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente de 55 anos, masculino, obeso, refere dor em queimação retroesternal após a\nalimentação, desde os 30 anos de idade. Fez endoscopia digestiva alta, que mostrou área de\nmucosa cor salmão nos 4 cm distais do esôfago. A histologia dos 2 cm proximais desta área\ndescreveu metaplasia intestinal, com área de displasia de baixo grau. Qual a melhor recomendação\nde conduta para este paciente?","options":{"A":"Nova endoscopia com biópsia em 6 meses.","B":"Nova endoscopia com biópsia imediatamente.","C":"Ressecção endoscópica da mucosa lesada.","D":"Terapia fotodinâmica endoscópica.","E":"Esofagectomia distal."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-36950","number":"36950","sourceNumber":"36950","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Homem de 54 anos é atendido na emergência com queixa de dor de início súbito em\nabdome superior, seguido de dor em todo o\nabdome há 5 horas. Apresenta-se sudoreico e agitado.\nNo exame, o abdome é tenso e doloroso, a PA é de 160 X 90 mmHg e pulso de 115 bpm. Durante\na laparotomia, o cirurgião detecta uma úlcera gástrica perfurada tipo I. Qual o procedimento mais\nindicado nesse caso?","options":{"A":"Gastrectomia subtotal sem vagotomia.","B":"Gastrectomia parcial com reconstrução a BII.","C":"Antrectomia com reconstrução a BI.","D":"Rafia da úlcera com proteção de omento."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-36960","number":"36960","sourceNumber":"36960","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Mulher de 43 anos é tratada por ter úlceras há 1 ano. Já apresentou úlceras esofágicas,\ngástricas, duodenais e, atualmente, apresenta\nmúltiplas úlceras de 1 a 1,5 cm no estômago, 1ª e 2ª\nporção do duodeno. Qual a principal suspeita diagnóstica?","options":{"A":"Úlcera refratária por contaminação por Helicobacter pylori.","B":"Síndrome de Turcot com úlceras de estresse.","C":"Síndrome de Zollinger-Ellison por neoplasia\nneuroendócrina.","D":"Doença de Ménétrier gástrica."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-32534","number":"32534","sourceNumber":"32534","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Sobre a úlcera péptica, marque a alternativa INCORRETA.","options":{"A":"Resulta do desequilíbrio entre fatores protetores e agressores da mucosa.","B":"Mais de 50 % dos portadores de úlcera gástrica e mais de 90% dos portadores de úlcera\nduodenal têm associação com infecção por H. pylori.","C":"O uso de AINE (anti-inflamatórios não esteroidais) está associado a muitos casos de úlcera\ngástrica.","D":"Cerca de 75% dos pacientes com infecção por H. pylori terão, em algum momento da vida, o\ndiagnóstico de úlcera péptica.","E":"O tratamento cirúrgico da doença ulcerosa péptica foi substituído nos últimos anos pela\nabordagem clínica e medicamentosa."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-36983","number":"36983","sourceNumber":"36983","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente em investigação de dispepsia ulcerosa comparece com resultado de\nendoscopia digestiva, alta, revelando duas pequenas úlceras no fundo gástrico. Não apresenta\noutras comorbidades. Qual o fator etiológico mais provável?","options":{"A":"H pylori.","B":"Tabagismo.","C":"Uso de anti-inflamatório.","D":"Infecção por citomegalovírus."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-37419","number":"37419","sourceNumber":"37419","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A ingestão de querosene por crianças ocorre, principalmente, em famílias de nível\nsocioeconômico menos favorecido, que conservam o líquido dentro de garrafas de refrigerantes ao\nalcance fácil das crianças. A conduta correta diante de uma criança que ingere querosene é:","options":{"A":"Lavagem gástrica com soro gelado.","B":"Uso de óleo mineral por sonda nasogástrica para diminuir a absorção de hidrocarbonetos.","C":"Uso de corticoide para evitar a pneumonia química.","D":"Tratamento de suporte com monitorização respiratória, renal e neurológica.","E":"Nenhuma das alternativas anteriores."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-24318","number":"24318","sourceNumber":"24318","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Com relação à fisiopatologia da acalasia esofágica, assinale a alternativa ERRADA:","options":{"A":"Dentre as alterações encontradas observa-se destruição do plexo nervoso intramural de\nAuerbach.","B":"Perda do caráter peristáltico, principalmente no 1/3 superior do esôfago.","C":"Alterações do núcleo dorsal do nervo vago.","D":"Ectasia do esôfago na fase tardia."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-24330","number":"24330","sourceNumber":"24330","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente do sexo masculino, 39 anos, dá entrada pela manhã na emergêcia do IJF com\nquadro de forte dor abdominal iniciada naquela madrugada. Além da dor, o paciente refere\nnáuseas, vômitos e sudorese. Ao exame apresenta fácies de sofrimento, normocorado, desidratado\n(++/4+), taquicárdico (120 ppm), sudorêico e levemente taquipnéico. Ausculta cardiopulmonar\nnormal e o abdome tenso, bastante doloroso à palpação, com sinais difusos de irritação peritoneal.\nOs exames de laboratório mostram uma discreta leucocitose e demais exames normais, incluindo\namilase. Rx de tórax e abdômen e ultrassonografia abdominal são normais. Qual o diagnóstico\nmais provável para esse caso?","options":{"A":"Úlcera péptica perfurada.","B":"Pancreatite aguda.","C":"Apendicite aguda.","D":"Trombose mesentérica."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-22946","number":"22946","sourceNumber":"22946","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Sobre a relação entre H. pylori e doença ulcerosa péptica, assinale o item correto.","options":{"A":"A recorrência da doença ulcerosa péptica é frequente mesmo após a erradicação da bactéria","B":"75% das úlceras duodenais e > 90% das úlceras gástricas estão relacionadas com a infecção\npelo H. pylori","C":"O H. pylori um fraco produtor de urease, enzima conversora de ureia em bicarbonato e amônia","D":"A fisiopatologia da úlcera deve-se ao fato do H. pylori destruir as células D gástricas,\ninibindo o\nfeedback negativo da produção de gastrina","E":"As cepas virulentas do H. pylori"},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-24347","number":"24347","sourceNumber":"24347","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Mulher de 35 anos internada na enfermaria do IJF com diagnóstico de esofagite\ncaústica grave pós-ingestão de soda caústica.\nNo 4º dia de internação, evolui com dor torácica e\ndispnéia. O raio X de tórax da ocasião evidencia volumoso derrame pleural à esquerda e sinais de\npneumomediatino. A bioquímica do líquido pleural colhido por toracocentese revelou níveis de\namilase elevados. Que complicação justificaria os achados acima?","options":{"A":"Pancreatite aguda","B":"Rotura do esôfago","C":"Embolia pulmonar","D":"Abscesso do mediastino"},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-22963","number":"22963","sourceNumber":"22963","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A doença do refluxo gastroesofágico (DRGE) é uma patologia relacionada ao déficit de\nfuncionamento do esfíncter esofágico inferior, tanto quando a zona alta de pressão é baixa o\nsuficiente para permitir a passagem do conteúdo gástrico quanto por um relaxamento espontâneo\nde um esfíncter normal não associado a uma onda peristáltica. Baseado nessas afirmativas,\nassinale o item correto.","options":{"A":"A apresentação de pacientes com DRGE inclui uma clínica escassa sem sinais indicativos da\ndoença, além de uma ausência de sintomas de progressão","B":"A endoscopia é um exame dispensável no diagnóstico de DRGE por não poder demonstrar\nclaramente sinais da doença","C":"O tratamento farmacológico da DRGE foi revolucionado pelos inibidores de bomba de prótons,\nque se mostraram mais efetivos nas\ncicatrizações de úlceras esofágicas ácidas que os\nbloqueadores H2","D":"Pacientes com sintomas de longa duração ou aqueles nos quais os sintomas persistem numa\nidade precoce não devem ser considerados para tratamento cirúrgico de princípio","E":"Pacientes que não possuem nenhuma resposta dos seus sintomas com o uso de inibidores de\nbomba de prótons, devem ser encaminhados, em\nseguida, para um tratamento cirúrgico"},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-24363","number":"24363","sourceNumber":"24363","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Em relação à lesão aguda da mucosa gástrica (LAMG) induzida por antiinflamatórios\nnão esteróides (AINES), é CORRETO afirmar:","options":{"A":"A maioria dos pacientes que apresenta hemorragia digestiva grave secundária a LAMG\napresentava sintomas dispépticos prévios ao uso de AINES.","B":"Doses menores que 100 mg de AAS são seguras, não apresentando risco para o aparecimento\nde LAMG.","C":"A Infecção por H. pylori, possivelmente, é um fator de risco para o desenvolvimento da LAMG\nsecundária a AINES.","D":"As preparações de AINES com revestimento entérico não apresentam risco para o aparecimento\nde ulcerações pépticas na LAMG."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-24302","number":"24302","sourceNumber":"24302","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Quanto à doença acidopéptica, marque a opção verdadeira:","options":{"A":"A infecção pelo Helicobacter pylori tem relação direta e bem definida com a doença do refluxo.","B":"A úlcera duodenal merece controle endoscópico seriado pelo risco de evolução para\nadenocarcinoma.","C":"O uso prolongado dos inibidores de bomba de prótons está proscrito em todas as situações pelo\nrisco de atrofia gástrica.","D":"A dispepsia não ulcerosa demanda, por vezes, erradicação do Helicobacter pylori para controle\nsintomático."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-27766","number":"27766","sourceNumber":"27766","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Sobre lesões gástricas marque a opção correta.","options":{"A":"A gastrite hipertrófica (Doença de Ménetrier) é uma doença rara, adquirida sem relação com o\ncâncer gástrico.","B":"A laceração de Mallory-Weiss está relacionada com o uso crônico de AAS (ácido acetilsalicílico)","C":"A lesão gástrica de Dieulafoy é causada por uma artéria tortuosa que faz um trajeto através da\nsua mucosa gástrica.","D":"Os bezoares (tricobezoares) geralmente resolvem-se com tratamento clínico.","E":"As varizes gástricas devido à trombose da veia esplênica são tratadas preferencialmente por via\nendoscópica."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-27746","number":"27746","sourceNumber":"27746","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Sobre as doenças que acometem o esôfago podemos afirmar que:","options":{"A":"os GIST (tumores do estroma gastrintestinais) do esôfago são mais comuns no esôfago cervical.","B":"os divertículos epifrênicos estão localizados no terço proximal do esôfago e à direita.","C":"o divertículo de Zenker é o mais comum divertículo esofágico e está relacionado com hipertonia\ncricofaríngea.","D":"as membranas esofágicas inferiores (anel de Schatzki) predispõem a esofagite e ao refluxo\ngastresofágico.","E":"as membranas esofágicas superiores (síndrome de Plummer-Vinson) se desenvolvem em\npacientes com deficiência crônica de vitamina B12."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-27712","number":"27712","sourceNumber":"27712","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Sobre a DRGE (doença do refluxo gastresofágico) podemos afirmar:","options":{"A":"a dor retroesternal tipo compressão é típica na DRGE.","B":"o padrão-ouro para o diagnóstico da DRGE é a manometria do esôfago associada com a\nendoscopia.","C":"o tratamento de escolha da DRGE na presença de ulceração esofágica e/ou mucosa de Barrett\né o com inibidores da bomba de prótons.","D":"A mais comum complicação intra-operatória do tratamento cirúrgico da DRGE é o pneumotórax.","E":"a disfagia pós?operatória ocorre em mais de 80% dos pacientes submetidos a tratamento\ncirúrgico para DRGE."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-6930","number":"6930","sourceNumber":"6930","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Homem de 40 anos com queixa de pirose traz uma endoscopia que revelou esôfago de\nBarrett longo. O exame histopatológico confirma esôfago de Barrett sem displasia. A melhor\nconduta a seguir é:","options":{"A":"Observação.","B":"Inibidor de bomba de prótons.","C":"Válvula antirrefluxo.","D":"Ablação a Laser.","E":"Ressecção."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-9027","number":"9027","sourceNumber":"9027","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Um dos principais exames para o diagnóstico da acalasia é a manometria esofágica.\nQual das alterações abaixo NÃO corresponde a um\ncritério manométrico comumente encontrado\nnessa situação?","options":{"A":"Aperistalse do corpo esofágico","B":"Pressão do esfíncter esofagiano inferior (EEI) normal ou < 15 mmHg","C":"Ausência ou relaxamento parcial do EEI após a deglutição","D":"Pressão intraesofágica basal maior que a intragástrica"},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-9031","number":"9031","sourceNumber":"9031","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Com relação aos divertículos epifrênicos, é correto afirmar, EXCETO:","options":{"A":"São divertículos de pulsão que aparecem no terço distal do esôfago","B":"Na maioria das vezes, acomete pacientes portadores de um distúrbio de motilidade onde estão\npresentes sintomas como disfagia, regurgitação, vômitos, dor torácica, tosse e perda de peso","C":"Embora o exame contrastado defina melhor a presença de divertículos, estudos de motilidade\nsão necessários para a conclusão diagnóstica","D":"O tratamento cirúrgico, quando indicado, inclui sua ressecção e uma miotomia do esfíncter\nesofagiano superior."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-6906","number":"6906","sourceNumber":"6906","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Mulher de 55 anos em uso crônico de anti-inflamatório não esteroidal apresenta quadro\nde hemorragia digestiva alta vultosa. Após a\nestabilização hemodinâmica, realizou endoscopia que\nmostrou úlcera na 1ª porção duodenal, na parede posterior, recoberta por grande coágulo. Neste\nmomento foi tratada com injeção de adrenalina. A paciente permaneceu sob observação rigorosa,\nquando em menos de 24 horas apresentou hipotensão e enterorragia. Qual o procedimento melhor\nindicado para esta paciente?","options":{"A":"Repetir a endoscopia com esclerose.","B":"Vagotomia com piloroplastia e ulcerorrafia.","C":"Vagotomia e gastrojejunostomia.","D":"Vagotomia e gastrectomia parcial.","E":"Gastrectomia subtotal."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-7278","number":"7278","sourceNumber":"7278","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"O esfíncter esofágico inferior (EEI) é mais precisamente referido como o mecanismo\nEEI ou a zona de alta pressão esofágica distal\n(ZAP). São fatores que diminuem o tônus da ZAP:","options":{"A":"gastrina, colecistocinina.","B":"histamina, neperidina.","C":"atropina, hérnia de hiato.","D":"metoclopromida, ethanol.","E":"nicotina, operação antirrefluxo."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-9023","number":"9023","sourceNumber":"9023","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Em relação à DRGE é CORRETO afirmar:","options":{"A":"A maior parte dos portadores de DRGE apresenta erosões esofágicas ao exame endoscópico.","B":"Não há correlação entre piora dos sintomas e aparecimento do esôfago de Barrett.","C":"A prova terapêutica com IBP, por quatro semanas, deve ser utilizada em todos os pacientes com\nsintomas de DRGE.","D":"A pHmetria esofágica é indispensável para o diagnóstico da DRGE."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-8834","number":"8834","sourceNumber":"8834","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Em um paciente com síndrome de obstrução pilórica, esperamos encontrar os\nseguintes distúrbios eletrolíticos e acidobásicos:","options":{"A":"Hipocalemia, hipomagnesemia e alcalose metabólica.","B":"Hipocloremia, hipocalemia e alcalose metabólica.","C":"Hiponatremia, hipocalemia e acidose metabólica.","D":"Hipocalemia, hipercloremia e alcalose metabólica.","E":"Hipocloremia, hipomagnesemia e alcalose metabólica."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-8861","number":"8861","sourceNumber":"8861","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Assinale a opção que contém uma correlação INCORRETA de doença esofágica e seu\ntratamento:","options":{"A":"Disfagia cervical esofágica associada à deficiência de ferro - Dilatação esofágica e correção do\ndefeito nutricional.","B":"Disfagia esofágica devido a anel de Schatzki e refluxo - Dilatação esofágica e inibidor de bomba\nde prótons.","C":"Disfagia severa devido a esfíncter superior esofágico anormal - Esofagomiotomia.","D":"Acalasia esofágica discreta (tipo I ou II) - Dilatação do esfíncter inferior e/ou procinéticos.","E":"Espasmo esofágico difuso grave - Esofagectomia trans-hiatal."},"answer":"E","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-8870","number":"8870","sourceNumber":"8870","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Assinale a opção INCORRETA sobre úlcera péptica.","options":{"A":"A formação de úlcera requer secreção de ácido, pepsina em associação de H. pylori ou ingestão\nde anti-inflamatórios.","B":"O melhor tratamento para um paciente com úlcera duodenal perfurada de poucas horas é rafia\nda úlcera com manchão de omento por laparoscopia.","C":"O melhor tratamento para um paciente com obstrução duodenal por úlcera é, se possível,\nantrectomia e vagotomia.","D":"O tratamento cirúrgico eletivo de úlcera não complicada é raro mesmo com métodos\nminimamente invasivos (vagotomias por laparoscopia).","E":"As úlceras pépticas com complicações como sangramento, perfuração e obstrução diminuíram\nmuito na era dos inibidores de bomba de\npróton."},"answer":"E","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-17840","number":"17840","sourceNumber":"17840","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Na segmentação cirúrgica do fígado este é dividido em quantos segmentos:","options":{"A":"4","B":"6","C":"8","D":"10","E":"12"},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-307095","number":"307095","sourceNumber":"307095","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Um paciente de 45 anos de idade compareceu à consulta com queixa de disfagia.\nRefere que apresenta disfagia para alimentos\nsólidos, de início há sete meses, e de caráter\nprogressivo, atualmente com dificuldade de ingestão de líquidos. O esofagograma baritado é\nnormal e não apresenta megaesôfago. A manometria esofágica apresenta aperistalse no corpo\nesofágico e hipertonia do esfíncter esofágico inferior. Nesse caso clínico, o diagnóstico mais\nprovável é:","options":{"A":"Hérnia de hiato esofágico.","B":"Espasmo esofagiano difuso.","C":"Esôfago em quebra-nozes.","D":"Doença do refluxo gastroesofágico.","E":"Acalásia."},"answer":"E","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-349774","number":"349774","sourceNumber":"349774","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"No caso de um paciente que realizou gastrectomia parcial e tem apresentado, 20\nminutos após a ingesta alimentar, sintomas\ncomo náuseas, vômitos, sensação de plenitude\ngástrica, diarreia explosiva, palpitações e taquicardia, qual é o provável diagnóstico e a\norientação\nque o médico deve fornecer para a melhora dos sintomas?","options":{"A":"Dumping tardio / Orientar a evitar hipoglicemia, ingerindo maiores quantidades de alimentos com\naçúcar em um menor intervalo de tempo.","B":"Síndrome da alça aferente / Orientar o paciente a provocar vômitos quando tiver os sintomas de\nplenitude gástrica, pois geralmente gera um alívio imediato dos sintomas.","C":"Gastrite alcalina de refluxo / Orientar o paciente a utilizar inibidor de bomba de prótons a\ncada 12\nhoras e evitar a ingestão de alimentos ácidos.","D":"Atonia gástrica / Utilizar pró-cinéticos como a metoclopramida e fazer a ingestão de várias\nrefeições com menores quantidades de alimentos.","E":"Dumping precoce / Orientar a evitar alimentos que contenham grande quantidade de açúcar,\nrealizar pequenas refeições com proteínas e\ngorduras em menor intervalo de tempo e separar os\nlíquidos dos sólidos durante as refeições."},"answer":"E","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-305278","number":"305278","sourceNumber":"305278","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente com queixa de pirose, azia e regurgitações procura orientações sobre um\npossível diagnóstico de Doença do Refluxo Gastroesofágico (DRGE) e tratamento. Assinale a\nalternativa que apresenta somente informações CORRETAS que poderão ser fornecidas a esse\npaciente.","options":{"A":"O exame padrão-ouro para o diagnóstico é a endoscopia digestiva alta. A DRGE pode ser\ncausada por hérnia hiatal do tipo I, chamada de hérnia de rolamento.","B":"O melhor exame para o diagnóstico é a manometria. A DRGE pode ser causada por hérnia hiatal\ndo tipo II, chamada de hérnia por\ndeslizamento.","C":"O melhor exame para o diagnóstico é a pHmetria de 24h. A DRGE pode ser causada por hérnia\nhiatal do tipo II, conhecida como hérnia de rolamento.","D":"O melhor exame para o diagnóstico é a esofagografia. A DRGE pode ser causada por hérnia\nhiatal do tipo II, chamada de hérnia por rolamento.","E":"O exame padrão-ouro para diagnóstico é a pHmetria de 24h. A DRGE pode ser causada por\nhérnia hiatal do tipo III, chamada de hérnia por deslizamento."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-274347","number":"274347","sourceNumber":"274347","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Assinale a alternativa que corresponde aos 3 locais anatômicos de estreitamento do\nesôfago.","options":{"A":"Constrição pelo músculo milo-hióideo, constrição traqueal e constrição gastroesofágica.","B":"Constrição pelo músculo cricofaríngeo, constrição broncoaórtica e constrição diafragmática.","C":"Constrição pelo músculo omo-hióideo, constrição brônquica e constrição pericárdica.","D":"Constrição pelo músculo cricofaríngeo, constrição traqueal e constrição gastroesofágica.","E":"Constrição pelo músculo tireofaríngeo, constrição broncoaórtica e constrição gastroesofágica."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-274348","number":"274348","sourceNumber":"274348","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Assinale a alternativa que corresponde ao tipo de hérnia mais comum que gera\nsintomas de refluxo gastroesofágico.","options":{"A":"Hérnia hiatal por deslizamento.","B":"Hérnia de Spiegel.","C":"Hérnia de Zenker.","D":"Hérnia epigástrica.","E":"Hérnia hiatal paraesofágica."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-274351","number":"274351","sourceNumber":"274351","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Sobre a hemorragia digestiva alta causada por úlcera péptica, suas características e\nabordagem, assinale a alternativa correta.","options":{"A":"A úlcera péptica representa a 4a maior causa de hemorragia digestiva alta.","B":"Deve-se aguardar 72h após o quadro inicial da hemorragia para ser realizada endoscopia\ndigestiva alta.","C":"A maioria dos casos de hemorragia por úlcera necessita de abordagem cirúrgica.","D":"Hemorragia mais intensa geralmente ocorre quando a úlcera duodenal penetra ramos da artéria\ngastroepiploica esquerda.","E":"Na suspeita ou diagnóstico de úlcera péptica, deve ser iniciada terapia com inibidor de bomba de\nprótons."},"answer":"E","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-262216","number":"262216","sourceNumber":"262216","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Com relação à esofagite eosinofílica, julgue o item a seguir. Um dos sintomas dessa\ndoença é a disfagia de transmissão.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-262217","number":"262217","sourceNumber":"262217","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Com relação à esofagite eosinofílica, julgue o item a seguir. É uma doença de maior\nprevalência em homens e não há evidências que a caracterizem como uma condição pré-maligna.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-262219","number":"262219","sourceNumber":"262219","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Com relação à esofagite eosinofílica, julgue o item a seguir. Corticoides sistêmicos em\nbaixas doses são o tratamento de escolha para essa condição.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-262221","number":"262221","sourceNumber":"262221","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Certo paciente de 18 anos de idade procura gastroenterologista após a realização de\nendoscopia digestiva alta, sem pedido médico, em razão de queixas de queimação retroesternal e\nregurgitação, que se iniciaram há cerca de dois meses. As queixas são geralmente pós-prandiais,\nprincipalmente após ingesta de alimentos gordurosos e de bebidas alcoólicas. Nega náuseas,\nvômitos, disfagia, perda ponderal ou quaisquer outros sintomas. O laudo do exame descreve\npresença de erosões em esôfago distal, algumas maiores que 5 mm, confluentes, acometendo\ncerca de 65% da circunferência do órgão. Acerca desse caso clínico e tendo em vista os\nconhecimentos médicos correlatos, julgue o item a seguir. O diagnóstico presuntivo de doença do\nrefluxo gastroesofágico (DRGE) pode ser feito na presença dos sintomas típicos de pirose e\nregurgitação ácida, sendo recomendada a endoscopia digestiva alta nos casos em que há sinais de\nalarme ou risco de complicações.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-262223","number":"262223","sourceNumber":"262223","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Certo paciente de 18 anos de idade procura gastroenterologista após a realização de\nendoscopia digestiva alta, sem pedido médico, em razão de queixas de queimação retroesternal e\nregurgitação, que se iniciaram há cerca de dois meses. As queixas são geralmente pós-prandiais,\nprincipalmente após ingesta de alimentos gordurosos e de bebidas alcoólicas. Nega náuseas,\nvômitos, disfagia, perda ponderal ou quaisquer outros sintomas. O laudo do exame descreve\npresença de erosões em esôfago distal, algumas maiores que 5 mm, confluentes, acometendo\ncerca de 65% da circunferência do órgão. Acerca desse caso clínico e tendo em vista os\nconhecimentos médicos correlatos, julgue o item a seguir. A pesquisa e o tratamento da bactéria H.\npylori não fazem parte da rotina propedêutica e terapêutica da DRGE.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-262225","number":"262225","sourceNumber":"262225","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Certo paciente de 18 anos de idade procura gastroenterologista após a realização de\nendoscopia digestiva alta, sem pedido médico, em razão de queixas de queimação retroesternal e\nregurgitação, que se iniciaram há cerca de dois meses. As queixas são geralmente pós-prandiais,\nprincipalmente após ingesta de alimentos gordurosos e de bebidas alcoólicas. Nega náuseas,\nvômitos, disfagia, perda ponderal ou quaisquer outros sintomas. O laudo do exame descreve\npresença de erosões em esôfago distal, algumas maiores que 5 mm, confluentes, acometendo\ncerca de 65% da circunferência do órgão. Acerca desse caso clínico e tendo em vista os\nconhecimentos médicos correlatos, julgue o item a seguir. O exame de manometria esofágica\nsempre deve ser realizado antes do tratamento cirúrgico da DRGE.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-262227","number":"262227","sourceNumber":"262227","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Certo paciente de 18 anos de idade procura gastroenterologista após a realização de\nendoscopia digestiva alta, sem pedido médico, em razão de queixas de queimação retroesternal e\nregurgitação, que se iniciaram há cerca de dois meses. As queixas são geralmente pós-prandiais,\nprincipalmente após ingesta de alimentos gordurosos e de bebidas alcoólicas. Nega náuseas,\nvômitos, disfagia, perda ponderal ou quaisquer outros sintomas. O laudo do exame descreve\npresença de erosões em esôfago distal, algumas maiores que 5 mm, confluentes, acometendo\ncerca de 65% da circunferência do órgão. Acerca desse caso clínico e tendo em vista os\nconhecimentos médicos correlatos, julgue o item a seguir. Pela classificação de Los Angeles, o\npaciente apresenta uma esofagite erosiva grau C.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-262228","number":"262228","sourceNumber":"262228","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Quanto ao esôfago de Barrett, uma das possíveis complicações da doença do refluxo\ngastroesofágico (DRGE), julgue o item a seguir. Acomete principalmente o esôfago proximal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-262229","number":"262229","sourceNumber":"262229","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Quanto ao esôfago de Barrett, uma das possíveis complicações da doença do refluxo\ngastroesofágico (DRGE), julgue o item a seguir. Definido histologicamente como metaplasia\nintestinal, o esôfago de Barrett apresenta-se macroscopicamente como uma área de mucosa\nespessada e esbranquiçada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-262230","number":"262230","sourceNumber":"262230","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Quanto ao esôfago de Barrett, uma das possíveis complicações da doença do refluxo\ngastroesofágico (DRGE), julgue o item a seguir. Pacientes com esôfago de Barrett devem fazer\nendoscopia a cada seis meses para rastreio de câncer de esôfago.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-262237","number":"262237","sourceNumber":"262237","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A Rome Foundation trouxe uma grande contribuição à gastroenterologia ao padronizar\na definição de um grupo de doenças cujo\ndiagnóstico é muito comum à especialidade, que é o das\ndoenças funcionais. Acerca das doenças funcionais do trato digestivo, julgue o item a seguir. A\ndispepsia funcional pode ser apresentada como plenitude pós-prandial, ou saciedade precoce, ou\ndor epigástrica, ou queimação epigástrica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-262238","number":"262238","sourceNumber":"262238","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A Rome Foundation trouxe uma grande contribuição à gastroenterologia ao padronizar\na definição de um grupo de doenças cujo\ndiagnóstico é muito comum à especialidade, que é o das\ndoenças funcionais. Acerca das doenças funcionais do trato digestivo, julgue o item a seguir. Pirose\ntambém é interpretado como um dos sintomas definidores de dispepsia funcional.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-262239","number":"262239","sourceNumber":"262239","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A Rome Foundation trouxe uma grande contribuição à gastroenterologia ao padronizar\na definição de um grupo de doenças cujo\ndiagnóstico é muito comum à especialidade, que é o das\ndoenças funcionais. Acerca das doenças funcionais do trato digestivo, julgue o item a seguir.\n\nSintomas que se aliviam com evacuação ou flatulência não se enquadram como dispepsia\nfuncional.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-262241","number":"262241","sourceNumber":"262241","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A Rome Foundation trouxe uma grande contribuição à gastroenterologia ao padronizar\na definição de um grupo de doenças cujo\ndiagnóstico é muito comum à especialidade, que é o das\ndoenças funcionais. Acerca das doenças funcionais do trato digestivo, julgue o item a seguir.\n\nAntieméticos e antidepressivos fazem parte do arsenal terapêutico da dispepsia funcional.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-239276","number":"239276","sourceNumber":"239276","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Um paciente de 75 anos de idade procurou atendimento por diminuição do volume\nurinário e intolerância aos esforços,\nassociada a dor torácica ventilatório-dependente e a dor lombar\nde forte intensidade. Realizou exames de laboratório, que evidenciaram: hemoglobina = 8,6 g/dl,\nhematócrito = 25%, leucócitos = 6.600/mm3, sem particularidades no diferencial, plaquetas = 190\nmil/mm3, creatinina = 4,51 mg/dl, potássio = 6,3 mEq/L, cálcio sérico corrigido = 13 mg/dl, ureia =\n109 mg/dl, reserva alcalina = 12 U/L. Ao exame físico, o paciente encontrava-se em regular estado\ngeral, hipocorado, com presença de sopro sistodiastólico 2+/4+, murmúrio vesicular reduzido em\n1/3 inferior direito, edema em membros inferiores 3+/4+, abdome sem particularidades e\n\npercussão-punho-lombar (PPL) negativo, PA = 180 mmHg X 90 mmHg, FC = 97 bpm, SatO2 = 92%\nem ar ambiente. Considerando esse caso\nclínico e os conhecimentos médicos correlatos, julgue o\nitem a seguir. Pacientes com dor crônica fazem uso frequente de anti-inflamatórios não esteroidais\n(AINES), que são associados a úlceras pépticas, de localização gástrica, mais frequentes que no\nduodeno.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-239277","number":"239277","sourceNumber":"239277","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Um paciente de 75 anos de idade procurou atendimento por diminuição do volume\nurinário e intolerância aos esforços,\nassociada a dor torácica ventilatório-dependente e a dor lombar\nde forte intensidade. Realizou exames de laboratório, que evidenciaram: hemoglobina = 8,6 g/dl,\nhematócrito = 25%, leucócitos = 6.600/mm3, sem particularidades no diferencial, plaquetas = 190\nmil/mm3, creatinina = 4,51 mg/dl, potássio = 6,3 mEq/L, cálcio sérico corrigido = 13 mg/dl, ureia =\n109 mg/dl, reserva alcalina = 12 U/L. Ao exame físico, o paciente encontrava-se em regular estado\ngeral, hipocorado, com presença de sopro sistodiastólico 2+/4+, murmúrio vesicular reduzido em\n1/3 inferior direito, edema em membros inferiores 3+/4+, abdome sem particularidades e\n\npercussão-punho-lombar (PPL) negativo, PA = 180 mmHg X 90 mmHg, FC = 97 bpm, SatO2 = 92%\nem ar ambiente. Considerando esse caso\nclínico e os conhecimentos médicos correlatos, julgue o\nitem a seguir. Úlceras pépticas do tipo Forrest IIC evidenciadas na endoscopia são aquelas com\nfundo hemático.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-179186","number":"179186","sourceNumber":"179186","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Um paciente de 42 anos de idade, foi admitido no serviço de emergência com queixa\nde dor epigástrica, fezes escurecidas e\nfraqueza. Relata que os sintomas tiveram início nas últimas\n24 horas. Nega comorbidades prévias, mas informa uso frequente de ibuprofeno, nas últimas\nsemanas, devido a dores musculares relacionadas ao trabalho. Nega tabagismo, etilismo e uso de\ndrogas ilícitas. Ao exame, apresenta temperatura axilar de 37ºC, PA de 80 x 55 mmHg, FC de 119\nbpm, FR de 22 irpm e SpO? de 94% e está hipocorado, com abdome levemente distendido e\nsensível na região epigástrica. O exame da região retal evidencia fezes com melena. Com base\nnesse caso hipotético, assinale a alternativa que apresenta a abordagem inicial mais adequada\npara o paciente.","options":{"A":"endoscopia digestiva alta","B":"reanimação com líquidos intravenosos","C":"inibidores de bomba de prótons","D":"escleroterapia","E":"ligadura elástica"},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-179192","number":"179192","sourceNumber":"179192","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Um paciente de 42 anos de idade, foi admitido no serviço de emergência com queixa\nde dor epigástrica, fezes escurecidas e\nfraqueza. Relata que os sintomas tiveram início nas últimas\n24 horas. Nega comorbidades prévias, mas informa uso frequente de ibuprofeno, nas últimas\nsemanas, devido a dores musculares relacionadas ao trabalho. Nega tabagismo, etilismo e uso de\ndrogas ilícitas. Ao exame, apresenta temperatura axilar de 37ºC, PA de 80 x 55 mmHg, FC de 119\nbpm, FR de 22 irpm e SpO? de 94% e está hipocorado, com abdome levemente distendido e\nsensível na região epigástrica. O exame da região retal evidencia fezes com melena. Considere-se\nainda que, à endoscopia digestiva alta, tenha sido evidenciada, nessa situação hipotética, uma\núlcera gástrica com vaso visível não sangrante. Sendo assim, assinale a alternativa que apresenta,\ncorreta e respectivamente, a classificação de Forrest para a úlcera e seu risco de ressangramento.","options":{"A":"Forrest llc e baixo risco","B":"Forrest Ib e risco intermedário","C":"Forrest Ia e alto risco","D":"Forrest lla e alto risco","E":"Forrest lll e alto risco"},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-152130","number":"152130","sourceNumber":"152130","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Considere hipoteticamente que o paciente R. A. S., de 60 anos de idade, agenda\nconsulta ambulatorial de retorno para entregar\nresultados de uma endoscopia digestiva alta e de\numa ultrassonografia de rins e vias urinárias. O paciente trouxe receita do vizinho que teve o\nmesmo problema de saúde, porém melhorou após o uso de determinados medicamentos\nprescritos. R. A. S. apresenta antecedente pessoal de fratura exposta da tíbia com dano extenso às\npartes moles e antecedente familiar de acalasia no pai. Estava ansioso porque, após pesquisa na\ninternet, assemelhou os respectivos sintomas aos de alguns tipos de câncer. Com base nesse caso\nclínico, e considerando os conhecimentos médicos a ele relacionados, julgue o item a seguir. Uma\ndas grandes complicações referentes à doença do refluxo gastroesofágico é o esôfago de Barrett,\nem que se infere uma substituição do epitélio pavimentoso estratificado por metaplasia, e não por\ndisplasia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-152078","number":"152078","sourceNumber":"152078","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Considere hipoteticamente que o paciente R. A. S., de 60 anos de idade, agenda\nconsulta ambulatorial de retorno para entregar\nresultados de uma endoscopia digestiva alta e de\numa ultrassonografia de rins e vias urinárias. O paciente trouxe receita do vizinho que teve o\nmesmo problema de saúde, porém melhorou após o uso de determinados medicamentos\nprescritos. R. A. S. apresenta antecedente pessoal de fratura exposta da tíbia com dano extenso às\npartes moles e antecedente familiar de acalasia no pai. Estava ansioso porque, após pesquisa na\ninternet, assemelhou os respectivos sintomas aos de alguns tipos de câncer. Com base nesse caso\nclínico, e considerando os conhecimentos médicos a ele relacionados, julgue o item a seguir. Os\nresultados dos procedimentos clínicos, interverncionistas e cirúrgicos indicam o tratamento não\ncirúrgico (incluindo medicamentos e intervenções endoscópicas) como o mais seguro e mais efetivo\nda acalasia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-152092","number":"152092","sourceNumber":"152092","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Considere hipoteticamente que o paciente R. A. S., de 60 anos de idade, agenda\nconsulta ambulatorial de retorno para entregar\nresultados de uma endoscopia digestiva alta e de\numa ultrassonografia de rins e vias urinárias. O paciente trouxe receita do vizinho que teve o\nmesmo problema de saúde, porém melhorou após o uso de determinados medicamentos\nprescritos. R. A. S. apresenta antecedente pessoal de fratura exposta da tíbia com dano extenso às\npartes moles e antecedente familiar de acalasia no pai. Estava ansioso porque, após pesquisa na\ninternet, assemelhou os respectivos sintomas aos de alguns tipos de câncer. Com base nesse caso\nclínico, e considerando os conhecimentos médicos a ele relacionados, julgue o item a seguir.\n\nQualquer plano terapêutico para a doença ulcerosa péptica, tanto clínico quanto cirúrgico, deve\nlevar em conta o H. pylori.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-152085","number":"152085","sourceNumber":"152085","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente, 60 anos de idade, com disfagia progressiva há seis meses, com perda de\npeso acentuada, dor torácica atípica, relata que,\nnos últimos meses, vem apresentando disfagia\npara sólidos e agora só consegue engolir alimentos liquidificados. Perdeu 30 kg em um mês.\n\nPaciente é tabagista desde os 15 anos de idade, fumando oito palheiros por dia. Com base nesse\ncaso clínico, julgue o item a seguir. Esôfago\nde Barret tem relação com carcinoma escamoso.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-134981","number":"134981","sourceNumber":"134981","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"No que se refere a câncer de esôfago, cirrose e doença de Crohn, hulque o item\nsubsecutivo. O tipo mais frequente de\ncâncer de esôfago em paciente com acalasia é o carcinoma\nepidermoide de esôfago, sendo seu desenvolvimento relacionado com esofagite de estase e\nfermentação dos alimentos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-131805","number":"131805","sourceNumber":"131805","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Em relação às moléstias do esôfago, no que se refere à acalásia, assinale a alternativa\nCORRETA:","options":{"A":"A acalásia é definida como uma hipocontratilidade do Esfíncter Esofágico Superior (EES), com\nondas primárias exacerbadas.","B":"O esfíncter esofágico inferior se apresenta hipertensivo em 50% dos casos.","C":"Essa moléstia é o distúrbio motor esofagiano mais raro.","D":"A causa principal é hipertensão arterial sistêmica.","E":"No esofagograma, observa-se a clássica imagem do bico de garrafa."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-135009","number":"135009","sourceNumber":"135009","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Um paciente com quarenta anos de idade, natural e procedente de Barreiras (BA),\nprocurou o ambulatório de clínica médica e\ninformou que apresentava quadro de constipação\nintestinal havia seis meses, situação que o obriga a usar laxantes seguidamente. O paciente não\napresenta disfagia e não mostrou alterações dignas de nota no exame físico. Com relação a esse\ncaso clínico, julgue o item seguinte. Em caso de doença de Chagas, a realização do exame\nradiológico contrastado é a melhor forma de diagnosticar o comprometimento intestinal do paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-135015","number":"135015","sourceNumber":"135015","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Um paciente com quarenta anos de idade, natural e procedente de Barreiras (BA),\nprocurou o ambulatório de clínica médica e\ninformou que apresentava quadro de constipação\nintestinal havia seis meses, situação que o obriga a usar laxantes seguidamente. O paciente não\napresenta disfagia e não mostrou alterações dignas de nota no exame físico. Com relação a esse\ncaso clínico, julgue o item seguinte. O procedimento de averiguação mais indicado para se\ninvestigar se o referido paciente está acometido por doença de Chagas é pesquisar a presença do\nparasita em sangue periférico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-108156","number":"108156","sourceNumber":"108156","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Com relação ao tubo digestivo, às suas glândulas anexas e às patologias que\nacometem esses sistemas, julgue o item\nsubsequente. O divertículo de Meckel pode ser acometido\npor uma úlcera péptica.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-88675","number":"88675","sourceNumber":"88675","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Julgue o item a seguir, relativo à úlcera péptica. A infecção gástrica pelo Helicobacter\npylori é responsável pela maioria dos casos de\núlcera duodenal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-88670","number":"88670","sourceNumber":"88670","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Julgue o item a seguir, relativo à úlcera péptica. Uma opção apropriada para a\nerradicação do H. pylori e o controle dos sintomas é a associação de um inibidor de bomba\nprotônica com claritromicina e amoxicilina.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-64276","number":"64276","sourceNumber":"64276","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Julgue o item seguinte relativo às neoplasias gástricas: A gastropatia hipertrófica\nhipoproteinêmica, também conhecida como doença\nde Ménétrier, é uma afecção rara, adquirida e\npré-maligna para o câncer gástrico.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-49135","number":"49135","sourceNumber":"49135","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Tendo em vista que o conhecimento da anatomia e fisiologia gástricas é de\nfundamental importância para o entendimento das\ndiversas afecções que acometem o estômago,\njulgue o item a seguir. A gastrina é produzida pelas células G localizadas no antro gástrico.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-32191","number":"32191","sourceNumber":"32191","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A respeito da doença do refluxo gastroesofágico (DRGE), assinale a alternativa correta.","options":{"A":"O exame padrão ouro para o diagnóstico dessa doença é a endoscopia digestiva alta.","B":"A DRGE raramente está associada ao gastrinoma.","C":"A DRGE pode causar tosse crônica por reflexo vagal esôfago-pulmonar.","D":"A principal indicação da cirurgia é a constatação de falha do controle da pirose ou dos sinais e\nsintomas extraesofágicos com a medicação.","E":"A estenose péptica é uma complicação da DRGE que ocorre no esôfago proximal."},"answer":"E","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-32182","number":"32182","sourceNumber":"32182","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"O exame padrão-ouro para o diagnóstico de câncer gástrico é a:","options":{"A":"Endoscopia com biópsia.","B":"Radiografia gastrointestinal com duplo contraste.","C":"Ultrassonografia endoscópica.","D":"Tomografia computadorizada com contraste.","E":"Ressonância nuclear magnética."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-32170","number":"32170","sourceNumber":"32170","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Com relação às diversas afecções benignas e malignas que acometem o estômago,\nassinale a alternativa correta.","options":{"A":"A maior parte dos pacientes com lacerações de Mallory-Weiss necessita de tratamento cirúrgico\nde urgência.","B":"Os sarcomas correspondem atualmente a cerca de 40% dos tumores gástricos malignos.","C":"Ao contrário de outras malignidades, os linfomas não têm nenhuma correlação com a infecção\npelo Helicobacter pylori.","D":"A síndrome de Zollinger-Ellison é caracterizada pela hipersecreção gástrica, tumor de células\nbeta do pâncreas e perfuração gástrica.","E":"A doença de Ménétrier, ou gastrite hipertrófica hipoproteinêmica, é uma doença adquirida e\npré-maligna."},"answer":"E","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-29709","number":"29709","sourceNumber":"29709","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Considerando que o conhecimento da fisiologia e anatomia do estômago é fundamental\npara o entendimento das doenças que o\nacometem, julgue o item que se segue. A fase cefálica da\nsecreção ácida é mediada primariamente pelo nervo vago e responde por 20% a 30% do volume\ntotal do ácido gástrico produzido em resposta a uma refeição.","options":{"A":"Certo","B":"Errado"},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-27529","number":"27529","sourceNumber":"27529","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Assinale a opção correta no que diz respeito aos hormônios gastrointestinais.","options":{"A":"O peptídeo YY aumenta a motilidade gastrointestinal e a secreção gástrica e pancreática.","B":"O principal estímulo à liberação de secretina é o ácido no duodeno, quando o pH luminal diminui\npara 4 ou menos.","C":"A neurotensina aumenta a secreção gástrica e inibe a motilidade intestinal.","D":"O enteroglucagon é produzido predominantemente no intestino delgado, proximal e funciona\nestimulando a motilidade do intestino delgado.","E":"A principal função fisiológica do polipeptídeo inibitório gástrico (PIG) é a regulação da\nliberação\nde colecistoquinina."},"answer":"E","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-27547","number":"27547","sourceNumber":"27547","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Assinale o exame, dentre os abaixo relacionados, que deve ser realizado em um\npaciente com suspeita clínica da síndrome de Zollinger-Ellison","options":{"A":"PHmetria.","B":"Dosagem de ácido vanil-mandélico.","C":"Colonoscopia.","D":"Dosagem de gastrina sérica.","E":"Dosagem de ácido 5-hidróxi-indol-acético."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-352365","number":"352365","sourceNumber":"352365","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Considerando as imagens apresentadas e os temas que ela suscita bem como seus\nconhecimentos prévios, julgue os itens de 15 a 17. A partir da figura I, é possível observar a\nlocalização anatômica do triângulo de Killian, situado entre as fibras oblíquas do músculo\ntireofaríngeo e as fibras horizontais do músculo cricofaríngeo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-352364","number":"352364","sourceNumber":"352364","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Considerando as imagens apresentadas e os temas que ela suscita bem como seus\nconhecimentos prévios, julgue os itens de 15 a 17. A hipótese diagnóstica indicada na figura II é\nconhecida como acalásia cricofaríngea, e geralmente se manifesta em pacientes na sétima década\nde vida. Essa condição é postulada devido a um aumento da elasticidade da mucosa e do tônus\nmuscular associado ao envelhecimento.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-352363","number":"352363","sourceNumber":"352363","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Considerando as imagens apresentadas e os temas que ela suscita bem como seus\nconhecimentos prévios, julgue os itens de 15 a 17. Os divertículos podem ser considerados de\npulsão como o de Zenker e o epifrênico, sendo este último considerado um divertículo verdadeiro.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-334872","number":"334872","sourceNumber":"334872","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"No tratamento da doença representada nesse exame radiológico contrastado, podem\nser usadas determinadas técnicas cirúrgicas.\nAssinale a alternativa que indica essas técnicas.","options":{"A":"Cardioplastia à Thal-Hatafuku e operação de Duhamel","B":"Operação de Duhamel e esofagectomia","C":"Cardiomiotomia à Heller e operação de Frey","D":"Cardioplastia à Thal-Hatafuku e esofagectomia","E":"Cardiomiotomia à Heller e operação de Whipple"},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-334874","number":"334874","sourceNumber":"334874","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Uma paciente de 40 anos de idade procura serviço de emergência queixando-se de dor\nem queimação localizada na região anterior do tórax, que se irradia para o pescoço e tem a\nalimentação e a posição supina como fatores de precipitação. A paciente negou que o esforço\ndesencadeie o sintoma. O eletrocardiograma (ECG) seriado e os biomarcadores cardíacos se\nmostraram sem alterações. Com base no exposto, assinale a alternativa que indica o próximo\npasso a ser seguido nesse caso.","options":{"A":"Solicitar teste ergométrico.","B":"Solicitar parecer da psiquiatria.","C":"Prescrever inibidor de bomba de próton.","D":"Solicitar tomografia de tórax.","E":"Prescrever ácido acetilsalicílico."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-307096","number":"307096","sourceNumber":"307096","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Em relação à doença do refluxo gastroesofágico (DRGE), assinale a alternativa correta.","options":{"A":"O esôfago de Barrett é fator de risco para adenocarcinoma esofágico.","B":"É mais comum em jovens do sexo feminino.","C":"Esofagectomia é o tratamento padrão-ouro para esôfago de Barrett.","D":"A sintomatologia mais comum da DRGE é dor torácica, seguida de lesões orais.","E":"Tem forte associação com carcinoma epidermoide de esôfago."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-307106","number":"307106","sourceNumber":"307106","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Um paciente foi atendido em pronto atendimento com queixa de pirose e regurgitação,\nrelatando que, nas últimas semanas, está com\ntosse, odinofagia e eructações. Diante disso, ele foi\ndiagnosticado como doença do refluxo gastroesofágico (DRG). Tendo em vista esse caso clínico,\nassinale a alternativa correta. Alternativas:","options":{"A":"A elevação da cabeceira e a diminuição da ingesta de álcool e gorduras não têm impacto na\nDRG.","B":"O controle do peso não muda o prognóstico dessa doença e seu tratamento.","C":"A correção cirúrgica pode ser indicada quando o paciente, a despeito da aderência adequada ao\ntratamento, segue com esofagite redicivante.","D":"O prognóstico dos pacientes com DRG não tratados é sem complicações e com alto índice de\nresolução.","E":"Na presença de esôfago de Barrett, não há necessidade de exames para controle."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-266428","number":"266428","sourceNumber":"266428","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Um paciente do sexo masculino, de 35 anos de idade, procurou atendimento médico\npor apresentar epigastralgia, tipo queimação,\nassociada a pirose havia três meses, principalmente\napós refeições e durante o sono. Foi realizado exame de endoscopia digestiva alta, que sugeriu o\ndiagnóstico de doença do refluxo gastroesofágico (DRGE). Com relação ao caso clínico hipotético\nprecedente e a aspectos relacionados à DRGE, julgue o item a seguir. Obesidade e ingesta de\nalimentos gordurosos são fatores de risco para DRGE.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-266429","number":"266429","sourceNumber":"266429","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Um paciente do sexo masculino, de 35 anos de idade, procurou atendimento médico\npor apresentar epigastralgia, tipo queimação,\nassociada a pirose havia três meses, principalmente\napós refeições e durante o sono. Foi realizado exame de endoscopia digestiva alta, que sugeriu o\ndiagnóstico de doença do refluxo gastroesofágico (DRGE). Com relação ao caso clínico hipotético\nprecedente e a aspectos relacionados à DRGE, julgue o item a seguir. Os sintomas de pirose e\nepigastralgia apresentados pelo paciente são manifestações atípicas da DRGE.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-266430","number":"266430","sourceNumber":"266430","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Um paciente do sexo masculino, de 35 anos de idade, procurou atendimento médico\npor apresentar epigastralgia, tipo queimação,\nassociada a pirose havia três meses, principalmente\napós refeições e durante o sono. Foi realizado exame de endoscopia digestiva alta, que sugeriu o\ndiagnóstico de doença do refluxo gastroesofágico (DRGE). Com relação ao caso clínico hipotético\nprecedente e a aspectos relacionados à DRGE, julgue o item a seguir. Mudanças comportamentais,\ncomo dieta fracionada e elevação da cabeceira da cama, são essenciais para a melhora clínica do\npaciente em tela.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-266431","number":"266431","sourceNumber":"266431","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Um paciente do sexo masculino, de 35 anos de idade, procurou atendimento médico\npor apresentar epigastralgia, tipo queimação,\nassociada a pirose havia três meses, principalmente\napós refeições e durante o sono. Foi realizado exame de endoscopia digestiva alta, que sugeriu o\ndiagnóstico de doença do refluxo gastroesofágico (DRGE). Com relação ao caso clínico hipotético\nprecedente e a aspectos relacionados à DRGE, julgue o item a seguir. No caso em apreço, a\nrealização do teste terapêutico com inibidor de bomba de prótons (IBP) com resposta clínica\nnegativa excluiria o diagnóstico de DRGE.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-263421","number":"263421","sourceNumber":"263421","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Um paciente com 32 anos de idade, tabagista, com histórico de epigastralgia,\napresentou, há cerca de 4 horas, quadro de\nhematêmese e melena. Ao chegar a um pronto-socorro\nhospitalar, encontrava-se com PA = 90 x 50 mmHg e FC = 112 bpm. No local, foram realizadas\nreposição volêmica com normalização dos parâmetros hemodinâmicos bem como endoscopia\ndigestiva alta, que evidenciou úlcera péptica localizada na incisura angularis do estômago, com\nvaso visível, porém sem sangramento ativo. Realizou-se, então, terapia combinada de hemostasia\nda úlcera. Nesse caso, a conduta imediata adequada para o paciente é indicar:","options":{"A":"Internação hospitalar e preparação para a cirurgia de emergência.","B":"Internação hospitalar, octreotide endovenoso e repetição da endoscopia em 48 horas.","C":"Internação hospitalar, inibidor de bomba de prótons endovenoso e monitorização hemodinâmica\nnão invasiva.","D":"Alta hospitalar, inibidor de bomba de prótons por via oral por 30 dias e repetição de endoscopia\ndigestiva alta em 3 meses."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-291552","number":"291552","sourceNumber":"291552","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Um homem, com 58 anos de idade, foi atendido em ambulatório de hospital secundário.\nRelatava dor e queimação epigástrica que aumentava após a ingestão de alimentos, acompanhada\nde plenitude pós-prandial. Realizou endoscopia digestiva alta que evidenciou úlcera com 5 mm de\ndiâmetro na parede anterior do antro gástrico, na região pré-pilórica. Com base nos dados\napresentados, assinale a alternativa que apresenta a conduta adequada a ser seguida.","options":{"A":"Solicitar endoscopia com biópsias seriadas para excluir neoplasia gástrica e pesquisar\nHelicobacter pylori.","B":"Indicar tratamento operatório pela localização da úlcera e risco de perfuração.","C":"Prescrever inibidor de secreção gástrica por 6 a 8 semanas e solicitar endoscopia com pesquisa\nde Helicobacter pylori, avaliando a cicatrização.","D":"Prescrever inibidor da secreção gástrica e tratar Helicobacter pylori empiricamente por sua\nprevalência em ulcerosos, evitando recidiva."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-227393","number":"227393","sourceNumber":"227393","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A respeito da Doença de Refluxo Gastroesofágico (DRGE) e da estenose péptica do\nesôfago distal, julgue o item seguinte. O esôfago de Barrett, condição clínica associada à\ncomplicação da DRGE, predispõe a pessoa a carcinoma epidermoide do esôfago distal.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-227394","number":"227394","sourceNumber":"227394","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A respeito da doença de refluxo gastroesofágico (DRGE) e da estenose péptica do\nesôfago distal, julgue o item seguinte. O exame radiológico contrastado do esôfago não evidencia\nestenose péptica do esôfago distal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-227395","number":"227395","sourceNumber":"227395","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A respeito da doença de refluxo gastroesofágico (DRGE) e da estenose péptica do\nesôfago distal, julgue o item seguinte. Para\npaciente com esofagite grave por DRGE, deve-se\nprescrever o uso de inibidor de bomba de prótons por duas vezes ao dia, sem tempo determinado\nde tratamento.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-227396","number":"227396","sourceNumber":"227396","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A respeito da doença de refluxo gastroesofágico (DRGE) e da estenose péptica do\nesôfago distal, julgue o item seguinte. A DRGE resulta de falha de uma das defesas do esôfago,\ncomo a resistência intrínseca do epitélio.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-206113","number":"206113","sourceNumber":"206113","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Sobre o esôfago de Barret, assinale a alternativa INCORRETA:","options":{"A":"40% dos pacientes com refluxo gastroesofágico desenvolvem o esôfago de Barret.","B":"A Metaplasia Intestinal incompleta que ocorre no esôfago de Barret inclui células gástricas\nsuperficiais, células caliciformes intestinais e células absortivas intestinais.","C":"A ressecção esofágica é recomendada para pacientes com displasia de alto grau. A\nesofagectomia subtotal transhiatal é recomendada para maioria dos pacientes.","D":"Pacientes com esôfago de Barret tem risco 40 vezes maior de desenvolver carcinoma esofágico."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-206136","number":"206136","sourceNumber":"206136","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A mortalidade da hemorragia digestiva alta diminuiu expressivamente após a evolução\nda terapêutica endoscópica, estando em torno de 5 a\n14%. Sobre isso, é INCORRETO afirmar:","options":{"A":"A hemorragia digestiva alta não varicosa é autolimitada em até 80% dos casos, sem\nnecessidade de intervenções.","B":"Não há indício que os hepatopatas tenham maior chance que a população geral de desenvolver\nlesão pulmonar aguda associado à transfusão.","C":"Infecções são comuns em doentes com hemorragia digestiva alta varicosa, chegando a 50%\ndurante o período de internação do doente.","D":"Segundo a Classificação de Forrest, a lesão ulcerosa com coágulo aderido corresponde ao tipo\nIIa."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-206152","number":"206152","sourceNumber":"206152","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Acalasia é a doença mais bem compreendida de todos os distúrbios da motilidade\nesofágica. É INCORRETO afirmar sobre as\ncaracterísticas manométricas esofágicas da Acalasia\ntípica:","options":{"A":"Amplitude pressórica < 40 mmHg.","B":"Ondas de contração simultâneas.","C":"Ausência de peristalse.","D":"Pressão do esfíncter esofágico inferior entre 15 e 25 mmHg."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-206160","number":"206160","sourceNumber":"206160","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Sobre a Vagotomia Troncular para o tratamento da Úlcera Gástrica, assinale a\nalternativa INCORRETA:","options":{"A":"É realizada pela secção do nervo vago esquerdo e direito acima dos ramos hepáticos e celíacos.","B":"É provavelmente a operação mais realizada para doença ulcerosa duodenal.","C":"Quando o bulbo duodenal está muito deformado e fibrosado uma piloplastia Finney pode ser\numa alternativa útil.","D":"Apresentam menores taxas de diarreia e dumping quando comparadas à vagotomia\nsuperseletiva."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-183876","number":"183876","sourceNumber":"183876","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"No que se refere às enfermidades gastrointestinais, julgue o item que se segue. Os\nsintomas clínicos de esofagopatia chagásica devem-se, principalmente, ao refluxo gastroesofágico\ncausado pela acalásia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-175142","number":"175142","sourceNumber":"175142","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A figura abaixo demonstra o esôfago, pela vista posterior e pelo lado direito. A\nalternativa que corresponde, respectivamente,\naos divertículos do esôfago representados por *, ** e\n\n*** são:","options":{"A":"Faringoesofágico, Tração e Justagástrico.","B":"Tração, Zenker e Epifrênico.","C":"Zenker, Tração e Epifrênico.","D":"Tração, Médio esofágico e Epifrênico."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-159561","number":"159561","sourceNumber":"159561","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente portadora de artrite reumatoide e que faz uso contínuo de inibidor de bomba\nde prótons compareceu ao ambulatório de\ncirurgia-geral, relatando desconforto retroesternal tipo\nqueimação, regurgitação e episódios de disfagia a sólidos. Após ser submetida a videoendoscopia\ndigestiva alta, constatou-se que a paciente apresentava esofagite erosiva por refluxo tipo C de Los\nAngeles. Em seguida, procedeu-se à avaliação funcional do esôfago por manometria esofágica e\npHmetria esofágica de dois canais, para se avaliar a possibilidade de tratamento cirúrgico. A partir\ndo caso clínico apresentado, julgue o próximo item. É bastante provável que a avaliação\nmanométrica do esôfago dessa paciente indique um esfincter inferior do esôfago hipotônico e\ndistúrbio hipocontrátil dos dois terços inferiores do esôfago distal.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-159541","number":"159541","sourceNumber":"159541","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"No que se refere ao megaesôfago e ao megacólon decorrentes da tripanossomíase\n\nsul-americana, julgue o item subsecutivo. Fecaloma, vólvulo, colite isquêmica e úlcera colônica são\ncomplicações associadas ao megacólon chagásico.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-159543","number":"159543","sourceNumber":"159543","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"No que se refere ao megaesôfago e ao megacólon decorrentes da tripanossomíase\nsul-americana, julgue o item subsecutivo. No\ncaso de paciente de trinta e dois anos de idade com\ndiagnóstico de dolicomegaesôfago, recomenda-se a realização de tratamento com benznidazol\ndurante sete dias.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-129021","number":"129021","sourceNumber":"129021","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Um paciente com quarenta anos de idade foi submetido à vagotomia troncular com\nantrectomia e reconstrução do trânsito intestinal por gastrojejunostomia do tipo Billroth II para\ntratamento de doença ulcerosa péptica. Por apresentar persistência dos sintomas pépticos no\n\npós-operatório, foi submetido à investigação laboratorial e, embora apresentasse valor de gastrina\nsérica normal no pré-operatório, ela agora estava elevada. Com base nesse caso hipotético,\nassinale a alternativa que apresenta a causa mais provável de hipergastrinemia nesse paciente:","options":{"A":"Hiperplasia de células G.","B":"Síndrome de Zollinger-Ellison.","C":"Síndrome de intestino curto.","D":"Anemia perniciosa.","E":"Antro excluído retido."},"answer":"E","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-133990","number":"133990","sourceNumber":"133990","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Assinale a alternativa que não indica complicação clássica pós-gastrectomia.","options":{"A":"Síndrome de Dumping precoce.","B":"Síndrome de Dumping tardia.","C":"Síndrome da alça aferente.","D":"Síndrome da alça eferente.","E":"Fecaloma."},"answer":"E","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-133932","number":"133932","sourceNumber":"133932","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Quanto ao esôfago em quebra-nozes, é CORRETO afirmar que:","options":{"A":"Esse é o distúrbio motor mais comum do esôfago.","B":"O esôfago, na manometria, apresenta alta pressão (> 180 mmHg).","C":"Dor torácica e tosse são sintomas raros.","D":"As contrações peristálticas podem ser normais, mas o EEI não relaxa.","E":"O tratamento cirúrgico é a primeira escolha, sendo preconizada a miotomia ampla via torácica."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-111267","number":"111267","sourceNumber":"111267","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"O pediatra é chamado para atender um recém-nascido com 27 dias com queixas de\nvômitos, não biliosos, desde os 17 dias de vida. Evacuação 1 vez ao dia. Nasceu com 38 semanas,\npeso de 3 300 g. Aleitamento materno exclusivo. Peso atual 3 500 g. Ao exame físico, observa-se\ndistensão epigástrica, com ondas peristálticas visíveis e palpa-se tumoração cilíndrica, 3 x 2 cm,\nduro, elástica, no hipocôndrio direito, junto à borda do músculo reto abdominal. Qual é a doença\ncompatível com essa descrição e em qual sexo ela é mais prevalente?","options":{"A":"Atresia duodenal, masculino.","B":"Atresia duodenal, feminino.","C":"Estenose hipertrófica de piloro, masculino.","D":"Estenose hipertrófica de piloro, feminino.","E":"Hematoma duodenal, sem prevalência de sexo."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-80688","number":"80688","sourceNumber":"80688","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"As manifestações extraesofágicas da doença do refluxo podem incluir:","options":{"A":"Febre alta.","B":"Diarreia.","C":"Vômitos em jato.","D":"Sangramento gengival.","E":"Laringite."},"answer":"E","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-75482","number":"75482","sourceNumber":"75482","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Homem com 35 anos de idade, obeso, com hérnia de hiato, é acompanhado\nclinicamente há cerca de dez anos. Sua última\nendoscopia de controle mostrou esofagite com\nesôfago de Barrett em uma extensão de cerca de 5 cm. Foram colhidas biópsias cujo resultado foi\nmetaplasia de Barrett. A conduta inicial para o seguimento deste paciente é:","options":{"A":"indicação imediata de cirurgia antirrefluxo.","B":"indicação imediata de esofagectomia parcial.","C":"orientações higienodietéticas e o uso de antiácidos orais.","D":"uso de inibidores de bomba de prótons - 60 a 80 mg/dia - por três meses.","E":"erradicação de H. pylori com amoxicilina - 2,0 g/dia e claritromicina - 1,0 g/dia."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-64441","number":"64441","sourceNumber":"64441","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Indique a droga que auxilia na cicatrização da úlcera gástrica independente de sua\ncausa:","options":{"A":"Hidróxido de alumínio","B":"Omeprazol","C":"Doxiciclina","D":"Metronidazol","E":"Amoxicilina"},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-75505","number":"75505","sourceNumber":"75505","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Homem com 50 anos de idade foi atendido no ambulatório de Clínica Médica por\napresentar dor epigástrica em queimação pós-prandial, de moderada intensidade. Informa que,\nocasionalmente, acorda durante a noite por causa da dor. O exame físico é sem alterações. O\npaciente foi submetido à endoscopia digestiva alta que revelou pequena ulceração em bulbo\nduodenal, de aspecto endoscópico benigno e teste da urease positivo. A conduta terapêutica\nindicada para o paciente é prescrever:","options":{"A":"pantoprazol, tetraciclina e metronidazol por 14 dias.","B":"lansoprazol, metronidazol e amoxicilina por 21 dias.","C":"rabeprazol por 21 dias, tetraciclina e levofloxacina por 15 dias.","D":"omeprazol por 28 dias e claritromicina e amoxicilina por 14 dias.","E":"esomeprazol, levofloxacina e claritromicina por 14 dias."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-137568","number":"137568","sourceNumber":"137568","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Um paciente de 51 anos de idade, do sexo masculino, procura ambulatório de atenção\nsecundária com queixa de pirose intermitente, frequentemente deflagrada por ingestão de\nalimentos gordurosos e álcool, por prática de exercícios físicos e por deitar-se após\nalimentação. Relata ainda eventuais episódios de regurgitação. Nega vômitos, náuseas, disfagia\nou odinofagia. Não faz uso de medicamentos em sua rotina diária. Além de sobrepeso, nada foi\nencontrado de anormal no exame físico. A abordagem mais custo-efetiva e benéfica para esse\npaciente é","options":{"A":"proceder estudo manométrico de esôfago.","B":"solicitar endoscopia digestiva alta com biópsia.","C":"prescrever inibidores de bomba de prótons por via oral.","D":"administrar antiácidos por via oral nos intervalos das refeições.","E":"realizar teste não invasivo para detecção de Helicobacter\nPylori."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-137609","number":"137609","sourceNumber":"137609","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Um homem de 39 anos de idade vem, há três anos, em tratamento ambulatorial\npara doença do refluxo gastroesofágico (DRGE),\nem uso contínuo de inibidores de bomba de\nprótons (IBP). Sempre que tenta fazer desmame dos\n\nIBP, volta a apresentar graves sintomas da DRGE. Esofagogastroduodenoscopia com biópsia\nrealizada há dois anos evidenciou\nesofagite, pequena hérnia de hiato (< 3 cm) e estômago\nnormal. O paciente interrompeu o uso de IBP há quatro meses e, devido ao quadro de\npirose e dor retroesternal, foi submetido a nova endoscopia digestiva, que revelou processo\ninflamatório grave e úlceras no terço distal do esôfago. O estômago apresenta-se normal e\no teste da urease é positivo. Não foi visualizada hérnia hiatal. Devido ao intenso processo\ninflamatório, não foi realizada biópsia. O paciente, que não apresenta outras queixas ou\n\nco-morbidades, é etilista social, tabagista (média de 1,5 maços/dia há 22 anos) e apresenta\nobesidade leve. Não há outras alterações ao exame físico. O que deve ser feito para\nencaminhar corretamente o caso acima descrito?","options":{"A":"Reiniciar o tratamento com IBP, utilizando o dobro da dose. Após seis semanas de\ntratamento, repetir endoscopia com biópsia.","B":"Manter o tratamento com IBP na dose habitual e encaminhar, de imediato, o paciente\npara ambulatório especializado de Cirurgia\nLaparoscópica.","C":"Solicitar imediatamente nova endoscopia, já que a biópsia é indispensável, e encaminhar o\npaciente para ambulatório especializado de Cirurgia Laparoscópica.","D":"Reiniciar o tratamento com IBP, utilizando o dobro da dose, associado ao tratamento do\nH.Pylori. Em seguida, tratamento de manutenção com IBP por tempo indefinido.","E":"Reiniciar tratamento com IBP , utilizando o dobro da dose por seis semanas. Após esse\nperíodo, tratamento de manutenção com IBP por tempo indefinido."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-138379","number":"138379","sourceNumber":"138379","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Um homem de 40 anos de idade apresentou úlcera duodenal com biópsia positiva para\nHelicobacter Pylori. Fez tratamento durante 7 dias com omeprazol, amoxicilina e claritromicina, em\ndoses padrão. Endoscopia de controle repetida após oito semanas de tratamento revela\npersistência de H. Pylori na biópsia. Qual a conduta mais adequada para o tratamento desse\npaciente?","options":{"A":"Omeprazol, amoxicilina e furazolidona por 10 dias.","B":"Omeprazol, levofloxacina e amoxicilina por 10 dias.","C":"Pantoprazol, amoxicilina e claritromicina por 14 dias.","D":"Pantoprazol, sais de bismuto, furazolidona e claritromicina por 10 dias.","E":"Pantoprazol, sais de bismuto, levofloxacina e claritromicina por 10 dias."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-138607","number":"138607","sourceNumber":"138607","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente do sexo feminino, com 34 anos de idade, sem antecedentes patológicos\npregressos significativos, procurou a Unidade Básica\nde Saúde com história de pirose e\nregurgitação há mais ou menos seis meses, e piora do quadro no último mês. Relata ganho\nponderal de 10 kg nos últimos três meses (Índice de massa corpóreo atual = 36,8 kg/m2 ). Faz uso\nirregular de antiácido por conta própria. Trazia consigo um resultado de endoscopia digestiva alta\ncom o seguinte laudo: ?erosões lineares de até 5 mm, não confluentes, localizadas em esôfago\ndistal?. Baseado no diagnóstico acima, você prescreve um inibidor de bomba de prótons durante\noito semanas e orienta a paciente a","options":{"A":"perder peso e evitar deitar-se imediatamente após\nas refeições.","B":"evitar ingestão de café e praticar esportes.","C":"suspender carne vermelha da alimentação e ingestão de bebidas gaseificadas.","D":"dormir com cabeceira da cama elevada e abolir\nfibras na dieta.","E":"aumentar a ingesta de proteínas e reduzir a ingesta\nde carboidratos"},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-138664","number":"138664","sourceNumber":"138664","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Homem, com 45 anos de idade, com dor epigástrica diária, ocorrendo no período\npós-prandial e à noite, e perda ponderal de 4 kg, começou uso de inibidor de bomba de próton\n\n(IBP) com alguma melhora. Informa que não usa álcool ou antinflamatórios não hormonais. Ainda\nna vigência da medicação realizou endoscopia\ndigestiva alta que revelou gastrite nodosa de antro e\ncorpo, e úlcera duodenal em fase de cicatrização. Biópsias de mucosa gástrica foram realizadas\ndurante o procedimento, e submetidas ao teste rápido de urease em fase líquida, cujo resultado foi\nnegativo. Quanto ao tratamento para Helicobacter pylori nesse paciente, conclui-se que","options":{"A":"não há necessidade de tratamento, pois o agente etiológico não é o Helicobacter pylori.","B":"não há necessidade de tratamento, pois a cicatrização da úlcera ocorre após a erradicação da\nbactéria.","C":"o tratamento está indicado e o uso de IBP interfere no teste de urease.","D":"há necessidade de tratamento profi lático contra reinfecção, mesmo havendo cura.","E":"há necessidade de tratamento especial para Helicobacter pylori resistente aos antibióticos."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-22155","number":"22155","sourceNumber":"22155","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Acerca das doenças que acometem o esôfago, julgue o item a seguir. Dilatação do\ncorpo do esôfago, perda da peristalse\nesofágica e extremidade distal do esôfago com afunilamento\nuniforme em bico são exemplos de alterações radiológicas observadas em esofagramas baritados\nde paciente com diagnóstico de acalasia de esôfago.","options":{"A":"certo","B":"errado"},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-22156","number":"22156","sourceNumber":"22156","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Acerca das doenças que acometem o esôfago, julgue os itens a seguir. A esofagite\ncáustica por ingestão de medicamentos pode ser\ncausada por clindamicina, anti-inflamatórios não\nesteroidais, comprimidos de cloreto de potássio e vitamina C, entre outros, e pode ser prevenida\npela ingestão de vários goles de água (antes e após a ingestão de medicamento) e pela\nmanutenção de posição ortostática após a ingestão da medicação.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-22157","number":"22157","sourceNumber":"22157","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Acerca das doenças que acometem o esôfago, julgue os itens a seguir. O esôfago de\nBarrett é uma complicação da doença por refluxo gastroesofágico e representa uma condição na\nqual o epitélio escamoso do esôfago é substituído por epitélio colunar metaplásico.","options":{"A":"certo","B":"errado"},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-8639","number":"8639","sourceNumber":"8639","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Um paciente de 29 anos de idade, com queixas de disfagia para sólidos há 10 anos e\npiora progressiva nos últimos meses, procurou atendimento médico. O exame físico evidenciou\npaciente muito emagrecido, mas em bom estado geral. Considerando o caso clínico descrito, julgue\no item subsequente. Durante a investigação diagnóstica do caso em apreço, a ausência de ondas\nterciárias no esôfago será indicativa de que o paciente deverá ser submetido a uma cardioplastia\nou ressecção esofágica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-8685","number":"8685","sourceNumber":"8685","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"No próximo item, é apresentada uma situação clínica hipotética envolvendo a interface\nda pediatria com a cirurgia pediátrica, seguida\nde uma assertiva a ser julgada. Uma radiografia de\ntórax de um neonato com diagnóstico clínico de atresia de esôfago revela coto proximal do esôfago\nem fundo de saco, hiperaerado, e uma radiografia de abdome mostra presença de ar no estômago\ne intestinos. Nessa situação, o diagnóstico mais provável é de atresia de esôfago, com fístula do\nsegmento distal do esôfago para a via aérea inferior.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-352186","number":"352186","sourceNumber":"352186","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente feminina, parda, 36 anos, obesa, apresenta pirose e regurgitação diariamente\nhá cerca de 3 meses. Nega disfagia, perda de\npeso, hiporexia, hemorragia digestiva ou outras\nqueixas. Nega comorbidades. Ao terminar de contar a sua história, a paciente fez uma pergunta:\npreciso fazer algum exame para saber o que eu tenho? Marque a alternativa com a resposta\ncorreta a esse questionamento.","options":{"A":"Sim. Está indicada a realização de uma pHmetria de 24 horas, uma vez que é o exame padrão\nouro para o diagnóstico.","B":"Não. A paciente apresenta sintomas típicos de doença do refluxo gastroesofágico e, como não\ntem sinais de alarme, não está indicada a\nrealização de endoscopia digestiva alta ou qualquer outro\nexame para confirmação diagnóstica.","C":"Sim. Deve ser realizada uma endoscopia digestiva alta em todos os pacientes com sintomas\nsugestivos de doença do refluxo gastroesofágico.","D":"Sim. É necessário realizar uma endoscopia digestiva alta e um Raio-X contrastado do esôfago\npara o diagnóstico diferencial com\nacalasia."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-368181","number":"368181","sourceNumber":"368181","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Um paciente com 54 anos de idade, usuário de diclofenaco sódico por lombalgia,\napresenta, há algumas horas, dor súbita em\nepigástrio, que rapidamente se irradia para todo o\nabdome. Não apresenta vômitos. Está taquicárdico e taquipneico. Ao exame abdominal, nota-se\nabdome em tábua, mas com sinal de Jobert ausente. A radiografia de abdome e de tórax com\ncúpulas é normal. Nesse caso, o diagnóstico mais provável é","options":{"A":"necrose intestinal.","B":"infarto do miocárdio.","C":"perfuração de úlcera péptica.","D":"pancreatite aguda."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-351614","number":"351614","sourceNumber":"351614","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"O quadro clínico na infecção pelo Helicobacter pylori (H. pylori) é diversificado e\nrelaciona-se a alguns sinais e sintomas. Com\nrelação a esses sinais, é CORRETO afirmar que após\na infecção primária pelo H. pylori","options":{"A":"metade das pessoas infectadas pode apresentar sintomas de gastroenterite.","B":"raramente ocorre evolução para quadro de úlcera péptica gástrica e duodenal.","C":"ocorrem náuseas e vômitos, o que provoca uma diminuição transitória de secreção ácida e\nhipercloridria.","D":"metade das pessoas infectadas pode apresentar sintomas de gastrite aguda."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-368186","number":"368186","sourceNumber":"368186","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Uma paciente do sexo feminino, 33 anos de idade,1,64 m, 55 kg, operada de refluxo há\ndois anos, refere queixa de azia regular há um ano e meio. Relata que faz uso de antiácido, sem\nreceita médica, com pouca melhora. Faz uso também de anticoncepcional oral, cálcio e vitamina D.\nRealizou uma endoscopia recente com esofagite não erosiva e fundoplicatura continente com boas\npregas envolvendo o aparelho de endoscopia. Foi prescrito inibidor de bomba de próton (IBP), com\npouca melhora em duas semanas. Após aumento da dose, a paciente se apresenta para avaliação\ndo cirurgião, mas não refere melhora nos sintomas. A conduta que deve ser adotada para essa\npaciente é","options":{"A":"realizar a reoperação à Nissen, laparoscópica.","B":"aumentar a dose de IBP.","C":"realizar a endoscopia digestiva alta.","D":"fazer o registro de pH esofágico prolongado."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-337619","number":"337619","sourceNumber":"337619","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Homem, 71 anos, tem história de cirurgia de gastrectomia parcial e reconstrução a\nBillroth II por úlcera gástrica\nestenosante. Procura atendimento com queixa de episódios de dor\nabdominal associada a náuseas e distensão, com alívio imediato após vômitos biliares. Em relação\nao diagnóstico e tratamento desse paciente, analise as afirmativas a seguir: I- A principal\nhipótese é\nde gastrite alcalina e deve ser solicitada impedâncio-Phmetria. II- O quadro clínico é compatível\ncom a síndrome da alça aferente. III- O tratamento para este caso deve ser o de fazer a Bilroth II\nem um Y de Roux. IV- A principal hipótese é de obstrução da alça eferente, e a melhor conduta é\nconverter para uma Bilroth I. Está(ão) CORRETA(S) as afirmativas:","options":{"A":"IV apenas.","B":"II e III apenas.","C":"I apenas.","D":"I e IV apenas."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-346842","number":"346842","sourceNumber":"346842","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Homem de 72 anos queixava-se de epigastralgia em queimação há 3 semanas. É\nportador de HAS e faz uso de enalapril,\nsinvastatina e AAS para prevenção primária de eventos\ncardiovasculares. Realizou EDA. Após o resultado, recebeu a prescrição de omeprazol 20mg em\njejum por 4 semanas, com resolução completa dos sintomas. Endoscopia Digestiva Alta (EDA):\ngastrite endoscópica enantematosa moderada do antro; úlcera na transição do corpo para o antro\nna curvatura menor, de fundo limpo, bordas regulares e planas, de 8mm, sem sinais de\nsangramento recente. Teste da urease negativo. Bx: gastrite crônica do antro; sem sinais de\nmalignidade. Assinale a alternativa que apresenta a conduta MAIS adequada para esse paciente\nnesse momento.","options":{"A":"Repetir a EDA.","B":"Suspender o uso do AAS.","C":"Substituir o AAS por prasugrel.","D":"Manter o uso do omeprazol por tempo indeterminado."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-345720","number":"345720","sourceNumber":"345720","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Um dos eventos mais temidos nos pacientes com hemorragia digestiva alta é o\nressangramento. Diante disso, vários escores\nsão utilizados para prever tal evento. Considerando a\nclassificação de Forrest, os pacientes que apresentam maior risco de ressangramento são os\nclassificados em Forrest:","options":{"A":"IA.","B":"IB.","C":"IIA.","D":"IIB."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-291923","number":"291923","sourceNumber":"291923","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Com relação às complicações da doença do refluxo gastroesofágico, é CORRETO\nafirmar que:","options":{"A":"O uso de anti-inflamatórios não hormonais pode ter um efeito profilático no desenvolvimento de\nadenocarcinoma em pacientes portadores de esôfago de Barrett.","B":"O diagnóstico de esôfago de Barrett é confirmado através da visualização endoscópica de\nepitélio metaplásico substituindo o epitélio escamoso do esôfago.","C":"O achado endoscópico de úlceras esofágicas profundas é típico da doença do refluxo\ngastroesofágico.","D":"O esôfago distal é a sede das estenoses pépticas com, geralmente, mais de 3cm."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-305001","number":"305001","sourceNumber":"305001","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Analise os fatores a seguir. I. Abuso de álcool; II. Sobrepeso associado ao estresse;\nIII.\nSíndrome de Zollinger-Ellison; IV. Overdose de radioterapia no abdome superior; São fatores\npossivelmente associados à gênese da úlcera péptica;","options":{"A":"I e II, apenas.","B":"I, III e IV, apenas.","C":"II e III, apenas.","D":"I, II, III e IV."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-287848","number":"287848","sourceNumber":"287848","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente apresenta dor epigástrica abrupta, intensa, que se difunde para a fossa ilíaca\ndireita e, em seguida, para todo o abdome, e ao exame, o abdome apresenta-se distendido, com\nperitonismo difuso e rigidez involuntária. Com base nessas informações, assinalar a alternativa que\napresenta o diagnóstico mais provável:","options":{"A":"Pancreatite aguda.","B":"Apendicite aguda.","C":"Isquemia mesentérica.","D":"Úlcera péptica perfurada.","E":"Diverticulite aguda."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-283902","number":"283902","sourceNumber":"283902","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente de 72 anos chega ao consultório se queixando de disfagia. Relata também\nque vem apresentando tosse, salivação\nexcessiva, regurgitação de alimentos mal digeridos e\nhalitose. Qual o provável diagnóstico?","options":{"A":"Divertículo de Meckel.","B":"Úlcera gástrica.","C":"Volvo intestinal.","D":"Divertículo de Zenker.","E":"Divertículo epifrênico."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-266401","number":"266401","sourceNumber":"266401","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente masculino, 63 anos, pedreiro, com dor crônica em região lombar fazendo uso\nde anti-inflamatório há 03 meses consecutivos. Deu\nentrada na Unidade de Pronto Atendimento\ncom dor abdominal súbita, de forte intensidade. Ao exame apresenta taquicardia, taquipneia e\nsinais de irritação peritoneal. Raio X de tórax e Rx de abdome em pé evidenciam pneumoperitônio.\nQual o mais provável diagnóstico?","options":{"A":"Úlcera perfurada.","B":"Diverticulite aguda.","C":"Neoplasia de cólon.","D":"Isquemia mesentérica."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-260709","number":"260709","sourceNumber":"260709","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"De qual artéria se origina a artéria gastroepiplóica direita:","options":{"A":"Hepática.","B":"Esplênica.","C":"Gástrica direita.","D":"Celíca.","E":"Gastroduodenal."},"answer":"E","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-227103","number":"227103","sourceNumber":"227103","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente do sexo masculino, 43 anos, com quadro de dor em região epigástrica há 24\nhoras, é admitido no pronto-socorro. Na\nhistória tem antecedente de hipertensão arterial sistêmica e\nDiabetes Mellitus. Ao exame clínico, apresenta palpação dolorosa em região epigástrica e flancos.\nRaio X abdominal em posição ortostática revela presença de sinal de Rigler. Hemograma com\nleucocitose e dosagem de amilase com valor de 363mgr/dl. Considerando o caso descrito, assinale\no diagnóstico MAIS PROVÁVEL para esse paciente.","options":{"A":"Pancreatite aguda.","B":"Úlcera duodenal perfurada.","C":"Colecistite aguda.","D":"Colangite aguda."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-232136","number":"232136","sourceNumber":"232136","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"São situações especiais em que está indicada a escolha do uso de inibidores H2\n(Ranitidina) para profilaxia de úlcera de estresse em detrimento aos bloqueadores de bomba de\nprótons (Omeprazol) por motivos de interação medicamentosa:","options":{"A":"Pacientes em uso de ácido acetilsalicílico e clopidogrel.","B":"Pacientes em uso de ácido acetilsalicílico.","C":"Pacientes em uso de clopidogrel, fenitoína e corticoides via enteral.","D":"Pacientes em uso de clopidogrel e corticóde via enteral.","E":"Pacientes em uso de clopidogrel e fenitoína via enteral."},"answer":"E","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-232145","number":"232145","sourceNumber":"232145","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Assinale, abaixo, de qual estrutura vascular a artéria gástrica direita é ramo:","options":{"A":"Artéria esplênica.","B":"Artéria hepática.","C":"Troco celíaco.","D":"Artéria gastroepiplóica esquerda.","E":"Artéria pancreatoduodenal superior."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-227291","number":"227291","sourceNumber":"227291","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"V.C.X., feminino, 39 anos, com diagnóstico prévio de doença do refluxo gastroesofágico\nhá 10 anos, inicialmente com sintomas\n3?4x/semana, com melhora completa dos sintomas após\ntratamento com Inibidores de Bomba de Prótons (IBP). Durante endoscopia digestiva alta realizada\nde controle de esofagite erosiva, foi evidenciada mucosa esofágica distal de cor rósea, de cerca de\n02 cm de extensão e foram realizadas múltiplas biópsias que evidenciaram metaplasia intestinal\nsem sinais de displasia. No momento, paciente com controle adequado de sintomas com IBP.\nDiante do quadro, qual a recomendação para a paciente?","options":{"A":"Fundoplicatura a Nissen.","B":"Ressecção endoscópica.","C":"Ablação endoscópica.","D":"Repetir endoscopia a cada 3 a 5 anos."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-246781","number":"246781","sourceNumber":"246781","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"FMC, masculino, 70 anos, queixa-se de disfagia há 3 anos associada a halitose e\nregurgitação de alimentos não digeridos. Refere também que frequentemente percebe\nabaulamento na região cervical, mas que nem sempre é perceptível. Sobre o caso clínico podemos\nafirmar:","options":{"A":"Trata-se de provável distúrbio motor do esôfago. Assim o diagnóstico será confirmado após uma\nesofagomanometria.","B":"Devido a idade, devemos considerar como principal hipótese o câncer de esôfago. Assim,\nrealizar uma endoscopia digestiva alta deve ser a primeira medida.","C":"a principal hipótese é de divertículo esofágico verdadeiro, formado em área de fraqueza entre\nhipofaringe e esôfago conhecida como trígono de Killian","D":"considerando a principal hipótese de divertículo de Zencker, devemos evitar a indicação inicial\nda endoscopia digestiva alta, pelo risco de\nperfuração acidental.","E":"A confirmação diagnóstica provavelmente será mediante uma pHmetria ou após melhora clínica\ncom IBP (prova terapêutica)."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-246784","number":"246784","sourceNumber":"246784","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Sobre a doença do refluxo gastroesofágico (DRGE) e a obesidade, podemos afirmar,\nEXCETO:","options":{"A":"A obesidade atua como fator de risco para a DRGE, tanto por interferir no funcionamento do\nesfíncter esofageano inferior quanto pelo aumento da pressão intra-abdominal.","B":"Atualmente a DRGE é considerada comorbidade associada/agravada pela obesidade, podendo\nvir a indicar cirurgia bariátrica quando\npaciente tiver IMC acima de 35.","C":"Os pacientes obesos, com IMC acima de 35 e refratários ao tratamento da DRGE com IBP, têm\na opção da fundoplicatura gástrica com\nválvula total (Nissen) como indicação terapêutica pertinente\ne com bons resultados na remissão dos sintomas.","D":"os pacientes com obesidade severa (IMC>40) e DRGE têm na cirurgia bariátrica o melhor aliado\npara tratamento das duas doenças e o Bypass Gástrico em Y de Roux tem sido a técnica mais\nadequada nestes pacientes, quando comparada ao Sleeve (gastrectomia vertical).","E":"Tanto a obesidade quanto a DRGE atuam como fatores de risco para o adenocarcinoma de\nesôfago."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-196781","number":"196781","sourceNumber":"196781","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"O procedimento cirúrgico de escolha para o tratamento da doença do refluxo\ngastroesofágico, na maioria dos pacientes, deve ser a cirurgia de:","options":{"A":"Lind.","B":"Thal.","C":"Heller modificada.","D":"Nissen."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-215153","number":"215153","sourceNumber":"215153","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Uma paciente de 41 anos de idade, com queixa de dor epigástrica em queimação de\nlonga data relacionada à ingesta de alimentos condimentados, retorna em consulta ambulatorial\ntendo como resultado de endoscopia digestiva alta o diagnóstico de úlcera duodenal e pesquisa de\n\nH. pylori positivo. Relatava uso esporádico de antiácidos, mas com pouca melhora da dor. Nega\nuso de Anti-inflamatórios não Esteroidais\n(AINES). Qual a associação de medicamentos com\nmelhor nível de evidência científica para o tratamento desse caso?","options":{"A":"Agente antissecretor, omeprazol e claritromicina.","B":"Inibidor da bomba de prótons, eritromicina e amoxicilina.","C":"Inibidor da bomba de prótons, amoxicilina e claritromicina.","D":"Antagonistas do receptor H2 de histamina, claritromicina e amoxicilina.","E":"Manter antiácidos e iniciar inibidor de bomba de prótons."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-199600","number":"199600","sourceNumber":"199600","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Julgue as afirmativas abaixo sobre a Doença Ácido-Péptica em Verdadeiras (V) ou\nFalsa (F) e em seguida assinale a alternativa correta. ( ) Cerca de duas semanas após o início do\nuso de anti-inflamatórios não esteroidais, cerca de 5% dos pacientes desenvolvem erosões e\núlceras gástricas. ( ) O risco de desenvolver úlcera durante o uso de anti-inflamatórios não\nesteroidais é maior em pacientes acima de 60 anos de idade, em pacientes que previamente\ntiveram úlcera, em pacientes que usam corticosteroides e em pacientes com comorbidades\nimportantes. ( ) O risco de desenvolvimento de úlcera na presença do Helicobacter Pylori é\ndeterminado por fatores relacionados a bactéria, não tendo os fatores do hospedeiro qualquer\ninterferência nesse processo. ( ) A hemorragia é a complicação mais comum da úlcera péptica,\nsendo as úlceras causadas pelos anti-inflamatórios não esteroidais responsáveis por uma\nproporção maior dessa complicação.","options":{"A":"V, V, F, V.","B":"F, F, F, V.","C":"V, F, F, V.","D":"F, V, F, F."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-202737","number":"202737","sourceNumber":"202737","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente feminina, 72 anos, hipertensa, diabética, renal crônica em tratamento\nconservador, dá entrada no pronto\natendimento, com história de vômitos em borra de café.\nRealizada endoscopia de urgência: identificada úlcera ativa em bulbo duodenal com estigmas\nendoscópicos de sangramento recente. Com relação à propedêutica, em caso de presença de\núlcera péptica ativa, podemos afirmar que:","options":{"A":"Tanto a úlcera gástrica quanto a úlcera duodenal devem ser biopsiadas durante a realização de\nendoscopia para fins de diagnóstico diferencial com neoplasia, não havendo necessidade de\nrealizar nova endoscopia após o tratamento para controle de cura.","B":"Apenas a úlcera gástrica deve ser biopsiada durante a realização de endoscopia para fins de\ndiagnóstico diferencial com neoplasia, havendo necessidade de realizar nova endoscopia após o\ntratamento para controle de cura.","C":"Apenas a úlcera duodenal deve ser biopsiada durante a realização de endoscopia para fins de\ndiagnóstico diferencial com neoplasia, sendo necessário realizar nova endoscopia após o\ntratamento para controle de cura.","D":"Tanto a úlcera gástrica quanto a úlcera duodenal devem ser biopsiadas durante a realização de\nendoscopia para fins de diagnóstico diferencial com neoplasia, havendo necessidade de realizar\nnova endoscopia após o tratamento para controle de cura.","E":"Apenas a úlcera gástrica deve ser biopsiada durante a realização de endoscopia para fins de\ndiagnóstico diferencial com neoplasia, não havendo necessidade de realizar nova endoscopia após\no tratamento para controle de cura."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-202748","number":"202748","sourceNumber":"202748","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente feminina, 72 anos, hipertensa, diabética, renal crônica em tratamento\nconservador, dá entrada no pronto atendimento,\ncom história de vômitos em borra de café.\nRealizada endoscopia de urgência: identificada úlcera ativa em bulbo duodenal com estigmas\nendoscópicos de sangramento recente. Com relação à classificação endoscópica dos estigmas de\nsangramento, encontrados nas lesões em paciente com HDA não varicosa, e a indicação de\ntratamento endoscópico dos mesmos, podemos afirmar que:","options":{"A":"Úlcera Forrest IIb apresenta-se com coágulo aderido e deve receber tratamento endoscópico.","B":"Úlcera Forrest Ib apresenta-se com coágulo aderido e não deve receber tratamento\nendoscópico.","C":"Úlcera Forrest IIa apresenta-se com sangramento em jato e deve receber tratamento\nendoscópico.","D":"Úlcera Forrest IIc apresenta-se com coto vascular visível e não deve receber tratamento\nendoscópico.","E":"Úlcera Forrest III apresenta-se com hematina e deve receber tratamento endoscópico."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-215133","number":"215133","sourceNumber":"215133","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Qual das localizações seguintes de úlceras gástricas está associada ao aumento de\nprodução de ácido?","options":{"A":"Cardia.","B":"Fundo.","C":"Incisura Angular.","D":"Pré pilórica.","E":"Grande curvatura."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-199639","number":"199639","sourceNumber":"199639","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente masculino, 65 anos, evoluindo com plenitude pós-prandial progressiva\nassociada à perda de peso. Apresenta\ntratamento crônico de doença péptica, sendo por duas\nvezes diagnosticado úlcera de bulbo duodenal, nos últimos 03 anos. Fez tratamento com Inibidores\nde Bomba de Prótons (IBP) por 12 semanas, sem melhora do quadro. Já tratou Helicobacter pylori\npor duas vezes. Realizou endoscopia digestiva alta que impossibilitou a passagem do aparelho ou\nde uma sonda alimentar, devido à estenose pilórica. As biópsias realizadas no exame foram\nnegativas para malignidade. A conduta mais adequada é:","options":{"A":"Dobrar a dose do IBP e alta para casa com dieta líquida restrita.","B":"Internação e realização de gastrostomia endoscópica para estabelecimento de via alimentar.","C":"Internação, terapia nutricional parenteral e preparação para tratamento cirúrgico da estenose\npilórica.","D":"Internação e cirurgia de urgência devido ao quadro obstrutivo alto."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-199598","number":"199598","sourceNumber":"199598","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente J.A.M.C., 42 anos, previamente hígido, foi encaminhado pelo\ngastroenterologista para avaliação de\ntratamento cirúrgico de Doença do Refluxo Gastroesofágico\n(DRGE). Paciente apresenta história de regurgitação alimentar, principalmente após as refeições,\ncom episódios quase diários, alegando melhoras com uso de Inibidores de Bomba de Prótons\n(IBP). Paciente desejando realizar o procedimento cirúrgico para evitar uso crônico de IBP e\nsintomas. Os exames essenciais para avaliação pré-operatórias da DRGE são, exceto:","options":{"A":"Endoscopia digestiva alta.","B":"Manometria esofágica.","C":"pHmetria esofagiana de 24h.","D":"Tomografia computadorizada de abdome."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-172511","number":"172511","sourceNumber":"172511","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente 32 anos é submetido a uma endoscopia digestiva de urgência sem anestesia\npara retirada de pedaço de carne. Procedimento\ndescrito como tecnicamente difícil devido agitação\ndo paciente, que evolui ao término com choque circulatório grave e insuficiência respiratória. Ao\nexame clínico: torporoso, taquipneico, ausculta abolida à direita, com hipertimpanismo à percussão\ntorácica direita, jugulares túrgidas, RCR 2t 110bpm, PA 60x30mmHg, bulhas hipofonéticas e pulso\nparadoxal. Em relação ao caso marque a alternativa que contém todas as proposições adequadas\n(diagnósticas, terapêuticas):","options":{"A":"Perfuração de esôfago torácico, pneumotórax hipertensivo à direita, pneumomediastino. Medidas\nde suporte de vida, drenagem torácica e\ntoracotomia para sutura primária da lesão.","B":"Perfuração de esôfago cervical, pneumotórax hipertensivo à direita, pneumomediastino. Medidas\nde suporte de vida, drenagem torácica e\n\ncervicostomia para sutura primária da lesão","C":"Perfuração de esôfago torácico, pneumotórax hipertensivo à direita, pneumomediastino.\n\nMedidas de suporte de vida, drenagem torácica, suspensão\ndieta oral e nutrição parenteral prolongada.","D":"Perfuração de esôfago abdominal, pneumotórax hipertensivo à direita. Medidas de suporte de\nvida, drenagem torácica e laparotomia para sutura primaria da lesão","E":"Perfuração de esôfago torácico, hemotórax à direita, tamponamento cardíaco. Medidas de\nsuporte de vida, drenagem torácica e pericárdica de urgencia, tomografia de tórax para\nprogramação do tratamento definitivo."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-172519","number":"172519","sourceNumber":"172519","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente 32 anos é submetido a uma endoscopia digestiva de urgência sem anestesia\npara retirada de pedaço de carne. Procedimento\ndescrito como tecnicamente difícil devido agitação\ndo paciente, que evolui ao término com choque circulatório grave e insuficiência respiratória. Ao\nexame clínico: torporoso, taquipneico, ausculta abolida à direita, com hipertimpanismo à\npercussão torácica direita, jugulares túrgidas, RCR 2t 110bpm, PA 60x30mmHg, bulhas\nhipofonéticas e pulso paradoxal. Esse mesmo paciente é transferido ao HECI após 10 dias do\nevento inicial, proveniente de outro hospital onde estava internado no CTI. Relatório enviado\ndaquele hospital relatava: 01 TC tórax sem identificar local da lesão esôfago; 01 laparotomia que\n\ntambém não identificou a lesão; outra TC tórax após cerca de 3 dias da endoscopia, dessa vez com\ncontraste no esôfago, sem extravasamento do contraste; pneumonia extensa e empiema pleural à\ndireita. Estava em uso de antibióticos de largo espectro, intubado sob ventilação mecânica, com\ndreno torácico à direita, recebendo nutriçãoparenteral exclusiva, sedado, estável\nhemodinamicamente. Novamente marque a alternativa com as proposições mais adequadas:","options":{"A":"Diagnóstico de lesão de esôfago muito pouco provável devido à alta sensibilidade da TC de\ntórax com contraste esofageano realizada.\nProvável diagnóstico de pneumonia aspirativa à direita,\nmanter antibióticos por 28 diasdevido ao empiema, passar sonda nasoenteral para desmame de\nnutrição parenteral.","B":"Diagnóstico de lesão de esôfago muito pouco provável devido à alta sensibilidade da TC de\ntórax com contraste esofageano realizada.\nProvável diagnóstico de pneumonia aspirativa à direita,\nmanter antibióticos por 28 dias devido ao empiema e realizar esofagograma com contraste baritado\npara exclusão definitiva do diagnóstico.","C":"Lesão de esôfago sem abordagem cirúrgica precoce. Realizar esofagoscopia para confirmar a\nlocalização da lesão e implante de prótese por endoscopia (stent) para isolamento da lesão. Manter\nantibióticos por 28 diasdevido ao empiema, iniciar retirada da nutrição parenteral.","D":"Lesão de esôfago sem abordagem cirúrgica precoce. Realizar esofagoscopia para confirmar a\nlocalização da lesão. Realizar esofagostomia proximal para desvio do trânsito e controle do\n\nempiema, jejunostomia para nutrição enteral e programar tratamento cirúrgico somente após\ninfecção totalmente controlada.","E":"Lesão de esôfago sem abordagem cirúrgica precoce. Realizar esofagografia com contraste\nsolúvel em água para confirmar a localização\nda lesão e logo após encaminhar o paciente ao\ncentro cirúrgico para reparo da lesão, além de melhor abordagem do empiema. Manter antibióticos\npor 28 dias."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-187459","number":"187459","sourceNumber":"187459","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"No decorrer da fundoplicatura laparoscópica, diversas intercorrências podem ocorrer no\nintraoperatório. Notavelmente a hemorragia, quando ocorre, se origina da:","options":{"A":"Perfuração gástrica.","B":"Laceração esofagiana.","C":"Laceração hepática.","D":"Lesão dos vasos gástricos curtos.","E":"Perfuração esofagiana."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-172745","number":"172745","sourceNumber":"172745","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"J.A.C.M., 54 anos, previamente hígido, iniciou quadro de disfagia para sólidos e\nlíquidos concomitante há 06 meses, com piora progressiva, regurgitação e perda de peso. Foi\nrealizado o seguinte exame: Baseado neste exame, responda: qual aspecto característico\nencontrado, qual o diagnóstico mais provável e qual o melhor tratamento curativo?","options":{"A":"Esôfago em bico de pássaro, acalasia, esofagectomia com reconstrução com tubo gástrico.","B":"Dolicoesôfago, espasmo esofagiano difuso, esofagectomia.","C":"Esôfago em saca-rolhas, espasmo esofagiano difuso, bloqueadores do canal do cálcio.","D":"Esôfago em bico de pássaro, acalásia, cardiomiotomia à Heller."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-148549","number":"148549","sourceNumber":"148549","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Em relação à Doença do Refluxo Gastroesofágico (DRGE), assinale a alternativa\nCORRETA:","options":{"A":"A maioria dos pacientes com sinais e/ou sintomas extraesofágicos também apresentam\nsintomas típicos de DRGE concomitantes.","B":"O principal mecanismo fisiopatológico relacionado à DRGE é o relaxamento não relacionado à\ndeglutição, chamado de relaxamento transitório do esfíncter inferior do esôfago.","C":"A falta de resposta ao tratamento clínico com inibidor de bomba de próton é uma indicação ao\ntratamento cirúrgico da DRGE.","D":"Pacientes que apresentam na endoscopia digestiva alta uma ou mais soluções de continuidade\nda mucosa, com mais de 5 mm e que se estendam\nentre duas pregas longitudinais, são\nclassificados como Los Angeles B.","E":"Os antagonistas dos receptores H2, assim como os inibidores de bomba de prótons, são drogas\nseguras e bem toleradas e resultam em\ninibição completa da secreção ácida."},"answer":"E","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-155476","number":"155476","sourceNumber":"155476","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Qual o sítio mais comum de linfomas do sistema gastrointestinal?","options":{"A":"Estômago.","B":"Baço.","C":"Íleo terminal.","D":"Cólon direito.","E":"Pâncreas."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-162577","number":"162577","sourceNumber":"162577","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente de 58 anos, masculino, etilista crônico com dor abdominal há 24 horas, de\ninício agudo em epigástrio, generalizando-se\nhá 12 horas. Piora progressiva da intensidade da dor.\nRefere que está em tratamento para lombalgia. Ao ser examinado, médico observa distensão\nabdominal, ausência de peristalse, palpação dolorosa com irritação peritoneal. Qual melhor conduta\ninicial frente à principal hipótese diagnóstica?","options":{"A":"Radiografia simples de abdome decúbito","B":"Tomografia de abdome em decúbito.","C":"Radiografia simples de tórax em ortostase.","D":"Tomografia de tórax em ortostase.","E":"Laparoscopia."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-148543","number":"148543","sourceNumber":"148543","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente submetido à gastrectomia à Billroth II (BII), devido à doença péptica, vem\nrelatando discreta perda de peso e agravo nos\nvômitos biliosos. Foi submetido à endoscopia\ndigestiva alta, que evidenciou gastrite erosiva intensa, associada a importante refluxo biliar.\nDevido\nà intratabilidade clínica, foi decidido pelo tratamento cirúrgico. Qual o procedimento mais\nutilizado?","options":{"A":"Gastrectomia total com reconstrução à BII.","B":"Gastrectomia total com reconstrução em y de Roux.","C":"Conversão de anastomose à BII em y de Roux.","D":"Gastrectomia subtotal com reconstrução à BII.","E":"Nenhuma das anteriores."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-126898","number":"126898","sourceNumber":"126898","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A maioria dos casos de hemorragia gastrointestinal alta maciça é secundária a uma\núlcera duodenal. Esta hemorragia é causada pela erosão de uma artéria sob a base úlcera.\n\nAssinale a alternativa que apresenta CORRETAMENTE a localização da úlcera e o ramo arterial\nque penetra por esta parede, respectivamente:","options":{"A":"Parede anterior e artéria gástrica esquerda.","B":"Parede posterior e artéria gastroepiploica direita.","C":"Parede posterior e artéria gastroduodenal.","D":"Parede anterior e artéria gastroepiploica esquerda."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-126906","number":"126906","sourceNumber":"126906","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"L.M.O.L., sexo feminino, 34 anos, história pregressa recente de ingesta de soda\ncáustica, apresenta episódios de tosse durante\nqualquer tentativa de deglutição alimentar.\nEndoscopia Digestiva Alta (EDA) evidencia esôfago de mucosa edemaciada e hiperemiada\ndifusamente, com fibrina e áreas de necrose superficial, além de orifício de 2,0 cm de diâmetro,\nlocalizado a 22,0 cm da arcada dentária superior, sugestivo de fístula. A broncoscopia confirmou\nfístula esofagotraqueal em nível da carina. Assinale a alternativa que apresenta a MELHOR\nconduta para essa paciente.","options":{"A":"Introdução de prótese esofágica para bloquear a fístula.","B":"Introdução de endoprótese traqueal para bloquear a fístula.","C":"Esofagocoloplastia retroesternal.","D":"Esofagectomia seguida de esofagogastroplastia ou esofagocoloplastia cervical."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-137811","number":"137811","sourceNumber":"137811","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Sobre a doença do refluxo gastroesofágico (DRGE) é correto afirmar:","options":{"A":"A DRGE é uma doença rara.","B":"A DRGE possui uma prevalência maior durante a terceira década de vida.","C":"A DRGE cursa apenas com sintomas gastrointestinais.","D":"Os antiácidos desempenham papel primário no tratamento da DRGE.","E":"A DRGE é um fator de risco importante para o desenvolvimento de esôfago de Barrett."},"answer":"E","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-127200","number":"127200","sourceNumber":"127200","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Quanto ao paciente que apresenta ingestão de substâncias cáusticas marque a\nalternativa incorreta.","options":{"A":"As lesões causadas por ácidos são devidas a necrose por coagulação, formando uma escara e\nimpedindo as lesões mais profundas.","B":"As lesões causadas por ácidos são devidas a necrose liquefativa e por isso atigem tecidos mais\nprofundos.","C":"A endoscopia digestiva alta pode ser feita em até 24 horas após a ingestão.","D":"A radiografia de tórax só é útil na avaliação de uma possível perfuração do esôfago ou do\nestômago.","E":"Os pacientes que ingerem álcali podem evoluir mais frequente para estenose de esôfago do que\nos que ingerem ácidos."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-102725","number":"102725","sourceNumber":"102725","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"O exame ideal para a quantificação do refluxo gastroesofágico para o estabelecimento\nda relação com os sintomas é:","options":{"A":"Manometria.","B":"Esofagografia.","C":"pHmetria de 24 horas.","D":"Endoscopia."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-102727","number":"102727","sourceNumber":"102727","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Em relação à doença do refluxo gastroesofágico, assinale a alternativa INCORRETA.","options":{"A":"A prevalência e a gravidade da doença vêm aumentando gradativamente.","B":"O exame padrão-ouro para o diagnóstico é a endoscopia digestiva alta.","C":"A maioria dos pacientes responde ao tratamento clínico bem conduzido.","D":"A metaplasia intestinal (Barret) é fator de risco para o adenocarcinoma."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-106464","number":"106464","sourceNumber":"106464","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"No sangramento maciço das úlceras pépticas, as artérias mais acometidas são:","options":{"A":"pancreatoduodenal superior e gástrica esquerda.","B":"pancreatoduodenal inferior e gastroduodenal.","C":"pancreatoduodenal superior e gastroduodenal.","D":"pancreatoduodenal inferior e gastroepiploica.","E":"pancreatoduodenal inferior e superior."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-106465","number":"106465","sourceNumber":"106465","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente sexo masculino, 36 anos de idade, com quadro que se iniciou há vários meses\ncom disfagia após a ingestão de líquidos,\nprincipalmente os gelados, e posteriormente com disfagia\npara alimentos sólidos. Evolui com regurgitação de alimentos não digeridos, perda de peso e\ninfecções pulmonares de repetição. Alivia-se da disfagia com elevação do queixo e extensão do\npescoço. O diagnóstico mais provável é:","options":{"A":"acalasia.","B":"divertículo de Zenker.","C":"câncer do esôfago.","D":"esofagite de refluxo.","E":"monilíase esofágica."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-101029","number":"101029","sourceNumber":"101029","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Recém-nascido (RN) de três semanas de vida apresenta vômitos claros após as\nmamadas desde o nascimento, que foram\naumentando progressivamente, com perda de peso igual\na 15% e constipação intestinal. Mãe relata que RN nasceu bem, a termo, adequado para idade\ngestacional e apresenta boa sucção e não apresenta problemas na amamentação. Ao exame\nfísico, o RN mostrava-se hipo-hidratado. A bioquímica e gasometria evidenciavam alcalose\nmetabólica hipopotassêmica e hipoclorêmica. O diagnóstico é:","options":{"A":"Refluxo Gástroesofágico Fisiológico.","B":"Estenose Hipertrófica de Piloro.","C":"Acidose Tubular Renal Tipo I.","D":"Acidose Tubular Renal Tipo II.","E":"Hiperplasia Congênita de Supra Renal por deficiência 21 hidroxilase."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-87396","number":"87396","sourceNumber":"87396","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Qual das alternativas a seguir é correta quanto à DRGE (Doença do Refluxo\nGastroesofágico).","options":{"A":"Pacientes jovens sem sinais de gravidade com queixa de pirose e regurgitação ácida podem ser\ntratados com inibidores de bomba de prótons sem realização prévia de EDA (Endoscopia Digestiva\nAlta).","B":"Disfagia é um achado que ocorre em mais de 80% dos pacientes no pós-operatório do\nFundoplicatura de Nissen.","C":"Manifestações da DRGE ocorrem ao menos uma vez na vida em mais de um terço da população\ngeral; desses, aproximadamente metade são\nsubmetidos à Fundoplicatura de Nissen.","D":"A EDA é o exame padrão-ouro no diagnóstico de DRGE uma vez que identifica alterações\ninflamatórias em cerca de 90% dos casos.","E":"Pacientes com sintomas extraesofágicos de DRGE têm manifestações mais intensas e não\nrespondem ao tratamento clínico. Por isso, devem ser sempre tratados cirurgicamente."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-77503","number":"77503","sourceNumber":"77503","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"SLO, 49 anos, sexo feminino, apresenta quadro de disfagia e foi encaminhada para a\nrealização de manometria esofágica. Quanto ao resultado da manometria poderemos afirmar,\nEXCETO:","options":{"A":"Na acalásia, o Esfíncter Esofagiano Inferior (EEI) apresenta-se com tônus aumentado e com\nrelaxamento incompleto à deglutição; as contrações peristálticas são ausentes.","B":"No Esfíncter Esofagiano Inferior Hipertenso, o EEI apresenta-se com tônus aumentado e com\nrelaxamento completo à deglutição; as contrações peristálticas estão presentes.","C":"No esôfago em \"quebra-nozes\", o EEI apresenta-se com o tônus normal e com relaxamento\ncompleto; as contrações peristálticas estão presentes.","D":"Na acalasia vigorosa, o EEI apresenta-se com tônus aumentado ou normal e com relaxamento\nparcial ou ausente à deglutição; as\ncontrações peristálticas são ausentes.","E":"No espasmo esofagiano difuso, o EEI apresenta-se com o tônus muito aumentado e com\nrelaxamento completo e intermitente à deglutição; as contrações peristálticas estão presentes."},"answer":"E","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-77550","number":"77550","sourceNumber":"77550","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"JSC, 45 anos, apresenta quadro recorrente de dor abdominal epigástrica tipo\nqueimação, há alguns meses. Há uma semana\niniciou quadro de vômitos intensos, várias vezes ao\ndia, não biliosos e com restos alimentares do dia anterior. Diante deste quadro clínico qual o\nmelhor\nexame para o diagnóstico e que distúrbio este paciente apresenta?","options":{"A":"Ultrassom abdominal e alcalose metabólica.","B":"Ultrassom abdominal e acidose metabólica.","C":"Radiografia de abdômen em ortostase e decúbito dorsal e alcalose metabólica.","D":"Endoscopia digestiva alta e hipopotassemia.","E":"Endoscopia digestiva alta e alcalose metabólica com cloro plasmático alto."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-59073","number":"59073","sourceNumber":"59073","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Em relação à Doença do Refluxo Gastroesofágico (DRGE) é correto afirmar:","options":{"A":"A intensidade e a frequência de sintomas de DRGE são excelentes preditores da presença e da\ngravidade da esofagite ao exame de endoscopia digestiva alta.","B":"O esôfago de Barrett é uma complicação pouco frequente da DRGE e se caracteriza pela\npresença de metaplasia gástrica em qualquer extensão do esôfago.","C":"Os melhores resultados do tratamento cirúrgico da DRGE são observados nos pacientes que\nnão apresentam melhora com uso de inibidores de\nbomba de prótons.","D":"O risco de malignização no esôfago de Barrett está relacionado à extensão do epitélio\nmetaplásico.","E":"Na presença de esôfago de Barrett, o tratamento cirúrgico é a melhor opção terapêutica, pois se\nmostrou eficaz em reduzir a extensão da mucosa metaplasica e em eliminar do risco de\nadenocarcinoma."},"answer":"E","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-59034","number":"59034","sourceNumber":"59034","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente do sexo masculino apresenta quadro de disfagia progressiva e\nemagrecimento acentuado. Observe as afirmações e assinale a alternativa incorreta.","options":{"A":"Acalasia é condição pré-maligna e a lesão pode aparecer após 20 anos de doença, podendo ser\num carcinoma de células escamosas ou adenocarcinoma.","B":"O câncer de esôfago é o câncer de crescimento mais rápido no aparelho digestivo.","C":"Em alguns países desenvolvidos, o adenocarcinoma corresponde a mais de 60% dos tumores\nde esôfago.","D":"O carcinoma espinocelular afeta de maneira semelhante homens brancos e homens\nafro-americanos.","E":"O tabagismo e o álcool aumentam o risco de câncer do trato digestivo superior em cinco vezes."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-59098","number":"59098","sourceNumber":"59098","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Não é achado radiológico no esofagograma de paciente com acalásia:","options":{"A":"Dilatação do esôfago em graus variados.","B":"Presença de ondas peristálticas no corpo do esôfago, em todas as fases da doença.","C":"Ausência da bolha gástrica.","D":"Retardo no esvaziamento esofagiano.","E":"Estreitamento distal do esôfago com aspecto de bico de pássaro."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-43935","number":"43935","sourceNumber":"43935","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"O tronco celíaco constitiu um importante ponto de referência na cirurgia abdominal.\nFazem parte do tronco celíaco:","options":{"A":"Artéria gástrica esquerda, artéria hepática direita e artéria lienal.","B":"Artéria gastroduodenal, artéria hepática comum e artéria mesentérica superior.","C":"Artéria gástrica esquerda, artéria hepática comum e artéria lienal.","D":"Artéria mesentérica superior, artéria mesentérica inferior e artéria hepática.","E":"Artéria esplênica, artéria gastroduodenal e artéria mesentérica superior."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-27351","number":"27351","sourceNumber":"27351","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A Duodenorrafia com Epiploonplastia, utilizada rotineiramente no tratamento cirúrgico\nda Úlcera Péptica Duodenal Perfurada com\nPeritonite foi preconizada por:","options":{"A":"Kehr","B":"Halsted","C":"Graham","D":"Weinberg","E":"Mc Vay"},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-27354","number":"27354","sourceNumber":"27354","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A descoberta do Helicobacter Pylori e seu tratamento mudaram radicalmente a\nindicação cirúrgica eletiva para a úlcera péptica\nduodenal. No diagnóstico desta bactéria Gram (-),\num método tem sua sensibilidade próximo de 95% e sua especificidade de 99%. Marque abaixo\neste método.","options":{"A":"Endoscopia digestiva com GastroAcidograma","B":"Teste da Urease","C":"Lavagem gástrica + Citologia esfoliativa","D":"Teste com C 14","E":"Biópsia + Exame histopatológico"},"answer":"E","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-27358","number":"27358","sourceNumber":"27358","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A atonia Gástrica que leva ao retardo no esvaziamento de sólidos e acelera o\nesvaziamento de líquidos, ocorre geralmente devido as vagotomias:","options":{"A":"Troncular + Superseletiva","B":"Seletiva + Superseletiva","C":"Superseletiva","D":"Seletiva + Troncular","E":"Troncular"},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-8069","number":"8069","sourceNumber":"8069","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Um paciente do sexo masculino com 37 anos, com história clínica compatível com\ndoença do refluxo gastro-esofágico,\nsintomático há vários anos. É submetido a endoscopia\ndigestiva alta, que evidencia alterações esofágicas compatíveis com Esôfago de Barret. Em relação\na esta enfermidade, assinale a alternativa correta.","options":{"A":"É conhecido precursor de câncer epidermoide de esôfago, devendo proceder-se a\nesofagectomia em 3 tempos na vigência do mesmo.","B":"É conhecido fator de risco de adenocarcinoma de esôfago, estando indicada a esofagectomia\ntrans-hiatal à Pinotti no momento do\ndiagnóstico endoscópico.","C":"Não tem relação direta com nenhum tipo de neoplasia, devendo o seu tratamento ser através de\nacompanhamento clínico bianual.","D":"É definida como substituição do epitélio escamoso de esôfago pelo epitélio colunar tipo\nintestinal, estando a conduta na dependência do grau de displasia.","E":"A esofagectomia do segmento afetado é tratamento indicado quando a displasia for de baixo\ngrau por 3 anos seguidos."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-8125","number":"8125","sourceNumber":"8125","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Com relação a úlcera péptica, marque a afirmativa incorreta.","options":{"A":"A infecção gástrica pelo Helicobacter pylori é responsável por mais de 95% casos de úlcera\nduodenal e mais de 80% dos casos de úlcera gástrica.","B":"A hemorragia digestiva pode ser a primeira manifestação da doença em 10% dos pacientes com\núlcera.","C":"O uso de anti-inflamatórios é a segunda etiologia mais comum, especialmente na população\nmais idosa.","D":"Nas úlceras associadas à infecção pelo Helicobacter pylori a erradicação da infecção promove\nmelhora da sintomatologia, cicatrização da úlcera e prevenção da recidiva ulcerosa e das\ncomplicações.","E":"O controle de cura da infecção após o tratamento do Helicobacter pylori deve ser realizado\nimediatamente após o fim do tratamento."},"answer":"E","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-339779","number":"339779","sourceNumber":"339779","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Mulher, 48 anos. História de disfagia progressiva para líquidos e sólidos há 2 anos.\nPerda não intencional de peso. Traz\nesofagograma com estreitamento distal \"bico de pássaro\".\nTeste de Machado-Guerreiro negativo. Nasceu e mora no Recife. A manometria evidencia\nrelaxamento incompleto do esfíncter inferior, ausência de peristalse e atividade contrátil do corpo\nesofágico. De acordo com a classificação de Chicago, é CORRETO afirmar que a paciente\napresenta:","options":{"A":"Doença de Chagas grau I.","B":"Acalásia tipo I.","C":"Acalásia tipo II.","D":"Acalásia tipo III.","E":"Doença de Chagas grau II."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-317155","number":"317155","sourceNumber":"317155","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Sobre os divertículos esofágicos é incorreto afirmar, EXCETO:","options":{"A":"A tuberculose é a principal causa de divertículos de pulsão.","B":"O divertículo mais comum do esôfago é o divertículo de Zenker, ocorrendo geralmente após a 5ª\ndécada de vida.","C":"O divertículo faringo-esofágico é considerado um divertículo verdadeiro, pois envolve todas as\ncamadas do órgão.","D":"O trígono de Killian é uma região de fraqueza à esquerda na hipofaringe."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-334777","number":"334777","sourceNumber":"334777","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A DRGE (Doença do Refluxo Gastroesofágico) é uma patologia com complexos\nmecanismos fisiopatológicos. Dentre eles, considera-se o mais importante:","options":{"A":"Relaxamentos transitórios do esfíncter esofágico inferior.","B":"Alterações do peristaltismo esofágico levando a um déficit no clareamento.","C":"Hipertonicidade do esfincter esofágico inferior.","D":"Maior extensão intra-abdominal do esfincter esofágico inferior."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-258175","number":"258175","sourceNumber":"258175","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Leia o caso clínico a seguir. Paciente jovem, do sexo feminino, com sintomas recentes\nde dispepsia funcional, sem nenhum sinal de\nalarme, apresenta teste respiratório positivo para\nHelicobacter pylori. Nesse caso, qual conduta deve ser realizada?","options":{"A":"Solicitar Endoscopia Digestiva Alta (EDA) com biópsia para avaliar o grau de atividade\ninflamatória antes de iniciar tratamento.","B":"Iniciar tratamento com inibidor de bomba de prótons e, após oito semanas, solicitar Endoscopia\nDigestiva Alta (EDA) caso não apresente remissão dos sintomas.","C":"Tratar imediatamente a infecção pelo H. pylori e fazer controle de tratamento após quatro\nsemanas com novo teste respiratório.","D":"Tratar imediatamente a infecção pelo H. pylori e fazer controle de tratamento logo após o\ntérmino dos antibióticos com Endoscopia Digestiva Alta (EDA)."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-355626","number":"355626","sourceNumber":"355626","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente masculino, 38 anos, com história de dor epigástrica, realiza endoscopia\ndigestiva alta que revela a presença de úlcera duodenal. A presença de Helicobacer pylori é\ncomprovada por biópsia. Assinale a opção que indica o tratamento para sua erradicação:","options":{"A":"A claritromicina deve ser utilizada em todas as linhas de tratamento, pois apresenta baixos\níndices de resistência.","B":"Para o tratamento de primeira linha é recomendada terapêutica dupla, incluindo um inibidor de\nbomba de prótons.","C":"O tratamento sequencial com amoxicilina e levofloxacino, cinco dias cada, pode ser uma opção\nde segunda linha quando não há resposta a um\nesquema triplo inicial.","D":"Nos pacientes com exposição anterior aos macrolídeos, a terapia incluindo subsalicilato de\nbismuto por 14 dias pode ser recomendada.","E":"Para um segundo tratamento, pode ser usado o mesmo esquema antibiótico já prescrito\nanteriormente, por período mais prolongado"},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-355630","number":"355630","sourceNumber":"355630","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente de 85 anos deu entrada no pronto-socorro com dor abdominal de início súbito\nhá sete horas. Encontra-se no 16° dia\npós-operatório de artroplastia de quadril, descorado, face de\ndor, pulso 125 bpm, pressão arterial 90 mmHg x 60mmHg e descompressão brusca positiva em\ntodo o abdome. O diagnóstico mais provável e a conduta adequada são:","options":{"A":"dissecção aguda de aorta, laparotomia exploradora","B":"abdome agudo vascular; arteriografia","C":"abdome agudo vascular, laparotomia exploradora","D":"ulcera péptica, sutura","E":"neoplasia gástrica, gastrectomia"},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-362692","number":"362692","sourceNumber":"362692","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Assinale a alternativa que apresenta um exame indicado para a confirmação das\nafecções do trato digestivo em crianças:","options":{"A":"Enterorresonância magnética do abdome.","B":"A endoscopia digestiva alta com biópsias de trato digestório.","C":"Enterotomografia do abdome.","D":"Endoscopia digestiva baixa em menores de 4 anos de idade."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-353864","number":"353864","sourceNumber":"353864","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Um menino de 7 anos é levado ao pediatra com queixas de desconforto abdominal,\nnáuseas e sensação de saciedade precoce, sem nenhuma causa orgânica aparente após\ninvestigação. Diagnóstico de dispepsia funcional é confirmado. Dadas as seguintes afirmações\nsobre o tratamento da dispepsia funcional em crianças, é CORRETO afirmar:","options":{"A":"Amitriptilina é contraindicada para o tratamento da dispepsia funcional.","B":"Os inibidores da bomba de prótons devem ser usados continuamente em todos os pacientes.","C":"O tratamento consiste em evitar anti-inflamatórios não esteroides, alimentos com condimentos\npicantes, gordurosos ou com cafeína.","D":"Psicoterapia não tem eficácia no processo doloroso."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-353857","number":"353857","sourceNumber":"353857","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A úlcera péptica ou Úlcera Gastroduodenal (UGD) é uma lesão que ocorre na mucosa\ndo trato gastrointestinal, sendo\ncaracterizada por um desequilíbrio entre fatores agressores e\nprotetores da mucosa gástrica. Sobre essa úlcera: I. A dor é habitualmente muito intensa, em\nqueimação e mantém-se por alguns dias, desaparece e ressurge em um novo intervalo de dias, de\nforma arrítmica. Outros sintomas dispépticos são bastante comuns e quase sempre associados,\ncomo flatulência, sialorreia, náuseas e vômitos. II. O segundo fator etiológico mais importante da\nUGD é representado pelos Anti-Inflamatórios Não Esteroides (AINEs). A aspirina e os AINEs\ninibidores da Ciclo-Oxigenase-1 (COX-1) são potencialmente agressivos para a mucosa\ngastroduodenal. III. Em casos de especialistas bem treinados, a anamnese, juntamente com o\nexame físico, confirmará com facilidade o diagnóstico da UGD, uma vez que poucos diagnósticos\ndiferenciais apresentam sintomatologia semelhante. Das proposições acima:","options":{"A":"Apenas I e II estão corretas.","B":"Apenas I está correta.","C":"Apenas II está correta.","D":"Todas estão incorretas."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-353793","number":"353793","sourceNumber":"353793","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente, 52 anos, sexo masculino, com histórico de refluxo gastroesofágico, é\ndiagnosticado com esôfago de Barrett. Ele pergunta ao médico sobre as opções de tratamento e\nsuas eficácias. Com base nos conhecimentos atuais, dadas as seguintes afirmações, a que em\nrelação ao tratamento do esôfago de Barrett está CORRETA é:","options":{"A":"O tratamento com IBP em dose dobrada e cirurgia são eficazes na regressão do epitélio\nmetaplásico no esôfago de Barrett.","B":"A cirurgia é o único tratamento eficaz na regressão do epitélio metaplásico no esôfago de\nBarrett.","C":"Tanto a terapia clínica com IBP quanto a cirúrgica são eficazes apenas em controlar o refluxo,\ndiminuindo o processo inflamatório e a progressão da doença.","D":"O tratamento com IBP em dose dobrada e cirurgia são eficazes na regressão do epitélio\nmetaplásico no esôfago de Barrett."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-354750","number":"354750","sourceNumber":"354750","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A indicação de tratamento cirúrgico para um paciente que apresenta doença do refluxo\ngastro-esofágico deve ser feita quando","options":{"A":"a manometria apresenta baixo peristaltismo no terço distal do esôfago.","B":"a pHmetria apresenta vários episódios com pH 6.","C":"apresenta esofagite erosiva grau III.","D":"apresenta pontuação no índice De Mister baixo."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-346451","number":"346451","sourceNumber":"346451","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A perfuração de úlcera duodenal, leva à perda de macicez hepática, que\npropedeuticamente se traduz pelo sinal de:","options":{"A":"Torres-Homem;","B":"Rovsing;","C":"Giordano;","D":"Jobert."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-334145","number":"334145","sourceNumber":"334145","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A doença do refluxo gastroesofágico pode ser tratada de maneira clínica e/ou cirúrgica.\nUm dos passos principais da cirurgia para\ncorreção de hérnia de hiato é a confecção da válvula\nanti-refluxo. Das técnicas abaixo, a que originalmente apresenta uma abordagem torácica e\nabdominal é:","options":{"A":"Lind","B":"Toupet","C":"Dor","D":"Belsey Mark IV"},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-321611","number":"321611","sourceNumber":"321611","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"O linfoma do tipo MALT gástrico apresenta-se normalmente como uma doença\nindolente e multifocal com sintomas\ninespecíficos do trato digestivo. Qual seria a melhor opção\nrelacionada ao tratamento da patologia em questão?","options":{"A":"O único tratamento curativo possível do linfoma MALT é a gastrectomia total associado a\nquimioterapia.","B":"Os Sintomas B (febre, calafrios e perda de peso) são de aparecimento precoce e relacionam-se\na menor resposta ao tratamento do linfoma MALT.","C":"A erradicação do H. pylori pode regredir a neoplasia nos estágios iniciais.","D":"A infecção por H. pylori acomete cerca de 50% dos casos e o tratamento do H. pylori não possui\nimpacto no tratamento do linfoma MALT."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-300796","number":"300796","sourceNumber":"300796","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente, sexo feminino, 38 anos, com dor torácica intensa e sensação de queimação.\nA dor se irradia para o pescoço e é\noriginada geralmente após as refeições e quando se deita, não\nsendo desencadeada por esforços. O ECG seriado está normal, assim como os níveis de troponina.\nNesse contexto, é INCORRETO afirmar:","options":{"A":"É apropriado avaliar a dor torácica para descartar isquemia cardíaca.","B":"Uma das causas mais comuns de ''dor torácica'', particularmente em pacientes jovens, é o\nrefluxo gastroesofágico ou o espasmo esofágico.","C":"Essa paciente tem sintomas clássicos de esofagite de refluxo e o melhor tratamento é com\ninibidor de bomba de prótons.","D":"Considerando a origem da dor, como narrado, ela deve ser investigada com teste de esforço\ncom tálio."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-311889","number":"311889","sourceNumber":"311889","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente de 45 anos apresenta-se à emergência com dor abdominal intensa, de início\nsúbito há 4 horas. Não tem comorbidades.\nAo exame, apresenta-se com abdome rígido e com\nirritação peritoneal difusa. Foi diagnosticado com úlcera péptica perfurada e submetido à\nlaparotomia após compensação clínica inicial. Vislumbrou-se uma úlcera gástrica tipo I (até 1,5cm\nde distância entre fundo e antro) perfurada. Em relação a este caso clínico, qual conduta deve ser\nadotada, levando-se em consideração que o paciente alcançou estabilidade hemodinâmica durante\na condução clínica?","options":{"A":"Fechamento com tampão e vagotomia troncular.","B":"Gastrectomia distal com reconstrução a Billroth I.","C":"Vagotomia troncular com piloroplastia.","D":"Fechamento com tampão e tratamento para H. pylori."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-294250","number":"294250","sourceNumber":"294250","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente tabagista, de 51 anos, deu entrada na emergência com quadro de dor\nabdominal súbita há duas horas. Após avaliação pela equipe da cirurgia e radiografia simples de\ntórax, foi indicada laparotomia exploradora por suspeita de úlcera perfurada. Achado\nintraoperatório: úlcera gástrica perfurada justa pilórica com orifício de 2,2 cm e calo fibroso\nimportante, com peritonite generalizada. Nesse caso, qual é a melhor conduta operatória?","options":{"A":"Exteriorização de sonda de gastrostomia por orifício de perfuração e fixação da mesma.","B":"Rafia de perfuração gástrica com \"\"pach\"\" de omento.","C":"Vagotomia troncular, piloroplastia e rafia de perfuração.","D":"Antrectomia com reconstrução em Y de Roux."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-317925","number":"317925","sourceNumber":"317925","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Na irrigação gástrica, a artéria gastroduodenal geralmente é ramo da artéria","options":{"A":"gástrica esquerda.","B":"gástrica direita.","C":"esplênica.","D":"hepática."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-314104","number":"314104","sourceNumber":"314104","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Se considerarmos a Doença do Refluxo Gastroesofágico, em qual das seguintes\ncondições clínicas está mais bem estabelecida sua associação?","options":{"A":"Erosão dentária.","B":"Pneumonia bronco aspirativa.","C":"Sinusite etmoidal.","D":"Fibrose pulmonar."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-316307","number":"316307","sourceNumber":"316307","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Relacione a melhor indicação cirúrgica para cada caso e marque a alternativa da\nsequência correta: 1- Cirurgia de Nissen; 2-\nCirurgia de Heller; 3- Cirurgia de Serra Dória; 4-\nEsofagectomia total; ( ) Paciente com cirurgia prévia de cardiomiotomia esofágica com recidiva dos\nsintomas. ( ) Megaesôfago grau 3, de causa idiopática. ( ) Paciente chagásico com diagnóstico de\nmegaesôfago grau 4. ( ) Doença do refluxo gastroesofágico e Esôfago de Barret confirmado à\nbiópsia.","options":{"A":"3, 2, 4, 1","B":"4, 2, 3, 1","C":"3, 1, 4, 2","D":"2, 4, 1, 3"},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-311903","number":"311903","sourceNumber":"311903","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A classificação de Forrest foi elaborada com base nos achados endoscópicos em\nquadros de hemorragia gastrointestinal alta\ne pode auxiliar na implementação de medidas\nterapêuticas profiláticas de novos episódios de ressangramento na doença ulcerosa péptica. Qual a\nclassificação de Forrest para o achado endoscópico de sangramento ativo e não pulsátil na doença\nda úlcera péptica?","options":{"A":"Grau Ib.","B":"Grau Ia.","C":"Grau IIa.","D":"Grau IIb."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-317160","number":"317160","sourceNumber":"317160","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Com relação as doenças ácido-pepticas podemos afirmar corretamente:","options":{"A":"O uso de IBPs (Inibidores da bomba de prótons) por períodos prolongados está formalmente\ncontra-indicado pelo risco de atrofia gástrica e desenvolvimento de câncer gástrico;","B":"Esta indicado a realização de biopsias endoscópicas durante o diagnóstico de ulcera duodenal\nativa pelo risco de desenvolvimento de\nadenocarcinoma;","C":"A infecção prolongada pelo H.pylori está associada ao desenvolvimento da gastrite crônica ativa;","D":"Devemos solicitar EDA (endoscopia digestiva alta) em todos os pacientes com dispepsia alta."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-294269","number":"294269","sourceNumber":"294269","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente de 32 anos, sexo masculino, consulta pela primeira vez no ambulatório de\ngastroenterologia, basicamente por queixa de disfagia proximal, há cerca de um ano, com entalos\nfrequentes e até a necessidade de endoscopia de urgência para retirada de bolo alimentar\nimpactado. Nesse caso, qual é a hipótese diagnóstica?","options":{"A":"Acalásia e para essa definição, deve ser realizado o exame de endoscopia digestiva alta.","B":"Esofagite eosinofílica, especialmente se a endoscopia revelar fenômeno de felinização do\nesôfago e friabilidade do tipo papel crepom.","C":"Adenocarcinoma de esôfago, especialmente em portadores de doença do refluxo de longa data,\ncujo epitélio do esôfago proximal pode ter sofrido metaplasia.","D":"Disfagia lusória, podendo ser necessária inclusive a realização de arteriografia, para detectar a\npresença de artéria subclávia esquerda aberrante."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-295358","number":"295358","sourceNumber":"295358","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente do sexo feminino, de 20 anos, com dispepsia há seis meses, sem tratamentos\nprévios. Foi submetida a endoscopia que\nevidenciou gastrite antral enantematosa leve. A avaliação\nhistopatológica demonstrou presença de Helicobacter pylori em pequena quantidade no antro\ngástrico. Neste caso, a conduta inicial mais apropriada é:","options":{"A":"Lanzoprazol 30 mg/1x/dia, por 28 dias.","B":"Lanzoprazol 30 mg + domperidona 10 mg/2x/dia, por 28 dias.","C":"Lanzoprazol 30 mg/2x/dia + Claritromicina 500 mg/2x/dia + Amoxicilina 1.000 mg/2x/dia, por 14\ndias.","D":"Lanzoprazol 30 mg/2x + Amoxicilina 1.000 mg/2x + levofloxacina 500 mg/1x, por 10 dias."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-300835","number":"300835","sourceNumber":"300835","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A acalasia é um distúrbio de motilidade esofágica congênito, caracterizado por\nperistaltismo esofágico defeituoso e falta de\nrelaxamento do esfíncter esofágico inferior durante a\ndeglutição. O tratamento não operatório mais eficaz para o distúrbio apresentado é:","options":{"A":"Bloqueadores dos canais de cálcio.","B":"Toxina botulínica.","C":"Dilatação pneumática.","D":"Esofagomiotomia videolaparoscópica."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-300837","number":"300837","sourceNumber":"300837","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente adulto, jovem, com sensação de queimadura no tórax, por trás do esterno,\ntosse noturna, rouquidão, infecções pulmonares\nde repetição e episódios de dor torácica. Relata\nque já fez endoscopia digestiva alta. Apresenta avaliação cardiológica normal. Considerando os\nrelatos apresentados, o provável diagnóstico é:","options":{"A":"Hérnia diafragmática.","B":"Refluxo gastroesofágico.","C":"Neoplasia de pulmão.","D":"Neoplasia de laringe."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-311965","number":"311965","sourceNumber":"311965","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A dispepsia acomete uma parcela significativa da população adulta e é uma demanda\nfrequente na atenção primária à saúde. Em relação à síndrome dispéptica, assinale a alternativa\nque apresenta um sinal de alerta e indicação para realizar endoscopia digestiva como abordagem\ninicial.","options":{"A":"Distensão abdominal.","B":"Dor aliviada por antiácidos.","C":"Regurgitação ácida.","D":"Perda de peso involuntária."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-300974","number":"300974","sourceNumber":"300974","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Um paciente de 40 anos, com queixa de dor epigástrica, sem irradiação, com 3 meses\nde evolução, realiza endoscopia digestiva alta\nque demonstra lesão ulcerada na parede anterior do\nbulbo duodenal, sem sangramento ativo, com teste de urease positivo. Com relação ao diagnóstico\ndessa lesão, assinale a alternativa CORRETA:","options":{"A":"Após o tratamento de H pylori, o método de escolha para confirmar a erradicação é a sorologia.","B":"O teste para H pylori somente deve ser realizado em lesões ulceradas com sangramento ativo.","C":"Histologia, cultura e teste rápido da urease são os testes invasivos para o diagnóstico de H\npylori.","D":"Os testes não invasivos para o diagnóstico de H. pylori são a sorologia e a cultura."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-300975","number":"300975","sourceNumber":"300975","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"É causa da síndrome de Zollinger-Ellison e os principais sintomas são os causados pela\nhipersecreção péptica ácida:","options":{"A":"Tumor carcinoide.","B":"Adenocarcinoma gástrico.","C":"Insulinoma.","D":"Gastrinoma."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-281812","number":"281812","sourceNumber":"281812","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente procedente do interior de Goiás, do sexo feminino, de 35 anos, com história\nprévia de tratamento de gastrite crônica\nrelacionada ao H. pylori há um ano atrás, tendo utilizado o\nesquema tríplice (IBP + Amoxicilina 1 g + Claritromicina 500 mg), duas vezes ao dia por sete dias.\nNa sua última endoscopia, há 20 dias, evidenciou úlcera duodenal em cicatrização (fase H2 da\nclassificação de Sakita) com anatomopatológico mostrando gastrite crônica leve, com atividade leve\ne presença do H. pylori (+/3+). Nesse caso, qual é a melhor conduta?","options":{"A":"Retratar com tratamento tríplice (IBP + Amoxicilina 1 g + Claritromicina 500 mg), duas vezes ao\ndia, dessa vez estendido por 14 dias.","B":"Retratar com tratamento tríplice (IBP + Amoxicilina 1 g + metronidazol 500 mg), duas vezes ao\ndia, por sete dias.","C":"Retratar com tratamento tríplice (IBP + Amoxicilina 1g), duas vezes ao dia, + Levofloxacina 500\nmg, uma vez ao dia, por 14 dias.","D":"Retratar com tratamento quádruplo (IBP + Amoxicílina 1 g + metronidazol 500 mg +\nFurazolidona 200 mg), duas vezes ao dia, por sete dias."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-281978","number":"281978","sourceNumber":"281978","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente TSGV, sexo masculino, 33 anos, procura ambulatório de cirurgia digestiva,\ncom queixa de disfagia há cerca de 4 anos, com\npiora no último ano acompanhada de perda\nponderal importante (cerca de 10kg). Foi solicitado exame contrastado de esôfago, que evidenciou\nmegaesôfago grau 3 (mostrado abaixo). Sobre a doença e o tratamento, é incorreto afirmar:","options":{"A":"Acalásia é o distúrbio esofágico primário de motilidade mais comum, podendo ser idiopática ou\nchagásica.","B":"Trata-se de uma doença motora (neurogênica) em que há o relaxamento parcial ou ausente do\nEEI (esfíncter esofágico inferior).","C":"Dilatação endoscópica é indicada para megaesôfago graus I e II, para melhorar quadro\nnutricional de pacientes sem condição cirúrgica,\npara pacientes operados, porém com sintomas\npersistentes e para gestantes.","D":"Cirurgia de Heller-Pinotti indicada no tratamento cirúrgico para pacientes com megaesôfago grau\nIII e IV; consiste na cardiomiotomia com\nconfecção de válvula antirrefluxo parcial."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-277418","number":"277418","sourceNumber":"277418","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"O conhecimento anatômico da vascularização gástrica é de extrema importância para a\nlinfadenectomia na cirurgia do câncer de estômago. Quanto a essa irrigação, as origens das\nartérias gastroepiplóicas esquerda e direita são, respectivamente:","options":{"A":"celíaca e gastroduodenal","B":"esplênica e gastroduodenal","C":"esplênica e hepática","D":"celíaca e hepática"},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-281285","number":"281285","sourceNumber":"281285","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Assinale a alternativa com a correta associação celular funcional do estômago.","options":{"A":"Célula G - produz pepsina.","B":"Célula D - produz somatostatina.","C":"Célula parietal - produz gastrina.","D":"Célula enterocromafin - produz peptídeo intestinal vasoativo."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-281290","number":"281290","sourceNumber":"281290","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Sobre os linfomas gástricos, assinale a incorreta.","options":{"A":"Diferente do adenocarcinoma, o linfoma não tem indicação cirúrgica como primeira escolha.","B":"A cirurgia está reservada para complicações como perfuração, obstrução e sangramentos.","C":"O linfoma mais comum é o linfoma extranodal da zona marginal (MALT).","D":"O trato gastrointestinal é o local extranodal de maior acometimento dos linfomas."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-274805","number":"274805","sourceNumber":"274805","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A prevalência de sintomas dispépticos na população brasileira adulta é de\naproximadamente 40%. Sobre a abordagem de dispepsia, marque a alternativa correta.","options":{"A":"A dispepsia funcional é um diagnóstico menos comum, mas deve ser suspeitado quando houver\nsinais de alarme.","B":"A Escherichia Coli está associada à patogênese da úlcera péptica e, portanto, em quadros de\ndispepsia deve ser realizado endoscopia digestiva alta com biópsia e pesquisa dessa bactéria.","C":"A prevalência de doença orgânica grave, com câncer gástrico, na dispepsia é muito baixa e,\nportanto, só é recomendado a realização de endoscopia digestiva alta em casos que apresentam\nsinais de alerta.","D":"Uma vez iniciado o tratamento medicamentoso para dispepsia funcional, o mesmo deve ser\nmantido por pelo menos 6 meses para reduzir o risco de recorrência."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-265913","number":"265913","sourceNumber":"265913","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A doença do refluxo gastroesofágico pode ser tratada de maneira clínica e/ou cirúrgica.\nUm dos passos principais da cirurgia para\ncorreção da hérnia de hiato é a confecção da válvula\nanti-refluxo. Das técnicas abaixo, a que originalmente apresenta uma abordagem torácica e\nabdominal é:","options":{"A":"Lind.","B":"Toupet.","C":"Belsey Mark IV.","D":"Dor."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-229830","number":"229830","sourceNumber":"229830","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Considerando a acalásia como patologia rara mundialmente, entretanto tida como a\ndoença motora mais comum do esôfago, pode-se\nafirmar que","options":{"A":"no Brasil a causa mais comum é infecciosa e relacionada à doença de Chagas, o diagnóstico é\nsuspeitado pelas principais queixas que são a disfagia e regurgitação, definidoras da doença,\npodendo a mesma ser confirmada por endoscopia digestiva alta e radiografia contrastada de\nesôfago.","B":"a causa auto-imune para a acalásia tem representado mundialmente a etiologia mais provável e\na endoscopia digestiva alta é exame\nimprescindível no diagnóstico para descartar tumores da\njunção esofagogástrica.","C":"a esofagomanometria tem alta precisão no diagnóstico de acalásia mesmo nos estágios iniciais\ne é caracterizada pela falha no relaxamento\ndo esfincter esofágico superior durante a deglutição e\naperistalse.","D":"o tratamento cirúrgico atualmente consiste no padrão-ouro para tratamento da acalásia,\nindependente do estágio proposto pela\nclassificação de Chicago, não utilizada no Brasil, tendo em\nvista a principal etiologia ser chagásica."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-247408","number":"247408","sourceNumber":"247408","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente de 48 anos, sexo masculino, morador da zona rural ao norte de Anápolis,\ncomparece a consulta médica pela primeira vez\nqueixando disfagia progressiva, tanto para líquidos\nquanto para sólidos, percebida sobretudo em região retroesternal. Refere episódios de tosse e\nengasgo à noite, interrompendo o sono. Apresenta ainda constipação intestinal crônica, que\nprogrediu nos últimos dois anos. Diante da suspeita clínica, afirma-se:","options":{"A":"o diagnóstico pode ser confirmado com endoscopia digestiva alta, que documenta, por\nvisualização direta, a dismotilidade esofágica.","B":"falta de relaxamento ou relaxamento incompleto do esfíncter esofágico inferior e aperistalse do\ncorpo esofágico são achados comuns na esofagomanometria.","C":"um resultado negativo utilizando a fixação de complemento de Machado e Guerreiro exclui a\npossibilidade de acalasia de etiologia chagásica.","D":"o alívio dos sintomas pode ser obtido com a combinação de nitratos, antagonistas dos canais de\ncálcio e pró-cinéticos."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-252748","number":"252748","sourceNumber":"252748","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A doença que se caracteriza por diarreia, úlceras pépticas, tumor pancreático ou\nduodenal e hipergastrinemia é a:","options":{"A":"Doença de Whipple.","B":"Síndrome de Zollinger-Ellison.","C":"Espru tropical.","D":"Doença de Ménétrier."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-246547","number":"246547","sourceNumber":"246547","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente do sexo masculino, 72 anos, com história recente de uso abusivo de\nanti-inflamatórios orais por lombociatalgia, dá entrada no pronto-socorro com história de\n\nepigastralgia de início súbito há 4 horas. Ao exame físico, paciente encontra-se sudoreico, pálido,\ntaquicárdico e agitado. Abdômen tenso e difusamente doloroso à palpação, inclusive à\ndescompressão brusca. Realizou radiografia (ver imagem). Levando em consideração a história\nsupracitada, analise os itens que se seguem. I. Trata-se de um quadro de úlcera péptica perfurada,\nestando indicada a abordagem cirúrgica para o caso. II. Ao exame físico do abdômen, uma grande\nparcela de pacientes com essa condição apresentará o sinal de Jobert. III. Trata-se de um caso de\npancreatite necro-hemorrágica relacionado ao uso de AINEs, com o sinal da alça sentinela ao RX\nsimples de abdômen (patognomônico). Pode-se afirmar que apenas:","options":{"A":"o item I está certo.","B":"o item II está certo.","C":"o item III está certo.","D":"os itens I e II estão certos.","E":"os itens I e III estão certos."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-229840","number":"229840","sourceNumber":"229840","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Das alternativas abaixo qual NÃO se enquadra nas patologias do esôfago:","options":{"A":"Exames de alta complexidade como tomografia ou ressonância não necessariamente são\nmandatórios na avaliação inicial de\ningestão de corpo estranho (CE), que não está restrita somente\na crianças. Neste contexto, a radiografia simples pode evidenciar material radiopaco no trajeto e\ndescartar perfurações. No contexto de CE esofágico, a remoção urgente deve ser realizada na\npresença de sintomas respiratórios ou sialorréia.","B":"Remoção de pilhas e baterias é mandatória de imediato, mesmo caso já tenham alcançado o\nestômago, independente do tamanho, pelo risco de estenose e perfuração e o mesmo se aplica à\ningestão de pacotes de cocaína.","C":"A cardiomiotomia anterior, associada à fundoplicatura em 3 planos, atualmente é a prática mais\nutilizada para tratamento da acalásia inicial e megaesôfagos não avançados.","D":"Urgências oncológicas no câncer de esôfago geralmente se manifestam por sangramentos,\nperfurações e obstrução e geralmente o\ntratamento cirúrgico definitivo para a doença não é\nindicado como abordagem inicial."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-249506","number":"249506","sourceNumber":"249506","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Originalmente descrito por Zenker e Von Ziemssen, o divertículo faringo-esofágico é o\ndivertículo esofágico mais comum. Encontra-se herniando em uma região denominada trígono de\nKillian. A complicação mais mórbida do não tratamento desta doença em pacientes idosos é:","options":{"A":"Perfuração esofágica.","B":"Abscesso pulmonar e/ou pneumonias por aspiração.","C":"Esôfago de Barret.","D":"Caquexia."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-249507","number":"249507","sourceNumber":"249507","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"São fatores estimulantes da secreção ácida gástrica:","options":{"A":"Gastrina, histamina e acetilcolina.","B":"Gastrina, bradicinina e acetilcolina.","C":"Somatostatina, histamina e acetilcolina.","D":"Somatostatina, bradicinina e adrenalina."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-229545","number":"229545","sourceNumber":"229545","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Um paciente de 40 anos, com queixa de dor epigástrica, sem irradiação, com 3 meses\nde evolução realiza endoscopia digestiva alta\nque demonstra lesão ulcerada ativa na parede\nanterior do bulbo duodenal, com teste de urease positivo. Com relação ao diagnóstico dessa lesão,\nassinale a alternativa CORRETA:","options":{"A":"a cultura da mucosa gástrica é o método de escolha para o diagnóstico de H. pylori quando uma\nendoscopia é realizada após o tratamento de H pylori, o método de escolha para confirmar a\nerradicação é a sorologia.","B":"o teste para H pylori somente deve ser realizado em lesões ulceradas com sangramento ativo.","C":"histologia, cultura e teste rápido da urease são os testes invasivos para o diagnóstico de H\npylori.","D":"os testes não invasivos para o diagnóstico de H. pylori são a sorologia e a cultura."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-229878","number":"229878","sourceNumber":"229878","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente 23 anos, obesa, há 2 meses com pirose e regurgitação. Realizada endoscopia\nque evidenciou esofagite erosiva grau B de Los\nAngeles. A melhor opção terapêutica para o caso é","options":{"A":"antagonista receptor H1.","B":"inibidor bomba de prótons.","C":"procinético.","D":"antiácido."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-254277","number":"254277","sourceNumber":"254277","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente 46 anos com icterícia, dor abdominal em andar superior, prurido, acolia,\ncolúria súbita iniciados há cerca de 2 meses,\nassociado ao quadro apresentava perda ponderal de\n8 kg. Quais das opções abaixo NÃO fazem parte do diagnóstico diferencial habitualmente:","options":{"A":"Neoplasia de colédoco distal.","B":"Coledocolitíase.","C":"Doença ulcerosa péptica.","D":"Neoplasia de cabeça de pâncreas."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-229879","number":"229879","sourceNumber":"229879","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente 45 anos com disfagia lentamente progressiva. Já portador de miocardiopatia\nchagásica. O exame que avaliará melhor a\nprincipal hipótese diagnóstica é","options":{"A":"raio x contratado de esôfago estômago e duodeno.","B":"endoscopia digestiva alta.","C":"tomografia computadorizada de tórax.","D":"ressonância magnética de tórax e abdome."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-252793","number":"252793","sourceNumber":"252793","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente do sexo feminino, 70 anos, queixa-se de disfagia baixa lentamente\nprogressiva, necessitando de coluna líquida para\nalívio sintomático. Refere diagnóstico prévio de\ndoença de Chagas. Diante de um possível quadro de megaesôfago chagásico, qual seria a melhor\nopção para definir o grau da doença esofágica?","options":{"A":"Manometria esofágica.","B":"Exame contrastado do esôfago (esôfago técnica padrão).","C":"Endoscopia digestiva alta.","D":"Tomografia computadorizada do tórax."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-254281","number":"254281","sourceNumber":"254281","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente 35 anos, apresenta dor crônica em joelho esquerdo, faz uso contínuo de\nantiinflamatório por conta própria. Há 15 dias queixa de dor epigástrica, em queimação, de forte\nintensidade, piorada nas últimas 2 horas, quando procurou serviço de urgência. Ao exame\npresença de dor em epigastro associado á descompressão dolorosa","options":{"A":"No Rx de abdome agudo é esperado presença de ar subdiafragmático na posição ortostática.","B":"Leucocitose com desvio à esquerda é mandatório no hemograma.","C":"O tratamento cirúrgico é uma gastrectomia com reconstrução em \"\"Y de Roux\"\".","D":"A úlcera duodenal que perfura é de parede posterior."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-216445","number":"216445","sourceNumber":"216445","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Pedro, 46 anos, etilista e tabagista, apresenta quadro de hematêmese há\naproximadamente 2 horas associado a\nepigastralgia e palidez cutâneo-mucosa. Relata\nepigastralgia crônica e uso irregular de omeprazol. Ao exame, apresenta-se ansioso, FR: 23 irpm,\nFC: 110 bpm, PA: 95 x 60 mmhg, Sat 02: 92%, T: 37,4°C. Abdome com RHA diminuídos,\nhipertimpânico, tensão aumentada, doloroso à palpação em andar superior com descompressão\nbrusca positiva. Durante seu exame, evoluiu com novo episódio de hematêmese e piora da dor\nabdominal. Após estabilização inicial e reposição volêmica, qual a melhor opção terapêutica?","options":{"A":"Sonda naso gástrica e hemotransfusão.","B":"Endoscopia digestiva alta.","C":"Terlipressina e endoscopia digestiva alta.","D":"Laparotomia exploradora."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-216563","number":"216563","sourceNumber":"216563","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"É ramo da artéria esplênica:","options":{"A":"Artéria hepática direita.","B":"Artéria hepática comum.","C":"Artéria gastroepiplóica esquerda.","D":"Artéria gastroepiplóica direita."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-201674","number":"201674","sourceNumber":"201674","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Analise a figura a seguir. O paciente com a manometria esofagiana apresentada deve\nser submetido a que tipo de conduta?","options":{"A":"pHmetria de 24 horas.","B":"Cardiomiotomia.","C":"Confecção de válvula antirrefluxo.","D":"Introdução de medicação inibidora dos canais de cálcio."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-202677","number":"202677","sourceNumber":"202677","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Analise a figura a seguir. O procedimento realizado sobre o esôfago visto na figura é\nmelhor indicado a um paciente que realizou manometria com pressão basal do esfíncter esofagiano\ninferior de:","options":{"A":"4 mmHg, com peristalse do corpo esofagiano menor que 70%.","B":"15 mmHg, com peristalse do corpo esofagiano menor que 70%.","C":"10 mmHg e que não responde ao tratamento clínico da doença de base.","D":"10 mmHg e que se apresenta assintomático."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-202682","number":"202682","sourceNumber":"202682","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"O esôfago de Barrett tem sido foco de atenção em função do aumento da obesidade na\npopulação mundial. Esta afecção","options":{"A":"tem como causa, em proporções iguais, o refluxo ácido e o não ácido.","B":"é causado pelo refluxo ácido em proporção maior que o não ácido.","C":"é causado pelo refluxo não ácido em proporção maior que o ácido.","D":"tem relação com infecções virais e não com o refluxo gastroesofágico."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-214925","number":"214925","sourceNumber":"214925","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Um homem de 60 anos é admitido no pronto-socorro com quadro de hematêmese há 2\nhoras da admissão. Referia uso de anti-inflamatório não hormonal há 1 semana por dor no joelho\n(sic) e é diabético e hipertenso, em uso regular de medicação. Após estabilização hemodinâmica,\nfoi submetido a endoscopia digestiva alta cujo achado foi uma úlcera na parede posterior do bulbo\nduodenal de 1 cm, classificada como Forrest IB. Com relação ao caso, podemos afirmar que:","options":{"A":"o uso de monoterapia com hemoclipe representa a melhor opção terapêutica nesse caso","B":"considerando a idade, a doença associada e o alto risco de ressangramento, está indicado\ntratamento operatório de imediato","C":"em se tratando de úlcera Forrest IB, está indicada a retirada do coágulo que está aderido no\nfundo da úlcera, para a terapêutica endoscópica adequada","D":"está indicada a terapêutica endoscópica combinada, com injeção esclerosante e\ntermocoagulação"},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-201912","number":"201912","sourceNumber":"201912","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Os pólipos gástricos mais frequentemente encontrados à endoscopia são:","options":{"A":"hiperplásicos","B":"adenomas tubulares","C":"adenomas vilosos","D":"adenomasn tubulovilosos","E":"neoplasias in situ"},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-218219","number":"218219","sourceNumber":"218219","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente, 50 anos, é levado ao pronto-socorro com quadro de vômitos vigorosos com\npresença de sangue em grande volume. Antecedentes pessoais: hipertensão arterial, em uso de\nlosartana; radiculopatia, em uso de diclofenaco. Exame físico: consciente; hidratado; hipocorado\n2+/4+; FC = 100 bpm; PA = 90 x 50 mmHg; abdome: inocente; Hb: 6,8 g/dl. A primeira conduta e a\netiologia mais provável são:","options":{"A":"Endoscopia digestiva alta; úlcera péptica.","B":"Estabilização clínica; úlcera péptica.","C":"Passagem de balão de Sengstaken-Blakemore; varizes esofágicas.","D":"Endoscopia digestiva alta; Mallory-Weiss."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-218252","number":"218252","sourceNumber":"218252","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente, 72 anos, apresentando quadros repetidos de pneumonia. Refere ainda\nhalitose e dificuldade para deglutir os alimentos, por vezes referindo sensação de ?bolo na\ngarganta?. Nega perda ponderal, odinofagia ou rouquidão. A principal hipótese diagnóstica e o\nmelhor exame complementar são:","options":{"A":"Doença do refluxo gastroesofágico; pHmetria esofágica.","B":"Acalasia; esofagomanometria.","C":"Carcinoma de esôfago; endoscopia digestiva alta.","D":"Divertículo de Zenker; esofagografia baritada."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-218254","number":"218254","sourceNumber":"218254","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Sobre a doença do refluxo gastroesofágico, assinale a alternativa INCORRETA:","options":{"A":"A pHmetria de 24h é considerado o exame padrão-ouro no diagnóstico da DRGE.","B":"O esôfago de Barrett corresponde à classificação IV de Savary-Miller.","C":"O esôfago de Barrett é caracterizado por uma substituição do epitélio escamoso estratificado por\nepitélio colunar.","D":"O H. pylori não está associado à DRGE."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-216436","number":"216436","sourceNumber":"216436","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A doença esofágica que acomete o plexo mioentérico do esôfago, causando uma\ncontração mantida do esfíncter esofágico\ninferior e que se manifesta clinicamente com disfagia, é\na(o):","options":{"A":"Espasmo esofágico difuso.","B":"Acalasia.","C":"Doença do refluxo gastroesofágico.","D":"Esofagite eosinofílica."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-210595","number":"210595","sourceNumber":"210595","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Sobre o divertículo de Zenker, assinale a alternativa incorreta.","options":{"A":"Geralmente apresentam-se em pacientes idosos, na 7ª década de vida.","B":"Tosse, salivação excessiva e disfagia são sinais de doença progressiva.","C":"Esofagograma com bário é utilizado para diagnóstico.","D":"Cervicotomia direita é a via de escolha quando o tratamento é cirúrgico.","E":"Tratamento endoscópico pode ser utilizado para divertículos de 4 cm."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-202653","number":"202653","sourceNumber":"202653","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A infecção por Helicobacter pylori (HP) é uma das infecções bacterianas crônicas mais\ncomuns em humanos. De acordo com o IV Consenso Brasileiro sobre o HP,","options":{"A":"o teste rápido da urease é recomendado para controle de terapia de erradicação.","B":"o exame histológico é o método padrão-ouro para diagnóstico da infecção.","C":"a triagem do HP após a terapia de erradicação deve ser realizada pelo menos quatro semanas\napós o término do tratamento.","D":"a realização de cultura com antibiograma antes do iníco do tratamento é recomendada devido à\ncrescente resitência bacteriana."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-210527","number":"210527","sourceNumber":"210527","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Qual a classificação de Forrest para um paciente com hemorragia digestiva alta que,\ncom a endoscopia digestiva alta, foi relacionada a uma úlcera com sangramento ativo e pulsátil?","options":{"A":"IA","B":"IIA","C":"IIB","D":"IIC","E":"III"},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-216664","number":"216664","sourceNumber":"216664","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A bactéria Helicobacter pylori foi descoberta pela dupla de australianos Barry e Warren,\nrevolucionando o tratamento da doença ulcerosa péptica. A sua erradicação é responsável pela\ndiminuição no índice de recidivas e complicações como a hemorragia digestiva alta. Em 2018 foi\npublicado o novo consenso para o tratamento desta bactéria. O tratamento inicial de escolha é:","options":{"A":"Inibidor da bomba de prótons, associado a claritromicina 500 mg de 12/2h e amoxicilina 1 g de\n12/12h por um período de 14 dias.","B":"Inibidor da bomba de prótons, associado a claritromicina 500 mg de 12/2h e amoxicilina 1 g de\n12/12h por um período de 7 dias.","C":"Inibidor da bomba de prótons, associado a levofloxacina 500 mg uma vez ao dia e amoxicilina 1\ng de 12/12h por um período de 14 dias.","D":"Inibidor da bomba de prótons, associado a metronidazol 500 mg de 12/2h e claritromicina 1 g de\n12/12h por um período de 7 dias."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-214131","number":"214131","sourceNumber":"214131","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"O esôfago de Barret é uma condição pré-maligna associada à doença do refluxo\ngastroesofágico, que se define como a presença de epitélio colunar no esôfago distal. Essa\nalteração é conhecida por:","options":{"A":"Metaplasia intestinal.","B":"metaplastia esofágica.","C":"Displasia esofágica.","D":"Displasia intestinal."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-205659","number":"205659","sourceNumber":"205659","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A técnica cirúrgica do refluxo gastroesofágico com acesso pelo pilar esquerdo para\nconfecção de uma válvula de 360 graus é denominada:","options":{"A":"Fundoplicatura à Toupet.","B":"Fundoplicatura à Dor.","C":"Fundoplicatura à Nissen.","D":"Fundoplicatura à Lind."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-214147","number":"214147","sourceNumber":"214147","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente em tratamento para refluxo gastroesofágico (RGE). Há 02 dias, informa ter\napresentado estado de ansiedade severo, inquietação e informa sentir vontade de sair correndo.\nRelata ter iniciado há dois dias o uso de omeprazol e bromoprida. A hipótese diagnostica e a\nconduta mais adequada nesse caso é:","options":{"A":"Crise de ansiedade/prescrever ansiolítico.","B":"Crise psicótica/prescrever quetiapina.","C":"Reação extrapiramidal/ suspender antiemético e substituí-lo por Domperidona.","D":"O quadro não esta relacionado aos medicamentos prescritos para o RGE/orientar a paciente a\nprocurar um psicólogo(a)."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-205632","number":"205632","sourceNumber":"205632","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"O Esofagograma baritado abaixo apresenta uma alteração clássica de qual patologia?","options":{"A":"Espasmo esofágico difuso.","B":"Acalasia.","C":"Motilidade esofágica ineficaz.","D":"Carcinoma espinocelular esofágico."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-186484","number":"186484","sourceNumber":"186484","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente de 45 anos, sexo masculino, com história de cirurgia gástrica prévia há 2 anos\ndevido a doença ulcerosa péptica refratária. Relata desconforto epigástrico e cólicas que se iniciam\napós as refeições há cerca de 3 meses associado a vômitos biliosos que geram alívio dos\nsintomas. Refere que o quadro é frequente e tem interferido em suas atividades cotidianas. Ao\nexame apresenta discreta distensão abdominal e desconforto a palpação da região supraumbilical.\nHb: 9,6; Ht 31; VCM: 108; Leucócitos: 7500 1% Bastonetes. Qual o diagnóstico mais provável e\ntratamento?","options":{"A":"Síndrome de Dumping, Reconstrução tipo Billroth I.","B":"Síndrome de Alça Aferente, Reconstrução em Y de Roux.","C":"Obstrução da Alça Eferente, Reconstrução tipo Billroth II.","D":"Gastrite de Refluxo Alcalina, Reconstrução em Y de Roux."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-186435","number":"186435","sourceNumber":"186435","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente, 28 anos, sexo feminino, apresentando episódios frequentes de pirose,\nregurgitação e tosse há 4 anos, resistente\nao tratamento com inibidor de bomba de prótons. Vem\napresentando disfagia a sólidos e exames mostraram intensa esofagite distal com motilidade\nesofágica normal. Após nova avaliação, recebeu indicação de tratamento cirúrgico. Qual das\nopções abaixo descreve a cirugia de escolha para a maioria dos pacientes com o quadro acima\ndescrito?","options":{"A":"Fundoplicatura com Válvula Parcial de 180 graus.","B":"Fundoplicatura com Válvula Parcial de 270 graus.","C":"Fundoplicatura com Válvula Posterior de 250 graus.","D":"Fundoplicatura com Válvula Total de 360 graus."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-185149","number":"185149","sourceNumber":"185149","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"As células parietais localizadas no corpo gástrico são responsáveis pela secreção de","options":{"A":"gastrina.","B":"fator intrínseco.","C":"pepsina.","D":"somatostatina."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-185156","number":"185156","sourceNumber":"185156","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"O método diagnóstico considerado padrão ouro para o diagnóstico da doença do\nrefluxo gastroesofágico é","options":{"A":"a endoscopia digestiva alta.","B":"a manometria.","C":"a pHmetria de 24 horas.","D":"o esofagograma."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-173544","number":"173544","sourceNumber":"173544","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente de 50 anos apresenta disfagia progressiva para sólidos e, posteriormente,\npara líquidos, além de perda de cerca de 5 kg em\ndois anos. Foi investigado com endoscopia\ndigestiva alta que mostrou esôfago dilatado, com dificuldade de passagem do aparelho pelo cárdia\ne radiografia contrastada de esôfago, estômago e duodeno com a seguinte imagem. Nessas\ncondições, qual conduta seria indicada?","options":{"A":"Cirurgia de Serra-Dória.","B":"Esofagectomia com esofagogastroplastia.","C":"Cardiomiotomia à Heller.","D":"Inoculação de toxina botulínica no cárdia com posterior dilatação endoscópica."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-182459","number":"182459","sourceNumber":"182459","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Um homem de 64 anos fez, durante 10 anos, tratamento irregular para úlcera péptica.\nHá 6 meses, notou que os alimentos pesavam\nno estômago. Passou, então, a fazer uso de\nalimentos líquidos. Há 3 meses, apresenta diariamente vômitos alimentares à noite, com alívio da\nsintomatologia. Com base no caso clínico exposto, é correto afirmar que o provável diagnóstico é:","options":{"A":"estenose pilórica","B":"síndrome de Plummer","C":"esofagite","D":"hérnia hiatal"},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-187724","number":"187724","sourceNumber":"187724","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Em relação à esofagopatia chagásica, assinale a alternativa incorreta:","options":{"A":"É doença com marcante característica epidemiológica e endêmica.","B":"É causada pela invasão do plexo mioentérico pelo protozoário flagelado Trypanosoma cruzi e\nmais comum no sexo masculino.","C":"A miotomia de Heller é a cirurgia mais indicada para os casos classificados como estágio III de\nRezende.","D":"A regurgitação é freqüente na doença avançada."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-173545","number":"173545","sourceNumber":"173545","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Qual é a manifestação sistêmica em que o consenso de Maastricht V recomenda\nerradicação do Helicobacter pylori?","options":{"A":"Hipertensão arterial sistêmica.","B":"Nefrite intersticial.","C":"Pênfigo vulgar.","D":"Anemia ferropriva de causa desconhecida."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-185115","number":"185115","sourceNumber":"185115","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Sobre a síndrome de Zollinger-Ellison, sabe-se que:","options":{"A":"normalmente acomete mulheres com idade entre 20 e 30 anos, e está associada à neoplasia\nendócrina múltipla do tipo 2.","B":"o teste com estimulação com secretina normalmente reduz os níveis séricos aumentados de\ngastrina.","C":"os principais sintomas incluem dor abdominal, diarréia, pirose e dispepsia, e perda de peso.","D":"os locais mais frequentes de acometimento de úlcera péptica são o antro e piloro gástricos."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-173554","number":"173554","sourceNumber":"173554","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Um homem de 27 anos refere episódios recorrentes de disfagia de condução, iniciados\nhá seis meses. Durante esse período,\napresentou quatro episódios de internação para realização\nde endoscopia digestiva alta por causa de impactação alimentar, com retirada de corpo estranho\n(bolo alimentar). Nessas endoscopias, notavam-se estrias transversais e sulcos longitudinais em\nesôfago médio e distal. Como antecedentes, apresentava rinite e intolerância à lactose. A etiologia\nmais provável e a melhor conduta a ser adotada são, respectivamente:","options":{"A":"esofagite eosinofílica; corticoide tópico inalatório.","B":"megaesôfago idiopático; dilatação endoscópica.","C":"doença do refluxo gastroesofágico; inibidores de bomba de próton.","D":"espasmo esofagiano difuso; bloqueador de canal de cálcio."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-187547","number":"187547","sourceNumber":"187547","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente com doença pulmonar obstrutiva crônica em uso de fenoterol e fluticasona\nspray, queixa de náusea, disfagia, odinofagia\nprincipalmente quando ingere alimentos sólidos e dor\nretroesternal intermitente não relacionada a deglutição. Ao exame apresentava-se dispneico,\nausculta pulmonar com discreta sibilância, lábios cianóticos e com placas úmidas brancas aderidas\nem orofaringe. O diagnóstico provável é","options":{"A":"esofagite péptica.","B":"esofagite medicamentosa.","C":"esofagite eosinofilica.","D":"esofagite por cândida."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-174486","number":"174486","sourceNumber":"174486","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"O Tronco Celíaco. Logo abaixo do hiato diafragmático. Trifurca-se em:","options":{"A":"Artéria Gástrica Direita, Artéria Hepática Comum e Artéria Gastroduodenal.","B":"Artéria Esplênica, Artéria Hepática Direita e Artéria Gastroduodenal.","C":"Artéria Esplênica, Artéria Gástrica Esquerda e Artéria Hepática Comum.","D":"Artéria Gástrica Esquerda, Artéria Hepática e Artéria Gastroduodenal."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-174456","number":"174456","sourceNumber":"174456","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Tremores, diaforese, tonturas, taquicardia, confusão mental são sintomas encontrados\nem qual Síndrome Pós-Gastrectomia?","options":{"A":"Síndrome da Alça Eferente.","B":"Síndrome de Dumping.","C":"Síndrome da Alça Aferente.","D":"Síndrome da Alça Cega."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-187596","number":"187596","sourceNumber":"187596","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente do sexo masculino, morador do interior de Goiás, 45 anos, apresenta quadro\nde disfagia progressiva de longa data,\nemagrecimento importante, internado pelos filhos devido à\nastenia intensa e desidratação na cidade de origem em decorrência de vômitos pós prandiais\nassociados. RX de tórax com alargamento de mediastino. Sem febre associada ou prurido. Tentada\nrealização de endoscopia digestiva alta com achado de dilatação esofágica e restos alimentares.\n\nRX contrastado do esôfago evidenciando dilatação esofágica, sinal da \"ponta de lápis\", perda do\neixo anatômico e alongamento dobrando-se sobre\na cúpula diafragmática. O diagnóstico provável e\ntratamento para o quadro clínico apresentado são:","options":{"A":"megaesôfago grupo III, cirurgia de Heller-Pinotti.","B":"megasôfago grupo II, cirurgia de Nissen.","C":"câncer de esofago, esofagectomia e linfadenectomia.","D":"megasesôfago grupo IV, cirurgia de Serra-Dória."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-187597","number":"187597","sourceNumber":"187597","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente com diagnóstico de longa data de Doença do Refluxo Gastroesofágico notou\npiora dos sintomas nos últimos 3 meses e\nprocurou atendimento com gastroenterologista. Foi\nsolicitada Endoscopia Disgestiva Alta e achado endoscópico de esôfago de Barret e irregularidades\nem mucosa que foram biopsiadas segundo protocolo adequado para o caso. Anatomopatológico\nindefinido para displasia. A conduta mais adequada é","options":{"A":"cirurgia de Nissen.","B":"aumentar o uso de inibidor de bomba de prótons (IBP) para 2x ao dia e repetir endoscopia com 2\na 6 meses.","C":"manter o uso de IBP somente em jejum e repetir endoscopia com 1 ano.","D":"encaminhar ao oncologista."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-187608","number":"187608","sourceNumber":"187608","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"No caso de Esôfago de Barret se o paciente fosse encaminhado ao Cirurgião\nOncológico ou Cirurgião do Aparelho\nDigestivo por achado endoscópico de Adenocarcinoma in situ\nem área de irregularidade biopsiada a conduta adequada seria:","options":{"A":"esofagectomia segmentar com ressecção da área de lesão.","B":"revisão de lâmina com segundo patologista experiente em Barret.","C":"mucosectomia com ressecção da área de irregularidade cujo diagnóstico evidenciou Barret e\nrealizar biópsias a cada 1 cm do segmento comprometido pelo Barret.","D":"letras b e c estão corretas."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-158464","number":"158464","sourceNumber":"158464","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente do sexo masculino, 34 anos de idade, apresenta-se com dispepsia crônica. Na\nendoscopia digestiva alta é identificado piloro duplo, que tem como causa mais frequente,","options":{"A":"Origem congênita.","B":"Fístula gastroduodenal consequente à úlcera péptica.","C":"Pâncreas anular.","D":"Divertículo."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-149180","number":"149180","sourceNumber":"149180","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"O Divertículo de Zenker está localizado no:","options":{"A":"Íleo terminal.","B":"Esôfago inferior.","C":"Próximo apêndice vermiforme.","D":"Esôfago proximal."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-150252","number":"150252","sourceNumber":"150252","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"O exame radiológico constitui o método mais importante no diagnóstico da esofagopatia\nchagásica. Segundo a classificação de Rezende, o megaesôfago grupo III é definido como:","options":{"A":"esôfago com pequeno a moderado aumento do calibre. Apreciável retenção de contraste.\n\nPresença frequente de ondas terciárias, associadas ou não a hipertonia do esôfago.","B":"esôfago com grande aumento de diâmetro. Atividade motora reduzida. Hipotonia do esôfago\ninferior. Grande retenção de contraste.","C":"esôfago com diâmetro de 7 a 10 cm, sem dolicomegaesôfago, com atividade motora mínima ou\nausente.","D":"esôfago com diâmetro maior que 10 cm, com ou sem dolicomegaesôfago, com atividade motora\nmínima ou ausente."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-154649","number":"154649","sourceNumber":"154649","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A operação laparoscópica de Thal-Hatafuku tem sido empregada no tratamento do\nmegaesôfago chagásico. Em que consiste esta técnica?","options":{"A":"abertura da parede do esôfago ultrapassando o cárdia e confecção de fundoplicatura anterior.","B":"abertura da parede anterior do esôfago na junção esofagogástrica, confecção de prega valvular\ncom o bordo inferior da abertura e fechamento da abertura com o fundo gástrico.","C":"secção da musculatura da junção esofagogástrica entendendo-se cerca de 6 cm acima do cárdia\nde 2 a 3 cm distalmente ao mesmo e\nconfecção de válvula posterior a Lind.","D":"secção da musculatura da junção esofagogástrica, vagotomia troncular e confecção de\nfundoplicatura anterior.","E":"secção lateral da parede esôfago e do fundo gástrico, com anastomose laterolateral e vagotomia\ntroncular."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-154612","number":"154612","sourceNumber":"154612","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Um paciente de 64 anos, portador de megaesôfago, foi internado para tratamento\ncirúrgico. Sua manometria revela contrações no\ncorpo do esôfago com amplitude de 9mmHg,\ndilatação do órgão com conservação do eixo esofágico no esofagograma; ecocardiograma com\nfração de ejeção de 40%; eletrocardiograma com FC = 50bpm. Das alternativas a seguir, a cirurgia\nmais adequada para este caso é:","options":{"A":"esofagoplastia redutora","B":"Thal","C":"esofagectomia após passagem de marca-passo externo","D":"Serra-Dória","E":"Lewis-Tanner"},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-149194","number":"149194","sourceNumber":"149194","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"NÃO deve ser passada a sonda nasogástrica às cegas, no caso de:","options":{"A":"Queimaduras extensas.","B":"Volvo de sigmoide.","C":"Gastrectomia parcial.","D":"Esofagite por soda cáustica."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-156992","number":"156992","sourceNumber":"156992","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Homem de 55 anos apresenta dificuldade de deglutição há 11 meses para alguns\nalimentos (prefere carne moída ou picada). Nega azia ou perda de peso. Assinale o diagnóstico\nmais provável.","options":{"A":"Carcinoma de esôfago.","B":"Anel de Schatzki.","C":"Divertículo de Zenker.","D":"Síndrome de Plummer-Vinson."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-156999","number":"156999","sourceNumber":"156999","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Qual tumor gástrico associa-se com a bactéria Helicobacter pylori?","options":{"A":"Tumor carcinoide.","B":"Linfoma MALT.","C":"Adenocarcinoma.","D":"Sarcoma."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-156433","number":"156433","sourceNumber":"156433","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Marque a afirmativa correta:","options":{"A":"Parotidite epidêmica está relacionada a infecção bacteriana aguda.","B":"Os divertículos esofágicos podem ser assintomáticos.","C":"Na doença do refluxo gastresofágico o esfincter esofágico inferior está competente.","D":"A doença de Crohn se caracteriza por pangastrite."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-157304","number":"157304","sourceNumber":"157304","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Desconsiderando variações anatômicas, quais são os três ramos arteriais originados do\ntronco celíaco?","options":{"A":"Gastroduodenal, hepática comum e gástrica direita.","B":"Gastroduodenal, esplênica e gástrica esquerda.","C":"Esplênica, gástrica esquerda e hepática comum.","D":"Esplênica, hepática própria e gastroepiplóica esquerda.","E":"Hepática comum, esplênica e mesentérica superior."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-158469","number":"158469","sourceNumber":"158469","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"No megaesôfago chagásico é correto afirmar que, exceto:","options":{"A":"Na classificação de Rezende o grupo II é caracterizado por esôfago de calibre pouco\naumentado, com retenção de contraste e presença de ondas terciárias.","B":"O megaesôfago grupo IV da classificação de Rezende é caracterizado pelo alongamento do\nórgão, que dobra-se sobre a cúpula\ndiafragmática, e pelas ondas terciárias que pioram ainda mais\no\n\nquadro de disfagia.","C":"O tratamento cirúrgico no megaesôfago grupos II e III é geralmente realizado por\ncardiomiotomias associadas a valvuloplastias.","D":"No megaesôfago grupo IV é indicado a cirurgia de esofagectomia com esofagogastroplastia ou a\ncirurgia de Serra Dória."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-156511","number":"156511","sourceNumber":"156511","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"O tratamento cirúrgico para úlcera duodenal, que estatisticamente está relacionado com\nmenores taxas de recidiva, é:","options":{"A":"Vagotomia troncular com antrectomia.","B":"Vagotomia superseletiva.","C":"Vagotomia seletiva com piloroplastia.","D":"Vagotomia troncular com piloroplastia."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-127248","number":"127248","sourceNumber":"127248","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Renato, 5 anos, apresenta tumoração na linha cervical média com evolução de 6\nmeses, móvel à deglutição, indolor, sem sinais\ninflamatórios e de caráter cístico à ultrassonografia.\nO diagnostico MAIS provável é:","options":{"A":"Cisto de duplicação esofágica.","B":"Linfangioma.","C":"Teratoma.","D":"Cisto tireoglosso."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-136882","number":"136882","sourceNumber":"136882","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Com relação às úlceras gástricas, sabe-se que:","options":{"A":"as úlceras de pequena curvatura e fundo gástrico estão relacionadas à hipersecreção ácida.","B":"as úlceras de pequena curvatura próximas à incisura angularis são responsáveis por 60% das\núlceras gástricas.","C":"bebidas quentes e infecção por H. pylori são fatores de risco para o desenvolvimento de úlceras\ngástricas.","D":"doença ulcerosa péptica, hipersecração ácida e tumor de células beta das ilhotas pancreáticas\ncaracterizam a Síndrome de Zollinger-Ellison."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-127294","number":"127294","sourceNumber":"127294","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Sobre câncer esofagiano responda (V) para Verdadeiro ou (F) para Falso e assinale a\nalternativa CORRETA. ( ) 30% estão localizados no terço proximal, 50% no terço médio e 20% no\nterço distal. ( ) A DRGE predispõe a metaplasia glandular denominada esôfago de Barret. ( )\nMais da metade das neoplasias esofagianas são adenocarcinomas.","options":{"A":"F / F / V.","B":"V / V / F.","C":"F / V / F.","D":"V / F / V."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-127320","number":"127320","sourceNumber":"127320","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"No paciente com doença do refluxo gastro-esofágico, cuja manometria revela uma\natividade peristáltica de 45% e amplitude da onda\nperistáltica distal de 21 mmHg, deve-se optar por:","options":{"A":"Fundoplicatura total.","B":"Esofagogastrectomia.","C":"Fundoplicatura parcial.","D":"Gastrectomia parcial a BII."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-127693","number":"127693","sourceNumber":"127693","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente do sexo masculino, de 54 anos, coronariopata, em uso contínuo de AAS,\napresentando dor epigástrica. Foi submetido à endoscopia, que evidenciou úlcera duodenal\ncicatrizada (estágio S2 de Sakita) e teste da urease positivo. Negava tratamentos prévios para\nHelicobacter pylori. Nesse caso, a conduta mais apropriada é:","options":{"A":"Usar Inibidor de Bomba de Prótons (IBP) continuamente.","B":"Tratar o Helicobacter pylori por 14 dias e manter o AAS.","C":"Suspender o AAS e manter IBP.","D":"Tratar o Helicobacter pylori por sete dias e manter o uso de AAS e IBP continuamente."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-129862","number":"129862","sourceNumber":"129862","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente com doença pulmonar obstrutiva crônica, em uso de fluticasona spray,\napresenta náusea, disfagia, odinofagia,\nprincipalmente quando ingere alimentos sólidos, e dor\nretroesternal intermitente não relacionada à deglutição. Ao exame, apresenta-se dispneico,\nausculta pulmonar com discreta sibilância, lábios cianóticos e com placas brancas de aspecto\nalgodonoso em orofaringe. O diagnóstico mais provável para o caso é:","options":{"A":"esofagite péptica.","B":"esofagite medicamentosa.","C":"esofagite eosinofílica.","D":"esofagite por cândida."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-138616","number":"138616","sourceNumber":"138616","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Para tratamento do megaesôfago chagásico grupo III (Segundo a classificação do\nProfessor Jofre Marcondes de Resende), a\ncirurgia de Serra-Dória se destaca como uma excelente\nopção de tratamento. Esta cirurgia compreende:","options":{"A":"Miotomia extra mucosa do esôfago com fundoplicatura a ?Toupet?.","B":"Esofagectomia transdiafragmática com esofagogastroplastia.","C":"Hemi-gastrectomia com esofagogastroplastia.","D":"Antrectomia com esofagocoloplastia."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-127953","number":"127953","sourceNumber":"127953","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Ocreotida, análogo da somatostatina, tem entre suas funções reguladoras:","options":{"A":"Aceleração do esvaziamento intestinal.","B":"Estimulação das enzimas pancreáticas.","C":"Diminuição da absorção de água no tubo digestivo.","D":"Bloqueio da secreção gástrica."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-127960","number":"127960","sourceNumber":"127960","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Regurgitação de alimentos, halitose e crescente dificuldade de engolir vinham\ncausando transtornos diários em uma senhora de 75 anos. Foi-lhe sugerida uma miotomia\nendoscópica ao detectar um divertículo de esôfago, cujo lócus anatômico mais frequente é a\nregião:","options":{"A":"Hiatal","B":"Faríngea","C":"Epifrênica","D":"Mesoesofágica"},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-101149","number":"101149","sourceNumber":"101149","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A abordagem correta do paciente com suspeita de abdome agudo é de fundamental\nimportância para o diagnóstico precoce e a terapêutica eficaz. Devido à sua natureza\npotencialmente cirúrgica, uma investigação diligente é imperativa. A abordagem segue a ordem\nusual ? anamnese, exame físico, exames laboratoriais e estudos de imagem. Durante a\nabordagem, é comum o aparecimento do \"Sinal de Rigler\" na seguinte situação clínica:","options":{"A":"apendicite aguda.","B":"colecistite aguda.","C":"úlcera péptica perfurada.","D":"volvo de sigmoide."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-103650","number":"103650","sourceNumber":"103650","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A classificação de Los Angeles para esofagite, feita através de endoscopia digestiva\nalta, diz:","options":{"A":"No grau A, as lesões são maiores que 5 mm.","B":"No grau B, as lesões são menores que 5 mm.","C":"No grau C, as lesões confluem, porém, envolvem menos de 75% da circunferência do órgão.","D":"No grau D, as lesões não confluem, porém, envolvem mais de 75% da circunferência do órgão."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-102491","number":"102491","sourceNumber":"102491","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Não é achado radiológico no esofagograma de paciente com acalásia:","options":{"A":"Dilatação do esôfago em graus variados.","B":"Presença de ondas peristálticas no corpo do esôfago, em todas as fases da doença.","C":"Ausência da bolha gástrica.","D":"Retardo no esvaziamento esofágico.","E":"Estreitamento distal do esôfago com aspecto de ?bico de pássaro?."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-103689","number":"103689","sourceNumber":"103689","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Durante a deglutição, o alimento é impulsionado por meio de contrações musculares\nchamadas de ondas peristálticas que podem ser primárias, secundárias e terciárias. Assinale\nquanto a sua fisiologia.","options":{"A":"Ondas primárias são iniciadas pela deglutição.","B":"Ondas secundárias são voluntárias.","C":"Ondas terciárias são ondas fisiológicas encontradas na maioria dos pacientes.","D":"Ondas terciárias são propulsivas."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-111384","number":"111384","sourceNumber":"111384","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"É complicação possível da Doença de Refluxo Gastroesofágico (DRGE):","options":{"A":"Estenose esofágica.","B":"Úlcera esofágica.","C":"Esôfago de Barrett.","D":"Aspiração broncopulmonar.","E":"Todas as alternativas acima são complicações possíveis da DRGE."},"answer":"E","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-109297","number":"109297","sourceNumber":"109297","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"O esôfago de Barrett:","options":{"A":"Tem como únicos agentes causadores o ácido clorídrico e a pepsina do suco gástrico.","B":"Tem o diagnóstico confirmado apenas pelo exame endoscópico.","C":"Caracteriza-se por substituição do epitélio distal do esôfago por epitélio metaplásico.","D":"Apresenta risco de malignização em cerca de metade dos casos, após cinco anos."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-106713","number":"106713","sourceNumber":"106713","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Em relação a epidemiologia e fatores de risco no adenocarcinoma do esôfago, assinale\na alternativa correta.","options":{"A":"A sua incidência segundo o gênero é oito vezes maior entre os homens.","B":"A raça não parece exercer influência alguma.","C":"A sua incidência é maior na 3ª e 4ª década de vida.","D":"Nenhuma das alternativas anteriores está correta."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-109166","number":"109166","sourceNumber":"109166","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Senhor Paulo, 60 anos com queixas de refluxo gastro-esofágico, realizou endoscopia\ndigestiva alta (EDA). A EDA mostra, além da\nesofagite, presença de epitélio de Barret cuja biópsia\nrevelou metaplasia intestinal. Após tratamento clínico realizou nova endoscopia que apresentou o\nmesmo resultado. A conduta mais adequada para este paciente é:","options":{"A":"Medidas clínicas antirrefluxo e EDA se houver mudança da sintomatologia.","B":"Inibidores da bomba de prótons e EDA a cada dois anos.","C":"Ressecção endoscópica da área do Barret.","D":"Repetir a EDA com biópsia feita por outro patologista."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-110221","number":"110221","sourceNumber":"110221","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Homem de 28 anos comparece à consulta referindo pirose e dispepsia há 4 meses, que\npioram após a alimentação, com 2 a 3 episódios por semana. Nega disfagia ou alterações do hábito\nintestinal. Não possui antecedentes patológicos. Nesse caso, a conduta mais adequada é:","options":{"A":"Endoscopia digestiva alta.","B":"pHmetria esofágica.","C":"Manometria.","D":"Inibidor de bomba de prótons."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-101164","number":"101164","sourceNumber":"101164","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A atresia de esôfago é a mais frequente anomalia congênita deste órgão, acometendo\num a cada 4.000 neonatos. Cinquenta por cento\ndos lactentes têm anomalias associadas, mais\nfrequentemente relacionadas com a síndrome de:","options":{"A":"Fanconi-Bickel.","B":"Prader-Willi.","C":"prune belly.","D":"VATER."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-86342","number":"86342","sourceNumber":"86342","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Com relação ao refluxo gastroesofágico:","options":{"A":"existe uma relação inversamente proporcional entre a presença de hérnia hiatal e as formas\nmais graves de refluxo.","B":"é menos frequente em indivíduos obesos.","C":"a endoscopia digestiva alta é o método padrão-ouro para o seu diagnóstico.","D":"é mais frequente em pacientes do sexo masculino."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-83683","number":"83683","sourceNumber":"83683","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Os conhecimentos atuais da atuação do Helicobacter pylori (H. pylori) nas gastrites\ncrônicas permitem-nos afirmar que:","options":{"A":"A infecção pelo H. pylori é rara, sendo que somente em 20% dos casos é causa de gastrite\ncrônica.","B":"A fisiopatologia da lesão do H. pylori ocorre somente pela ação local direta nas células\nepiteliais.","C":"Os indivíduos com gastrite de corpo pelo H. pylori mantém a capacidade de secretar ácido e tem\nrisco aumentado de úlcera duodenal.","D":"Cerca de 90% das úlceras duodenais e 70% das úlceras gástricas estão relacionadas à infecção\npelo H. pylori.","E":"A erradicação da bactéria isoladamente não demonstrou significativa redução das úlceras em\nusuários crônicos de AAS/AINE."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-85789","number":"85789","sourceNumber":"85789","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"No Esôfago de Barrett, podemos afirmar que:","options":{"A":"O conceito atual de Esôfago de Barrett restringe-se somente à metaplasia intestinal no esôfago\ndistal.","B":"A incidência de adenocarcinoma é elevada nas metaplasias intestinais do esôfago distal e tem\naumentado nos últimos anos.","C":"O aspecto histológico da metaplasia instestinal no esôfago distal mostra células caliciformes\ntambém chamadas de células azuis quando coradas pelo corante ?alcian blue?.","D":"É consenso que o esôfago de Barrett deve ser tratado por meio de cirurgia anti-refluxo.","E":"Na presença de displasia de alto grau, é consenso que este paciente deva ser encaminhado\npara terapia por ablação com a coagulação por\nplasma de argônio."},"answer":"E","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-86378","number":"86378","sourceNumber":"86378","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Sobre a Doença do Refluxo Gastresofagiano, assinale a alternativa CORRETA:","options":{"A":"O esôfago de Barrett é uma condição benigna e assintomática, de relevância clínica pelo papel\nde lesão precursora no adenocarcinoma do esôfago.","B":"O exame inicial de escolha na avaliação de pacientes com sintomas típicos de refluxo é a\nendoscopia digestiva alta.","C":"O tratamento cirúrgico tem como objetivo abolir o refluxo gastroduodenal para o esôfago,\ninterromper a lesão contínua à mucosa\nesofagiana, além de corrigir anormalidades anatômicas,\ncomo a hérnia hiatal e a incompetência do EEI (Esfíncter Esofágico Inferior).","D":"todas anteriores corretas."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-86356","number":"86356","sourceNumber":"86356","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Sobre o megaesôfago, assinale a alternativa CORRETA:","options":{"A":"A miotomia incompleta, refluxo gastroesofágico com esofagite, fibrose ao nível da secção\nlongitudinal da musculatura da transição\nesofagogástrica, são causas de recidiva dos sintomas no\nmegaesôfago, após cardiomiotomias em qualquer técnica empregada.","B":"Na cirurgia de Serra-Dória, os tempos cirúrgicos são a de Grondahl (cardioplastia com\nesofagogastroanastomose laterolateral) e a gastrectomia Billroth II.","C":"A cirurgia de cardiomiotomia à Heller com fundoplicatura é o tratamento cirúrgico mais utilizado\ne\nadequado no tratamento do megaesôfago\ngrupo III e IV.","D":"A dilatação pneumática por endoscopia é tratamento rotineiro para o megaesôfago grupo I."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-86357","number":"86357","sourceNumber":"86357","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Sobre complicações perioperatórias na cirurgia do Refluxo Gastroesofagiano por\nvideolaparoscopia, assinale a alternativa correta:","options":{"A":"Hemotórax.","B":"Lesão esplênica.","C":"Lesão do ducto torácico.","D":"Todas as anteriores."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-85336","number":"85336","sourceNumber":"85336","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Do ponto de vista esofagomanométrico, o achado que define a Doença do Refluxo\nGastroesofágico é:","options":{"A":"relaxamento transitório interprandial do esfíncter esofagiano inferior.","B":"hipotonia do esfíncter esofagiano inferior.","C":"hipocontratilidade do corpo esofágico.","D":"espasmos esofagianos."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-85347","number":"85347","sourceNumber":"85347","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Em relação à hérnia hiatal, verifica-se que a do tipo:","options":{"A":"II é a mais comum.","B":"III, apesar de frequente, habitualmente não se complica.","C":"I, também conhecida como hérnia de rolamento, deve ser corrigida se associada à doença do\nrefluxo.","D":"II deve sempre ser considerada para o tratamento cirúrgico, devido ao risco de complicação."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-62685","number":"62685","sourceNumber":"62685","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Na investigação de um paciente com disfagia de longa data foi realizado raio X de\nesôfago que mostrou megaesôfago grupo IV (pela classificação de Rezende). Nesse caso, a\ncirurgia que oferece piores resultados com recidiva precoce dos sintomas é:","options":{"A":"Serra-Dória.","B":"Thal.","C":"Heller.","D":"Mucosectomia com gastroplastia."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-63701","number":"63701","sourceNumber":"63701","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Uma mulher de 40 anos foi avaliada no ambulatório de gastro por uma história de 7\nmeses de dispepsia, eructação e\nregurgitação líquida. Refere não ter qualquer outro sintoma\nassociado. A paciente usou omeprazol via oral por 8 semanas sem sucesso. Tem antecedente de\nhipertensão arterial e diabetes mellitus tipo 2, além de obesidade (IMC 38). Ela faz uso de\nenalapril,\nmetformina e insulina NPH. Não apresenta nenhum achado ao exame físico e a pesquisa de\nsangue oculto nas fezes é negativa. Qual das assertivas abaixo melhor descreve o próximo passo\nna investigação diagnóstica do caso clínico da paciente?","options":{"A":"Tomografia de tórax","B":"Tomografia de abdome com fase contrastada","C":"ulltrassonografia de abdome","D":"Monitorização ambulatorial de pH esofágico"},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-64600","number":"64600","sourceNumber":"64600","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente masculino, 46a, submetido à EDA por dispepsia. Achados: úlcera gástrica na\nparede anterior do antro proximal, 27 mm, bordas irregulares, revestida por espessa camada de\nfibrina e necrose, pregas convergentes roídas. Biópsias revelam úlcera péptica. Teste de urease\npositivo. Sua próxima conduta é:","options":{"A":"Verificar dosagem de CEA, CA 19-9, CA 125.","B":"Realizar ecoendoscopia: lesão hipoecogênica em planos mais profundos e linfonodos satélites\nsão indicativos de malignidade.","C":"Repetir a biópsia após 2 semanas de tratamento com IBP e erradicação de H. pylori.","D":"encaminhar a cirurgia, pois os sinais endoscópicos indicam malignidade.","E":"Tratamento com IBP por 8 semanas sem tratamento para H. pylori."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-69213","number":"69213","sourceNumber":"69213","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A doença do refluxo gastroesofágico consiste na exposição do epitélio esofágico a um\nPh baixo por longos períodos em função de um\nclareamento ineficiente e a incompetência do\nesfíncter esofageano inferior. Dentre as possibilidades de tratamento cirúrgico podemos citar,\nexceto:","options":{"A":"A fundoplicatura parcial de Lind.","B":"A esofagomiotomia à Heller com válvula de Pinotti.","C":"A fundoplicatura total de Nissen.","D":"A fundoplicatura de Toupet.","E":"Cardioplastia de Nissen."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-47634","number":"47634","sourceNumber":"47634","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Durante uma gastrectomia parcial (antrectomia), que estrutura serve de referência para\ndelimitar o antrogástrico?","options":{"A":"Artéria gástrica esquerda.","B":"Ramo de Latarjet do nervo vago.","C":"Borda superior do pâncreas.","D":"Ligamento redondo."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-53610","number":"53610","sourceNumber":"53610","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Sobre a infecção pelo Helicobacterpylori é correto afirmar que:","options":{"A":"a sorologia somente deve ser realizada em pacientes com contra-indicação à endoscopia\ndigestiva alta, e seu resultado substitui o resultado anatomo-patológico da biópsia gástrica.","B":"uso de inibidores da bomba de prótons pode estar relacionado a resultados falso-negativos do\nteste da uréase.","C":"a infecção predominante de corpo gástrico está relacionada ahipercloridria e desenvolvimento de\núlcera duodenal.","D":"em pacientes com úlcera duodenal ativa, o tratamento de erradicação da bactéria só deve ser\nrealizado após a cicatrização da úlcera com drogas antissecretoras.","E":"os exames sorológicos, por não serem invasivos, são considerados o método ideal para controle\nde cura após tratamento de erradicação da\nbactéria."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-47322","number":"47322","sourceNumber":"47322","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A pior opção para tratar um megaesôfago chagásico avançado e recidivado é:","options":{"A":"dilatações pneumáticas de repetição (com baixa pressão para evitar perfuração).","B":"esofagectomia com anastomose esofagogástrica cervical.","C":"mucosectomia do esôfago com anastomose esofagogástrica cervical.","D":"cardioplastia ampla + antrectomia (ou hemigastrectomia) com reconstrução em Y de Roux +\nvagotomia troncular.","E":"operação de Thal-Hatafuku."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-49024","number":"49024","sourceNumber":"49024","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Ingestão de soda Cáustica: quais as medidas iniciais e o momento da endoscopia\ndigestiva alta?","options":{"A":"As substâncias corrosivas nas formas: sólida ou líquida costumam causar principalmente lesões\nem cavidade oral, poupando o esôfago e mais grave no estômago; devendo a endoscopia ser\nsolicitada de imediato.","B":"A endoscopia digestiva alta precoce nas lesões por soda cáustica é essencial, pois os achados\nendoscópicos predizem exatamente a profundidade do tecido lesado, porém, não orienta a\nterapêutica inicial.","C":"O exame endoscópico é importante para o diagnóstico como também para a administração\nprecoce de neutralizadores ácidos evitando\nassim a perfuração do aparelho digestivo.","D":"Nas crianças com ingestão de soda cáustica a endoscopia digestiva alta só deve ser feita do\nquinto ao décimo quinto dia após a ingestão, devido ao menor risco de perfuração.","E":"Apesar de controverso a endoscopia dentro de 12 a 14 horas após a ingestão de soda cáustica\né necessária para a documentação da extensão do\ndano e acompanhamento clínico, já que 80%\ndos estreitamentos ocorrem dentro das primeiras oito semanas."},"answer":"E","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-48878","number":"48878","sourceNumber":"48878","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Nos adenocarcinomas de esôfago distal é correto afirmar:","options":{"A":"Todos os adenocarcinomas de esôfago distal surgem a partir do esôfago de Barrett.","B":"À semelhança do que acontece com o carcinoma espinocelular do esôfago, o paciente dá\nentrada no serviço de cirurgia em estado geral muito precário.","C":"A obesidade e o fumo são considerados fatores de risco para o adenocarcinoma do esôfago\ndistal.","D":"O adenocarcinoma do esôfago distal é considerado um câncer gástrico com invasão da\ntransição esofagogástrica.","E":"Nenhuma das alternativas é correta."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-48834","number":"48834","sourceNumber":"48834","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Na esofagopatia chagásica é correto afirmar:","options":{"A":"A fisiopatologia da doença é desencadeada principalmente pela destruição pelo parasito do\nsistema nervoso autônomo parassimpático.","B":"A acalasia consiste na hipertonia do esfíncter inferior do esôfago que impede o trânsito do bolo\nalimentar do esôfago para o estômago.","C":"Há necessidade de maior destruição dos neurônios do plexo nervoso intramural do esôfago para\no desencadear da esofagopatia do que do cólon\npara o desencadear da colopatia.","D":"Em geral, no megaesôfago grupo I na classificação de Rezende, existe coluna de bário\npreenchendo todo o esôfago até o terço superior.","E":"Nenhuma das alternativas é correta."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-34001","number":"34001","sourceNumber":"34001","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente com 45 anos, tabagista, usuário crônico de anti-inflamatórios não esteroidais\n(AINE) para artrite reumatoide, iniciou há 24\nhoras quadro de melena e epigastralgia intensa. Foi\nsubmetido a endoscopia digestiva alta, que evidenciou uma úlcera duodenal de 1,5 cm, profunda, e\nem seu fundo mínimo sangramento ?em babação?. A hemostasia endoscópica da lesão foi\nrealizada com sucesso. Nesse caso, qual a melhor conduta a seguir?","options":{"A":"Suspender o AINE, pesquisar o Helicobacter pylori e, se positivo, iniciar de imediato o\ntratamento\npara a sua erradicação.","B":"Manter o AINE, iniciar com inibidor de bomba por via oral, e pesquisar o Helicobacter pylori.","C":"Suspender o AINE, iniciar com inibidor de bomba por via oral, e pesquisar o Helicobacter pylori.","D":"Suspender o AINE, iniciar com inibidor de bomba endovenoso e pesquisar o Helicobacter pylori."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-22972","number":"22972","sourceNumber":"22972","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A doença do refluxo gastroesofágico deve ser tratada cirurgicamente nos pacientes\nportadores de:","options":{"A":"asma brônquica e esofagite edematosa.","B":"rouquidão com pressão média ao nível do esfíncter inferior do esôfago de 14 mmHg.","C":"estenoses pépticas do esôfago e dependentes do uso de inibidores de bomba protônica.","D":"hérnia hiatal do tipo I e esofagite erosiva."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-22987","number":"22987","sourceNumber":"22987","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"O principal mecanismo de ocorrência de episódios de refluxo gastroesofágico em\npacientes sem hérnia hiatal é:","options":{"A":"aumento acentuado da pressão intra-abdominal.","B":"relaxamento transitório do esfíncter esofagiano inferior.","C":"aumento do volume do conteúdo intragástrico.","D":"hipotensão do esfíncter esofagiano inferior."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-22989","number":"22989","sourceNumber":"22989","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"A infecção gástrica pelo H.pylori induz alterações na secreção gástrica de ácido e na\nmucosa gástrica que se relacionam a diferentes\ndesfechos clínicos. Dessa forma,","options":{"A":"a úlcera duodenal se associa a hipersecreção ácida e pangastrite atrófica.","B":"o câncer gástrico se associa a acidez gástrica normal e gastrite predominantemente antral.","C":"a úlcera duodenal se associa a hipossecreção ácida e gastrite predominantemente antral.","D":"o câncer gástrico se associa a hipossecreção ácida e pangastrite atrófica."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-27153","number":"27153","sourceNumber":"27153","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Qual dos medicamentos abaixo tem o menor potencial de agressão do estômago?","options":{"A":"AAS","B":"Piroxican","C":"Naproxeno","D":"Indometacina","E":"Ibuprofeno"},"answer":"E","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-27155","number":"27155","sourceNumber":"27155","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"No tratamento das manifestações atípicas da Doença do Refluxo Gastroesofágico\n(DRGE) qual a melhor conduta:","options":{"A":"Iniciar bloqueadores H2 passando para Inibidores da Bomba Protônica (IBP) caso não se\nobtenha resposta clinica satisfatória.","B":"Iniciar IBP em dose plena dobrando-se a dose caso não se obtenha resposta clínica satisfatória.","C":"Iniciar com IBP em dose dupla, adiministrando-se antes das refeições, por um período mínimo\nde 12 semanas.","D":"Iniciar com Bloqueador H2 associado a procinético.","E":"Iniciar com IBP em dose plena associado a procinético."},"answer":"C","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-27162","number":"27162","sourceNumber":"27162","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente do sexo masculino, 37 anos de idade, apresenta-se com dispepsia crônica do\ntipo ulcerosa. Na endoscopia digestiva alta apresenta piloro duplo. A causa mais frequente é:","options":{"A":"Congênita.","B":"Fístula gastroduodenal consequente à úlcera péptica.","C":"Pâncreas anular.","D":"Latrogenia.","E":"Divertículo."},"answer":"B","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-8991","number":"8991","sourceNumber":"8991","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Em relação a esofagite por ingestão de agentes corrosivos é correto afirmar que:","options":{"A":"80% dos pacientes que fazem ingestão de agentes corrosivos são adultos com idade superior a\n40 anos.","B":"90% das lesões são causadas por álcalis fortes.","C":"quanto maior a concentração e o volume ingerido menor é o dano celular na parede esofagiana.","D":"o exame endoscópico correlaciona grau da lesão e prognóstico com avaliação da possibilidade\nde progressão para estenose cicatricial, mas não é\nindicado na fase aguda da esofagite química."},"answer":"D","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-02-273966","number":"273966","sourceNumber":"273966","collectionBlock":"med:med-cirurgia-med-cir-02","collectionLabel":"MED · MED CIR 02","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 02","subtopic":"","stem":"Paciente do sexo masculino, 35 anos de idade, com história de disfagia progressiva e\nperda de peso (19 kg) há três meses. Nega\nhistória de doença do refluxo gastresofagiano, doença\nde Chagas, tabagismo e etilismo. Realizou endoscopia digestiva alta que evidenciou dilatação\nesofágica, porém ausência de tumores ou ulcerações esofagogástricas e sem aparente\ncompressão extrínseca do esôfago. Em relação aos métodos diagnósticos e manejo de acalásia,\nmarque \"V\" para Verdadeiro e \"F\" para Falso: ( ) Os achados clássicos na seriografia\nesofagogástrica nos pacientes com acalásia são o afunilamento distal do esôfago (lesão em \"bico\nde pássaro\") e dilatação proximal do órgão e, nos casos mais avançados, aparência de sigmoide\ncom estase alimentar. ( ) Segundo a classificação de Chicago para acalásia esofágica, os pacientes\nestratificados como tipo III apresentam melhores resultados com a miotomia cirúrgica que com a\nmiotomia endoscópica peroral. ( ) O quadro manométrico clássico é caracterizado pela\nincapacidade de relaxamento do esfíncter inferior do esôfago durante a deglutição e aperistalse\nesofágica. ( ) A cirurgia de Heller para o tratamento da acalásia é caracterizada pela realização de\numa miotomia esofagogástrica associada à hiatoplastia diafragmática e à confecção de uma válvula\nantirrefluxo de 360° envolvendo o esôfago distal. Assinale a sequência CORRETA:","options":{"A":"V - F - V - F.","B":"F - F - F - V.","C":"V - F - V - V.","D":"F - V - F - F."},"answer":"A","source":"Cirurgia/MED CIR 02/MED CIR 02.txt","sourceLabel":"MED · MED CIR 02","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 02","MED"],"answerSource":"explicit","commentDeferred":true}]};
